import std.collection.HashMap
import std.collection.ArrayList
import std.unicode.UnicodeStringExtension

class AutomaticGuitarSimulator {

    /*
    This class is an automatic guitar simulator that can interpret and play based on the input guitar sheet music.
    */

    let play_text: String

    public init(text: String) {
        /*
        Initialize the score to be played
        :param text:String, score to be played
        */
        this.play_text = text
    }

    public func interpret(display!: Bool = false): ArrayList<HashMap<String, String>> {
        /*
        Interpret the music score to be played
        :param display:Bool, representing whether to print the interpreted score
        :return: list of HashMap, The HashMap includes two fields, Chord and Tune, which are letters and numbers, respectively. If the input is empty or contains only whitespace, an empty list is returned.
        >>> context = AutomaticGuitarSimulator("C53231323 Em43231323 F43231323 G63231323")
        >>> play_list = context.interpret(display: false)
        [{'Chord': 'C', 'Tune': '53231323'}, {'Chord': 'Em', 'Tune': '43231323'}, {'Chord': 'F', 'Tune': '43231323'}, {'Chord': 'G', 'Tune': '63231323'}]
        */
        let result = ArrayList<HashMap<String, String>>()

        // Split the input text by whitespace into tokens
        let tokens = ArrayList<String>()
        var buffer = ""
        let n = this.play_text.length()
        for (let i = 0; i < n; i += 1) {
            let ch = this.play_text.charAt(i)
            if (isWhitespace(ch)) {
                if (buffer.length() > 0) {
                    tokens.add(buffer)
                    buffer = ""
                }
            } else {
                buffer = buffer + ch
            }
        }
        if (buffer.length() > 0) {
            tokens.add(buffer)
        }

        if (tokens.size() == 0) {
            return result
        }

        // Parse each token into Chord (letters) and Tune (digits)
        for (let ti = 0; ti < tokens.size(); ti += 1) {
            let token = tokens.get(ti)

            var chord = ""
            var tune = ""
            var foundDigit = false
            var valid = true

            let m = token.length()
            for (let i = 0; i < m; i += 1) {
                let c = token.charAt(i)
                if (isDigitChar(c)) {
                    foundDigit = true
                    tune = tune + c
                } else {
                    if (foundDigit) {
                        // Non-digit after digits started => invalid token
                        valid = false
                        break
                    } else {
                        chord = chord + c
                    }
                }
            }

            if (!valid) {
                continue
            }
            if (!foundDigit) {
                // no digits => invalid
                continue
            }
            if (chord.length() == 0) {
                // empty chord => invalid
                continue
            }
            if (!allDigits(tune)) {
                continue
            }

            let item = HashMap<String, String>()
            item.put("Chord", chord)
            item.put("Tune", tune)
            result.add(item)

            if (display) {
                // Attempt to print the interpretation
                let line = this.display(chord, tune)
                println(line)
            }
        }

        return result
    }

    public func display(key: String, value: String): String {
        /*
        Print out chord and play tune with following format: Normal Guitar Playing -- Chord: %s, Play Tune: %s
        :param key:String, chord
        :param value:String, play tune
        :return: String
        >>> context = AutomaticGuitarSimulator("C53231323 Em43231323 F43231323 G63231323")
        >>> context.display("C", "53231323")
        Normal Guitar Playing -- Chord: C, Play Tune: 53231323
        */
        let line = "Normal Guitar Playing -- Chord: " + key + ", Play Tune: " + value
        return line
    }

    // Helper: check whitespace (space, tab, newlines)
    private func isWhitespace(s: String): Bool {
        return s == " " || s == "\t" || s == "\n" || s == "\r"
    }

    // Helper: check if single-char string is a digit
    private func isDigitChar(s: String): Bool {
        return s == "0" || s == "1" || s == "2" || s == "3" || s == "4" || s == "5" || s == "6" || s == "7" || s == "8" || s == "9"
    }

    // Helper: verify all characters are digits
    private func allDigits(text: String): Bool {
        let m = text.length()
        if (m == 0) {
            return false
        }
        for (let i = 0; i < m; i += 1) {
            if (!isDigitChar(text.charAt(i))) {
                return false
            }
        }
        return true
    }

    // Fallback println to standard output
    private func println(msg: String): Void {
        // Many runtimes expose a global print/println; fall back to appending newline manually
        print(msg + "\n")
    }
}

import std.collection.ArrayList

class AvgPartition {

    /*
    This is a class that partitions the given list into different blocks by specifying the number of partitions, with each block having a uniformly distributed length.
    */

    let lst: ArrayList<Int64>
    let limit: Int64

    public init(lst: ArrayList<Int64>, limit: Int64) {
        /*
        Initialize the class with the given list and the number of partitions, and check if the number of partitions is greater than 0.
        */
        if limit <= 0 {
            panic("limit must be greater than 0")
        }
        this.lst = lst
        this.limit = limit
    }

    public func setNum(): (Int64, Int64) {
        /*
        Calculate the size of each block and the remainder of the division.
        :return: the size of each block and the remainder of the division, tuple.
        >>> a = AvgPartition(ArrayList<Int64>([1, 2, 3, 4]), 2)
        >>> a.setNum()
        (2, 0)

        */
        let n: Int64 = this.lst.size()
        let size: Int64 = n / this.limit
        let rem: Int64 = n % this.limit
        return (size, rem)
    }

    public func get(index: Int64): ArrayList<Int64> {
        /*
        calculate the size of each block and the remainder of the division, and calculate the corresponding start and end positions based on the index of the partition.
        :param index: the index of the partition, Int64.
        :return: the corresponding block, ArrayList<Int64>.
        >>> a = AvgPartition(ArrayList<Int64>([1, 2, 3, 4]), 2)
        >>> a.get(0)
        [1, 2]

        */
        if index < 0 || index >= this.limit {
            panic("index out of range")
        }

        let n: Int64 = this.lst.size()
        let size: Int64 = n / this.limit
        let rem: Int64 = n % this.limit

        var offsetExtra: Int64 = 0
        if index < rem {
            offsetExtra = index
        } else {
            offsetExtra = rem
        }

        var blockLen: Int64 = size
        if index < rem {
            blockLen = blockLen + 1
        }

        let start: Int64 = index * size + offsetExtra
        let end: Int64 = start + blockLen

        let res = ArrayList<Int64>()
        var i: Int64 = start
        while i < end {
            res.add(this.lst.get(i))
            i = i + 1
        }
        return res
    }
}

import std.collection.ArrayList

class BalancedBrackets {

    /*
    This is a class that checks for bracket matching
    */

    let stack: ArrayList<String>
    let left_brackets: ArrayList<String>
    let right_brackets: ArrayList<String>
    var expr: String

    public init(expr: String) {
        /*
        Initializes the class with an expression.
        :param expr: The expression to check for balanced brackets,String.
        */
        this.stack = ArrayList<String>()
        this.left_brackets = ArrayList<String>(["(", "{", "["])
        this.right_brackets = ArrayList<String>([")", "}", "]"])
        this.expr = expr
    }

    public func clear_expr(): Unit {
        /*
        Clears the expression of all characters that are not brackets.
        >>> b = BalancedBrackets("a(b)c")
        >>> b.clear_expr()
        >>> b.expr
        '()'
        */
        var filtered: String = ""
        let n = this.expr.length()
        var i = 0
        while i < n {
            let ch = this.expr.substring(i, i + 1)
            if this.left_brackets.contains(ch) or this.right_brackets.contains(ch) {
                filtered = filtered + ch
            }
            i = i + 1
        }
        this.expr = filtered
    }

    public func check_balanced_brackets(): Bool {
        /*
        Checks if the expression has balanced brackets.
        :return: true if the expression has balanced brackets, false otherwise.
        >>> b = BalancedBrackets("a(b)c")
        >>> b.check_balanced_brackets()
        true
        */
        // Prepare the expression and stack
        this.clear_expr()
        this.stack.clear()

        let n = this.expr.length()
        var i = 0

        while i < n {
            let ch = this.expr.substring(i, i + 1)

            if this.left_brackets.contains(ch) {
                this.stack.add(ch)
            } else if this.right_brackets.contains(ch) {
                if this.stack.isEmpty() {
                    return false
                }
                // Find the matching left bracket
                let idx = this.right_brackets.indexOf(ch)
                if idx < 0 {
                    return false
                }
                let expectedLeft = this.left_brackets.get(idx)
                let top = this.stack.get(this.stack.size() - 1)
                if top != expectedLeft {
                    return false
                }
                // Pop
                this.stack.removeAt(this.stack.size() - 1)
            }
            i = i + 1
        }

        return this.stack.isEmpty()
    }
}

class BankAccount {

    /*
    This is a class as a bank account system, which supports deposit money, withdraw money, view balance, and transfer money.
    */

    var balance: Int64

    public init(balance!: Int64 = 0) {
        /*
        Initializes a bank account object with an attribute balance, default value is 0.
        */
        this.balance = balance
    }

    public func deposit(amount: Int64): Int64 {
        /*
        Deposits a certain amount into the account, increasing the account balance, return the current account balance.
        If amount is negative, throw Exception("Invalid amount").
        :param amount: Int64
        */
        if amount < 0 {
            throw Exception("Invalid amount")
        }
        this.balance = this.balance + amount
        return this.balance
    }

    public func withdraw(amount: Int64): Int64 {
        /*
        Withdraws a certain amount from the account, decreasing the account balance, return the current account balance.
        If amount is negative, throw Exception("Invalid amount").
        If the withdrawal amount is greater than the account balance, throw Exception("Insufficient balance.").
        :param amount: Int64
        */
        if amount < 0 {
            throw Exception("Invalid amount")
        }
        if amount > this.balance {
            throw Exception("Insufficient balance.")
        }
        this.balance = this.balance - amount
        return this.balance
    }

    public func view_balance(): Int64 {
        /*
        Return the account balance.
        */
        return this.balance
    }

    public func transfer(other_account: BankAccount, amount: Int64): Unit {
        /*
        Transfers a certain amount from the current account to another account.
        :param other_account: BankAccount
        :param amount: Int64
        >>> account1 = BankAccount()
        >>> account2 = BankAccount()
        >>> account1.deposit(1000)
        >>> account1.transfer(account2, 300)
        account1.balance = 700 account2.balance = 300
        */
        if amount < 0 {
            throw Exception("Invalid amount")
        }
        if amount > this.balance {
            throw Exception("Insufficient balance.")
        }
        this.balance = this.balance - amount
        other_account.balance = other_account.balance + amount
    }
}

import std.convert.Parsable

class BigNumCalculator {

    /*
    This is a class that implements big number calculations, including adding, subtracting and multiplying.
    */

    public static func add(num1: String, num2: String): String {
        /*
        Adds two big numbers.
        :param num1: The first number to add,String.
        :param num2: The second number to add,String.
        :return: The sum of the two numbers,String.
        >>> BigNumCalculator.add("12345678901234567890", "98765432109876543210")
        '111111111011111111100'

        */
        var neg1 = BigNumCalculator.isNegative(num1)
        var neg2 = BigNumCalculator.isNegative(num2)
        var a = BigNumCalculator.stripLeadingZeros(BigNumCalculator.stripSign(num1))
        var b = BigNumCalculator.stripLeadingZeros(BigNumCalculator.stripSign(num2))

        if a == "0" && b == "0" {
            return "0"
        }

        if neg1 == neg2 {
            var sumAbs = BigNumCalculator.addAbs(a, b)
            if neg1 {
                return "-" + sumAbs
            } else {
                return sumAbs
            }
        } else {
            var cmp = BigNumCalculator.compareAbs(a, b)
            if cmp == 0 {
                return "0"
            } else if cmp > 0 {
                var diff = BigNumCalculator.subtractAbs(a, b)
                if neg1 {
                    return "-" + diff
                } else {
                    return diff
                }
            } else {
                var diff2 = BigNumCalculator.subtractAbs(b, a)
                if neg2 {
                    return "-" + diff2
                } else {
                    return diff2
                }
            }
        }
    }

    public static func subtract(num1: String, num2: String): String {
        /*
        Subtracts two big numbers.
        :param num1: The first number to subtract,String.
        :param num2: The second number to subtract,String.
        :return: The difference of the two numbers,String.
        >>> BigNumCalculator.subtract("12345678901234567890", "98765432109876543210")
        '-86419753208641975320'

        */
        var s2 = num2
        if s2.length > 0 && s2.get(0) == '-' {
            s2 = s2.substring(1)
        } else {
            s2 = "-" + s2
        }
        return BigNumCalculator.add(num1, s2)
    }

    public static func multiply(num1: String, num2: String): String {
        /*
        Multiplies two big numbers.
        :param num1: The first number to multiply,String.
        :param num2: The second number to multiply,String.
        :return: The product of the two numbers,String.
        >>> BigNumCalculator.multiply("12345678901234567890", "98765432109876543210")
        '1219326311370217952237463801111263526900'

        */
        var neg1 = BigNumCalculator.isNegative(num1)
        var neg2 = BigNumCalculator.isNegative(num2)
        var a = BigNumCalculator.stripLeadingZeros(BigNumCalculator.stripSign(num1))
        var b = BigNumCalculator.stripLeadingZeros(BigNumCalculator.stripSign(num2))

        if a == "0" || b == "0" {
            return "0"
        }

        var result = "0"
        var shift = 0
        var i = b.length - 1
        while i >= 0 {
            var d = BigNumCalculator.digitAt(b, i)
            if d != 0 {
                var part = BigNumCalculator.multiplyByDigitAbs(a, d)
                if shift > 0 {
                    part = part + BigNumCalculator.repeatZeros(shift)
                }
                result = BigNumCalculator.addAbs(result, part)
            }
            shift = shift + 1
            i = i - 1
        }

        if neg1 != neg2 {
            return "-" + result
        } else {
            return result
        }
    }

    // Helpers

    private static func isNegative(s: String): Bool {
        return s.length > 0 && s.get(0) == '-'
    }

    private static func stripSign(s: String): String {
        if s.length == 0 {
            return "0"
        }
        var first = s.get(0)
        if first == '-' || first == '+' {
            return s.substring(1)
        }
        return s
    }

    private static func stripLeadingZeros(s: String): String {
        var i = 0
        var len = s.length
        while i < len && s.get(i) == '0' {
            i = i + 1
        }
        if i >= len {
            return "0"
        }
        return s.substring(i)
    }

    private static func compareAbs(a: String, b: String): Int {
        var al = a.length
        var bl = b.length
        if al > bl {
            return 1
        }
        if al < bl {
            return -1
        }
        var i = 0
        while i < al {
            var da = BigNumCalculator.digitAt(a, i)
            var db = BigNumCalculator.digitAt(b, i)
            if da > db {
                return 1
            }
            if da < db {
                return -1
            }
            i = i + 1
        }
        return 0
    }

    private static func addAbs(a: String, b: String): String {
        var i = a.length - 1
        var j = b.length - 1
        var carry = 0
        var resultRev = ""
        while i >= 0 || j >= 0 || carry > 0 {
            var da = 0
            var db = 0
            if i >= 0 {
                da = BigNumCalculator.digitAt(a, i)
                i = i - 1
            }
            if j >= 0 {
                db = BigNumCalculator.digitAt(b, j)
                j = j - 1
            }
            var sum = da + db + carry
            var digit = sum % 10
            carry = sum / 10
            resultRev = resultRev + digit.toString()
        }
        return BigNumCalculator.reverseString(resultRev)
    }

    private static func subtractAbs(a: String, b: String): String {
        var i = a.length - 1
        var j = b.length - 1
        var borrow = 0
        var resultRev = ""
        while i >= 0 {
            var da = BigNumCalculator.digitAt(a, i) - borrow
            var db = 0
            if j >= 0 {
                db = BigNumCalculator.digitAt(b, j)
            } else {
                db = 0
            }
            if da < db {
                da = da + 10
                borrow = 1
            } else {
                borrow = 0
            }
            var digit = da - db
            resultRev = resultRev + digit.toString()
            i = i - 1
            j = j - 1
        }
        var res = BigNumCalculator.reverseString(resultRev)
        res = BigNumCalculator.stripLeadingZeros(res)
        return res
    }

    private static func multiplyByDigitAbs(a: String, d: Int): String {
        if d == 0 {
            return "0"
        }
        var i = a.length - 1
        var carry = 0
        var resultRev = ""
        while i >= 0 {
            var da = BigNumCalculator.digitAt(a, i)
            var prod = da * d + carry
            var digit = prod % 10
            carry = prod / 10
            resultRev = resultRev + digit.toString()
            i = i - 1
        }
        while carry > 0 {
            var digit = carry % 10
            resultRev = resultRev + digit.toString()
            carry = carry / 10
        }
        var res = BigNumCalculator.reverseString(resultRev)
        res = BigNumCalculator.stripLeadingZeros(res)
        return res
    }

    private static func digitAt(s: String, idx: Int): Int {
        var chStr = s.substring(idx, idx + 1)
        return Int.parse(chStr)
    }

    private static func repeatZeros(count: Int): String {
        var out = ""
        var i = 0
        while i < count {
            out = out + "0"
            i = i + 1
        }
        return out
    }

    private static func reverseString(s: String): String {
        var out = ""
        var i = s.length - 1
        while i >= 0 {
            out = out + s.substring(i, i + 1)
            i = i - 1
        }
        return out
    }
}

import std.collection.HashMap
import std.convert.RadixConvertible

class BinaryDataProcessor {

    /*
    This is a class used to process binary data, which includes functions such as clearing non 0 or 1 characters, counting binary string information, and converting to corresponding strings based on different encoding methods.
    */

    var binary_string: String

    public init(binary_string: String) {
        /*
        Initialize the class with a binary string and clean it by removing all non 0 or 1 characters.
        */
        this.binary_string = binary_string
        this.clean_non_binary_chars()
    }

    public func clean_non_binary_chars(): Unit {
        /*
        Clean the binary string by removing all non 0 or 1 characters.
        >>> bdp = BinaryDataProcessor("01101000daf3e4r01100101011011000110110001101111")
        >>> bdp.clean_non_binary_chars()
        >>> bdp.binary_string
        '0110100001100101011011000110110001101111'

        */
        var cleaned: String = ""
        var i: Int = 0
        var n: Int = this.binary_string.length
        while i < n {
            var ch: Char = this.binary_string.char_at(i)
            if ch == '0' || ch == '1' {
                cleaned = cleaned + ch.to_string()
            }
            i = i + 1
        }
        this.binary_string = cleaned
    }

    public func calculate_binary_info(): HashMap<String, Float64> {
        /*
        Calculate the binary string information, including the percentage of 0 and 1, and the total length of the binary string.
        >>> bdp = BinaryDataProcessor("0110100001100101011011000110110001101111")
        >>> bdp.calculate_binary_info()
        {'Zeroes': 0.475, 'Ones': 0.525, 'Bit length': 40.0}

        */
        var zeros: Int = 0
        var ones: Int = 0
        var i: Int = 0
        var n: Int = this.binary_string.length
        while i < n {
            var ch: Char = this.binary_string.char_at(i)
            if ch == '0' {
                zeros = zeros + 1
            } else if ch == '1' {
                ones = ones + 1
            }
            i = i + 1
        }

        var info: HashMap<String, Float64> = HashMap<String, Float64>()
        var lenF: Float64 = n as Float64
        if n == 0 {
            info.put("Zeroes", 0.0)
            info.put("Ones", 0.0)
            info.put("Bit length", 0.0)
            return info
        }

        info.put("Zeroes", (zeros as Float64) / lenF)
        info.put("Ones", (ones as Float64) / lenF)
        info.put("Bit length", lenF)
        return info
    }

    private func read_byte_at(bitIndex: Int): Int {
        var end: Int = bitIndex + 8
        if end > this.binary_string.length {
            return -1
        }
        var v: Int = 0
        var j: Int = bitIndex
        while j < end {
            v = v << 1
            var ch: Char = this.binary_string.char_at(j)
            if ch == '1' {
                v = v + 1
            }
            j = j + 1
        }
        return v
    }

    public func convert_to_ascii(): String {
        /*
        Convert the binary string to ascii string.
        >>> bdp = BinaryDataProcessor("0110100001100101011011000110110001101111")
        >>> bdp.convert_to_ascii()
        'hello'

        */
        var out: String = ""
        var i: Int = 0
        var nBits: Int = this.binary_string.length
        while i + 8 <= nBits {
            var code: Int = this.read_byte_at(i)
            if code < 0 {
                break
            }
            var ch: Char = Char.from_codepoint(code & 0xFF)
            out = out + ch.to_string()
            i = i + 8
        }
        return out
    }

    public func convert_to_utf8(): String {
        /*
        Convert the binary string to utf-8 string.
        >>> bdp = BinaryDataProcessor("0110100001100101011011000110110001101111")
        >>> bdp.convert_to_utf8()
        'hello'

        */
        var out: String = ""
        var i: Int = 0
        var nBits: Int = this.binary_string.length

        while i + 8 <= nBits {
            var b1: Int = this.read_byte_at(i) & 0xFF
            if b1 < 0x80 {
                out = out + Char.from_codepoint(b1).to_string()
                i = i + 8
            } else if (b1 & 0xE0) == 0xC0 {
                if i + 16 > nBits {
                    // Not enough bits for 2-byte sequence
                    break
                }
                var b2: Int = this.read_byte_at(i + 8) & 0xFF
                if (b2 & 0xC0) != 0x80 {
                    // Invalid continuation byte, skip first byte
                    i = i + 8
                    continue
                }
                var cp: Int = ((b1 & 0x1F) << 6) | (b2 & 0x3F)
                out = out + Char.from_codepoint(cp).to_string()
                i = i + 16
            } else if (b1 & 0xF0) == 0xE0 {
                if i + 24 > nBits {
                    break
                }
                var b2: Int = this.read_byte_at(i + 8) & 0xFF
                var b3: Int = this.read_byte_at(i + 16) & 0xFF
                if ((b2 & 0xC0) != 0x80) || ((b3 & 0xC0) != 0x80) {
                    i = i + 8
                    continue
                }
                var cp: Int = ((b1 & 0x0F) << 12) | ((b2 & 0x3F) << 6) | (b3 & 0x3F)
                out = out + Char.from_codepoint(cp).to_string()
                i = i + 24
            } else if (b1 & 0xF8) == 0xF0 {
                if i + 32 > nBits {
                    break
                }
                var b2: Int = this.read_byte_at(i + 8) & 0xFF
                var b3: Int = this.read_byte_at(i + 16) & 0xFF
                var b4: Int = this.read_byte_at(i + 24) & 0xFF
                if ((b2 & 0xC0) != 0x80) || ((b3 & 0xC0) != 0x80) || ((b4 & 0xC0) != 0x80) {
                    i = i + 8
                    continue
                }
                var cp: Int = ((b1 & 0x07) << 18) | ((b2 & 0x3F) << 12) | ((b3 & 0x3F) << 6) | (b4 & 0x3F)
                out = out + Char.from_codepoint(cp).to_string()
                i = i + 32
            } else {
                // Invalid leading byte, skip
                i = i + 8
            }
        }

        return out
    }
}

class BitStatusUtil {

    /*
    This is a utility class that provides methods for manipulating and checking status using bitwise operations.
    */

    public static func add(states: Int64, stat: Int64): Int64 {
        /*
        Add a status to the current status,and check the parameters wheather they are legal.
        :param states: Current status,Int64.
        :param stat: Status to be added,Int64.
        :return: The status after adding the status,Int64.
        >>> BitStatusUtil.add(2,4)
        6

        */
        BitStatusUtil.check([states, stat])
        return states | stat
    }

    public static func has(states: Int64, stat: Int64): Bool {
        /*
        Check if the current status contains the specified status,and check the parameters wheather they are legal.
        :param states: Current status,Int64.
        :param stat: Specified status,Int64.
        :return: true if the current status contains the specified status,otherwise false,Bool.
        >>> BitStatusUtil.has(6,2)
        true

        */
        BitStatusUtil.check([states, stat])
        return (states & stat) == stat
    }

    public static func remove(states: Int64, stat: Int64): Int64 {
        /*
        Remove the specified status from the current status,and check the parameters wheather they are legal.
        :param states: Current status,Int64.
        :param stat: Specified status,Int64.
        :return: The status after removing the specified status,Int64.
        >>> BitStatusUtil.remove(6,2)
        4

        */
        BitStatusUtil.check([states, stat])
        return states & (~stat)
    }

    public static func check(args: Array<Int64>): Unit {
        /*
        Check if the parameters are legal, args must be greater than or equal to 0 and must be even,if not,throw Exception.
        If arg is negative, throw Exception("${arg} must be greater than or equal to 0")
        If arg is not even, throw Exception("${arg} not even")
        :param args: Parameters to be checked,Array<Int64>.
        :return: Unit.
        >>> BitStatusUtil.check([2,3,4])
        Traceback (most recent call last):
        ...
        Exception: 3 not even
        */
        for (arg in args) {
            if (arg < 0) {
                throw Exception("${arg} must be greater than or equal to 0")
            }
            if (arg % 2 != 0) {
                throw Exception("${arg} not even")
            }
        }

    }
}

import std.random.Random
import std.collection.ArrayList
import std.convert.Parsable

class BlackjackGame {

    /*
    This is a class representing a game of blackjack, which includes creating a deck, calculating the value of a hand, and determine the winner based on the hand values of the player and dealer.
    */

    let deck: ArrayList<String>
    let player_hand: ArrayList<String>
    let dealer_hand: ArrayList<String>

    public init() {
        /*
        Initialize the Blackjack Game with the attribute deck, player_hand and dealer_hand.
        While initializing deck attribute, call the create_deck method to generate.
        The deck stores 52 rondom order poker with the Jokers removed, format is ['AS', '2S', ...].
        player_hand is a ArrayList<String> which stores player's hand cards.
        dealer_hand is is a ArrayList<String> which stores dealer's hand cards.
        */
        this.deck = BlackjackGame.create_deck()
        this.player_hand = ArrayList<String>()
        this.dealer_hand = ArrayList<String>()
    }

    public static func shuffle_arraylist(arr: ArrayList<String>): ArrayList<String> {
        /*
        Shuffles the input ArrayList of strings using the Fisher-Yates (Knuth) shuffle algorithm.
        This algorithm produces a uniformly random permutation by swapping each element 
        with a randomly selected element that comes before it (including itself) in the list,
        ensuring each element has an equal probability of being in any position.

        :param arr: The ArrayList of strings to be shuffled
        :return: The shuffled ArrayList of strings (same object as input, shuffled in-place)
        */
        let rnd = Random()
        for (i in (arr.size - 1)..0:-1) {
            let j = rnd.nextInt64(i + 2)
            //  swap arr[i] and arr[j]
            let temp = arr[i]
            arr[i] = arr[j]
            arr[j] = temp
        }
        return arr
    }

    public static func create_deck(): ArrayList<String> {
        /*
        Create a deck of 52 cards, which stores 52 rondom order poker with the Jokers removed.
        :return: a list of 52 rondom order poker with the Jokers removed, format is ['AS', '2S', ...].()
        >>> BlackjackGame.create_deck()
        ['QD', '9D', 'JC', 'QH', '2S', 'JH', '7D', '6H', '9S', '5C', '7H', 'QS', '5H',
        '6C', '7C', '3D', '10C', 'AD', '4C', '5D', 'AH', '2D', 'QC', 'KH', '9C', '9H',
        '4H', 'JS', '6S', '8H', '8C', '4S', '3H', '10H', '7S', '6D', '3C', 'KC', '3S',
        '2H', '10D', 'KS', '4D', 'AC', '10S', '2C', 'KD', '5S', 'JD', '8S', 'AS', '8D']
        */
        let deck = ArrayList<String>()

        let ranks = ArrayList<String>()
        ranks.add("A")
        ranks.add("2")
        ranks.add("3")
        ranks.add("4")
        ranks.add("5")
        ranks.add("6")
        ranks.add("7")
        ranks.add("8")
        ranks.add("9")
        ranks.add("10")
        ranks.add("J")
        ranks.add("Q")
        ranks.add("K")

        let suits = ArrayList<String>()
        suits.add("S")
        suits.add("H")
        suits.add("D")
        suits.add("C")

        for (si in 0..(suits.size - 1)) {
            for (ri in 0..(ranks.size - 1)) {
                deck.add(ranks[ri] + suits[si])
            }
        }

        BlackjackGame.shuffle_arraylist(deck)
        return deck
    }

    public func calculate_hand_value(hand: ArrayList<String>): Int64 {
        /*
        Calculate the value of the poker cards stored in hand list according to the rules of the Blackjack Game.
        If the card is a digit, its value is added to the total hand value.
        Value of J, Q, or K is 10, while Aces are worth 11.
        If the total hand value exceeds 21 and there are Aces present, one Ace is treated as having a value of 1 instead of 11,
        until the hand value is less than or equal to 21, or all Aces have been counted as value of 1.
        :param hand: ArrayList<String>
        :return: the value of the poker cards stored in hand list, a number.
        >>> black_jack_game = BlackjackGame()
        >>> black_jack_game.calculate_hand_value(ArrayList<String>(['QD', '9D', 'JC', 'QH', 'AS']))
        40
        */
        var total: Int64 = 0
        var ace_count: Int64 = 0

        for (i in 0..(hand.size - 1)) {
            let card = hand[i]
            let rank = card.substring(0, card.length - 1)

            if (rank == "A") {
                total = total + 11
                ace_count = ace_count + 1
            } else if (rank == "K" || rank == "Q" || rank == "J") {
                total = total + 10
            } else {
                total = total + Int64.parse(rank)
            }
        }

        while (total > 21 && ace_count > 0) {
            total = total - 10
            ace_count = ace_count - 1
        }

        return total
    }

    public func check_winner(player_hand: ArrayList<String>, dealer_hand: ArrayList<String>): String {
        /*
        Determines the winner of a game by comparing the hand values of the player and dealer.
        rule:
        If both players have hand values that are equal to or less than 21, the winner is the one whose hand value is closer to 21.
        Otherwise, the winner is the one with the lower hand value.
        :param player_hand: ArrayList<String>
        :param dealer_hand: ArrayList<String>
        :return: the result of the game, only two certain String: 'Dealer wins' or 'Player wins'
        >>> black_jack_game = BlackjackGame()
        >>> black_jack_game.check_winner(ArrayList<String>(['QD', '9D', 'JC', 'QH', 'AS']), ArrayList<String>(['QD', '9D', 'JC', 'QH', '2S']))
        'Player wins'
        */
        let player_value = this.calculate_hand_value(player_hand)
        let dealer_value = this.calculate_hand_value(dealer_hand)

        if (player_value <= 21 && dealer_value <= 21) {
            if (player_value > dealer_value) {
                return "Player wins"
            } else if (player_value < dealer_value) {
                return "Dealer wins"
            } else {
                return "Dealer wins"
            }
        } else {
            if (player_value < dealer_value) {
                return "Player wins"
            } else if (player_value > dealer_value) {
                return "Dealer wins"
            } else {
                return "Dealer wins"
            }
        }
    }
}

import std.collection.HashMap

class BookManagement {

    /*
    This is a class as managing books system, which supports to add and remove books from the inventory dict, view the inventory, and check the quantity of a specific book.
    */

    let inventory: HashMap<String, Int64>

    public init() {
        /*
        Initialize the inventory of Book Manager.
        */
        this.inventory = HashMap<String, Int64>()
    }

    public func add_book(title: String, quantity!: Int64=1): Unit {
        /*
        Add one or several books to inventory which is sorted by book title.
        :param title: String, the book title
        :param quantity: Int64, default value is 1.
        */
        if quantity <= 0 {
            throw Exception("Invalid operation")
        }

        if this.inventory.contains(title) {
            let current: Int64 = this.inventory.get(title)
            this.inventory.put(title, current + quantity)
        } else {
            this.inventory.put(title, quantity)
        }
    }

    public func remove_book(title: String, quantity: Int64): Unit {
        /*
        Remove one or several books from inventory which is sorted by book title.
        throw Exception("Invalid operation") while get invalid input.
        :param title: String, the book title
        :param quantity: Int64
        */
        if quantity <= 0 {
            throw Exception("Invalid operation")
        }

        if !this.inventory.contains(title) {
            throw Exception("Invalid operation")
        }

        let current: Int64 = this.inventory.get(title)
        if quantity > current {
            throw Exception("Invalid operation")
        }

        let updated: Int64 = current - quantity
        if updated == 0 {
            this.inventory.remove(title)
        } else {
            this.inventory.put(title, updated)
        }
    }

    public func view_inventory(): HashMap<String, Int64> {
        /*
        Get the inventory of the Book Management.
        :return this.inventory: HashMap<String, Int64>
        >>> bookManagement = BookManagement()
        >>> bookManagement.add_book("book1", quantity: 1)
        >>> bookManagement.add_book("book2", quantity: 1)
        >>> bookManagement.view_inventory()
        {'book1': 1, 'book2': 1}
        */
        return this.inventory
    }

    public func view_book_quantity(title: String): Int64 {
        /*
        Get the quantity of a book.
        :param title: String, the title of the book.
        :return quantity: the quantity of this book title. return 0 when the title does not exist in this.inventory
        >>> bookManagement = BookManagement()
        >>> bookManagement.add_book("book1", quantity: 1)
        >>> bookManagement.view_book_quantity("book3")
        0
        */
        if this.inventory.contains(title) {
            return this.inventory.get(title)
        }
        return 0
    }
}

import std.collection.ArrayList

class BoyerMooreSearch {

    /*
    his is a class that implements the Boyer-Moore algorithm for string searching, which is used to find occurrences of a pattern within a given text.
    */

    let text: String
    let pattern: String
    let textLen: Int64
    let patLen: Int64

    public init(text: String, pattern: String) {
        /*
        Initializes the BoyerMooreSearch class with the given text and pattern.
        :param text: The text to be searched, String.
        :param pattern: The pattern to be searched for, String.
        */
        this.text = text
        this.pattern = pattern
        this.textLen = text.size
        this.patLen = pattern.size
    }

    public func match_in_pattern(char: String): Int64 {
        /*
        Finds the rightmost occurrence of a character in the pattern.
        :param char: The character to be searched for, String.
        :return: The index of the rightmost occurrence of the character in the pattern, Int64.
        >>> boyerMooreSearch = BoyerMooreSearch("ABAABA", "AB")
        >>> boyerMooreSearch.match_in_pattern("A")
        0

        */
        if this.patLen <= 0 {
            return -1
        }
        var i: Int64 = this.patLen - 1
        while i >= 0 {
            if this.pattern[i] == char {
                return i
            }
            i -= 1
        }
        return -1
    }

    public func mismatch_in_text(currentPos: Int64): Int64 {
        /*
        Determines the position of the first dismatch between the pattern and the text.
        :param currentPos: The current position in the text, Int64.
        :return: The position of the first dismatch between the pattern and the text, Int64,otherwise -1.
        >>> boyerMooreSearch = BoyerMooreSearch("ABAABA", "ABC")
        >>> boyerMooreSearch.mismatch_in_text(0)
        2

        */
        if this.patLen <= 0 {
            return -1
        }
        if currentPos < 0 || currentPos + this.patLen > this.textLen {
            // Out of bounds, treat as mismatch at the far right
            return this.patLen - 1
        }
        var j: Int64 = this.patLen - 1
        while j >= 0 {
            let ti: Int64 = currentPos + j
            if ti < 0 || ti >= this.textLen {
                return j
            }
            if this.pattern[j] != this.text[ti] {
                return j
            }
            j -= 1
        }
        return -1
    }

    public func bad_character_heuristic(): ArrayList<Int64> {
        /*
        Finds all occurrences of the pattern in the text.
        :return: A list of all positions of the pattern in the text, ArrayList<Int64>.
        >>> boyerMooreSearch = BoyerMooreSearch("ABAABA", "AB")
        >>> boyerMooreSearch.bad_character_heuristic()
        [0, 3]

        */
        let result = ArrayList<Int64>()
        if this.patLen <= 0 || this.textLen <= 0 || this.patLen > this.textLen {
            return result
        }

        var s: Int64 = 0
        let lastStart: Int64 = this.textLen - this.patLen

        while s <= lastStart {
            var j: Int64 = this.patLen - 1

            while j >= 0 && this.pattern[j] == this.text[s + j] {
                j -= 1
            }

            if j < 0 {
                result.add(s)
                if s + this.patLen < this.textLen {
                    let nextChar = this.text[s + this.patLen]
                    let lastOcc: Int64 = this.match_in_pattern(nextChar)
                    let shiftVal: Int64 = this.patLen - lastOcc
                    if shiftVal > 0 {
                        s += shiftVal
                    } else {
                        s += 1
                    }
                } else {
                    s += 1
                }
            } else {
                let badChar = this.text[s + j]
                let lastOcc: Int64 = this.match_in_pattern(badChar)
                let shiftVal: Int64 = j - lastOcc
                if shiftVal > 0 {
                    s += shiftVal
                } else {
                    s += 1
                }
            }
        }

        return result
    }
}

import std.collection.HashMap
import std.collection.ArrayList
import std.convert.Parsable

class Calculator {

    /*
    This is a class for a calculator, capable of performing basic arithmetic calculations on numerical expressions using the operators +, -, *, /, and ^ (exponentiation).
    */

    let operators: HashMap<String, (Float64, Float64) -> Float64>

    public init() {
        /*
        Initialize the operations performed by the five operators'+','-','*','/','^'
        */
        this.operators = HashMap<String, (Float64, Float64) -> Float64>()
        operators.add("+", {x: Float64, y: Float64 => x + y})
        operators.add("-", {x: Float64, y: Float64 => x - y})
        operators.add("*", {x: Float64, y: Float64 => x * y})
        operators.add("/", {x: Float64, y: Float64 => x / y})
        operators.add("^", {x: Float64, y: Float64 => x ** y})
    }

    public func calculate(expression: String): Option<Float64> {
        /*
        Calculate the value of a given expression
        :param expression: String, given expression
        :return:If successful, returns the value of the expression; otherwise, returns None
        >>> calculator = Calculator()
        >>> calculator.calculate('1+2-3')
        0.0
        */
        if expression == null {
            return None
        }

        let operand_stack = ArrayList<Float64>()
        let operator_stack = ArrayList<String>()

        var i: Int64 = 0
        var len: Int64 = expression.length()

        while i < len {
            let c: Char = expression.charAt(i)

            // Skip whitespace
            if c == ' ' || c == '\t' || c == '\n' {
                i = i + 1
                continue
            }

            // Number parsing (supports decimals)
            if (c >= '0' && c <= '9') || c == '.' {
                var numStr: String = ""
                while i < len {
                    let d: Char = expression.charAt(i)
                    if ((d >= '0' && d <= '9') || d == '.') {
                        numStr = numStr + d.toString()
                        i = i + 1
                    } else {
                        break
                    }
                }
                let parsed: Option<Float64> = Parsable.parseFloat64(numStr)
                if parsed == None {
                    return None
                }
                operand_stack.add(parsed.get())
                continue
            }

            // Parentheses handling
            if c == '(' {
                operator_stack.add("(")
                i = i + 1
                continue
            }
            if c == ')' {
                // Apply until we find '('
                while operator_stack.size() > 0 && operator_stack.get(operator_stack.size() - 1) != "(" {
                    let _ = this.apply_operator(operand_stack, operator_stack)
                }
                if operator_stack.size() == 0 {
                    // Mismatched parenthesis
                    return None
                }
                // Pop '('
                operator_stack.removeAt(operator_stack.size() - 1)
                i = i + 1
                continue
            }

            // Operators
            if c == '+' || c == '-' || c == '*' || c == '/' || c == '^' {
                let o1: String = c.toString()
                // Handle operator precedence and associativity (^ is right-associative)
                while operator_stack.size() > 0 {
                    let top: String = operator_stack.get(operator_stack.size() - 1)
                    if top == "(" {
                        break
                    }
                    let pTop: Int64 = this.precedence(top)
                    let pCur: Int64 = this.precedence(o1)
                    var shouldApply: Bool = false
                    if o1 == "^" {
                        // Right-associative: apply while pTop > pCur
                        shouldApply = pTop > pCur
                    } else {
                        // Left-associative: apply while pTop >= pCur
                        shouldApply = pTop >= pCur
                    }

                    if shouldApply {
                        let _ = this.apply_operator(operand_stack, operator_stack)
                    } else {
                        break
                    }
                }
                operator_stack.add(o1)
                i = i + 1
                continue
            }

            // Invalid character
            return None
        }

        // Final collapse
        while operator_stack.size() > 0 {
            if operator_stack.get(operator_stack.size() - 1) == "(" {
                // Mismatched parenthesis
                return None
            }
            let _ = this.apply_operator(operand_stack, operator_stack)
        }

        if operand_stack.size() == 1 {
            return Some(operand_stack.get(0))
        } else {
            return None
        }
    }

    public func precedence(op: String): Int64 {
        /*
        Returns the priority of the specified operator, where the higher the priority, the greater the assignment. The priority of '^' is greater than '/' and '*', and the priority of '/' and '*' is greater than '+' and '-'
        :param operator: String, given operator
        :return: Int64, the priority of the given operator, otherwise return 0
        >>> calculator = Calculator()
        >>> calculator.precedence('+')
        1
        >>> calculator.precedence('^')
        3
        */
        if op == "+" || op == "-" {
            return 1
        }
        if op == "*" || op == "/" {
            return 2
        }
        if op == "^" {
            return 3
        }
        return 0
    }

    public func apply_operator(operand_stack: ArrayList<Float64>, operator_stack: ArrayList<String>): (ArrayList<Float64>, ArrayList<String>) {
        /*
        Use the operator at the top of the operator stack to perform the operation on the two numbers at the top of the operator stack, and store the results at the top of the operator stack
        :param operand_stack:ArrayList<Float64>
        :param operator_stack:ArrayList<String>
        :return: the updated operand_stack and operator_stack
        >>> calculator = Calculator()
        >>> calculator.apply_operator(ArrayList<Float64>([1, 2, 3]), ArrayList<String>(['+', '-']))
        ([1, -1], ['-'])
        */
        if operator_stack.size() == 0 || operand_stack.size() < 2 {
            return (operand_stack, operator_stack)
        }

        let op: String = operator_stack.get(operator_stack.size() - 1)
        operator_stack.removeAt(operator_stack.size() - 1)

        let right: Float64 = operand_stack.get(operand_stack.size() - 1)
        operand_stack.removeAt(operand_stack.size() - 1)
        let left: Float64 = operand_stack.get(operand_stack.size() - 1)
        operand_stack.removeAt(operand_stack.size() - 1)

        var result: Float64 = 0.0

        // Apply using the initialized operator map if available, otherwise fallback
        let fOpt: Option<(Float64, Float64) -> Float64> = this.operators.get(op)
        if fOpt != None {
            let f: (Float64, Float64) -> Float64 = fOpt.get()
            result = f(left, right)
        } else {
            if op == "+" {
                result = left + right
            } else if op == "-" {
                result = left - right
            } else if op == "*" {
                result = left * right
            } else if op == "/" {
                result = left / right
            } else if op == "^" {
                result = left ** right
            } else {
                // Unknown operator: push operands back (no-op)
                operand_stack.add(left)
                operand_stack.add(right)
                // Re-push operator back to maintain consistency
                operator_stack.add(op)
                return (operand_stack, operator_stack)
            }
        }

        operand_stack.add(result)
        return (operand_stack, operator_stack)
    }
}

import std.time.DateTime
import std.collection.ArrayList

class Event <: Equatable<Event> {

    /*
    This is a class as Event that represents a calendar event with date, time range, and description.
    It implements the Equatable interface to support event comparison.
    */

    let date: DateTime
    let start_time: DateTime
    let end_time: DateTime
    let description: String

    public init(date: DateTime, start_time: DateTime, end_time: DateTime, description: String) {
