class Message <: Equatable<Message> {

    /*
    This is a Message class representing a message in a chat system.
    It contains information about the sender, receiver, message content, and timestamp.
    */

    let sender: String
    let receiver: String
    let message: String
    let timestamp: String

    public init(sender: String, receiver: String, message: String, timestamp: String) {
        /*
        Initialize a Message object with sender, receiver, message content, and timestamp.
        :param sender: The username of the sender, String.
        :param receiver: The username of the receiver, String.
        :param message: The content of the message, String.
        :param timestamp: The time when the message was sent, String.
        >>> let msg = Message("John", "Mary", "Hello", "2023-01-01 00:00:00")
        >>> msg.sender
        "John"
        >>> msg.receiver
        "Mary"
        >>> msg.message
        "Hello"
        >>> msg.timestamp
        "2023-01-01 00:00:00"
        */
        this.sender = sender
        this.receiver = receiver
        this.message = message
        this.timestamp = timestamp
    }

    public override operator func != (that: Message): Bool {
        /*
        Check if two Message objects are not equal.
        Two messages are considered not equal if any of their sender, receiver, message, or timestamp differ.
        :param that: Another Message object to compare with.
        :return: True if the messages are not equal, False otherwise.
        >>> let msg1 = Message("John", "Mary", "Hello", "2023-01-01 00:00:00")
        >>> let msg2 = Message("John", "Mary", "Hi", "2023-01-01 00:00:00")
        >>> msg1 != msg2
        true
        */
        return this.sender != that.sender || this.receiver != that.receiver || this.message != that.message || this.timestamp != that.timestamp
    }

    public override operator func == (that: Message): Bool {
        /*
        Check if two Message objects are equal.
        Two messages are considered equal if their sender, receiver, message, and timestamp are all the same.
        :param that: Another Message object to compare with.
        :return: True if the messages are equal, False otherwise.
        >>> let msg1 = Message("John", "Mary", "Hello", "2023-01-01 00:00:00")
        >>> let msg2 = Message("John", "Mary", "Hello", "2023-01-01 00:00:00")
        >>> let msg3 = Message("Mary", "John", "Hello", "2023-01-01 00:00:00")
        >>> msg1 == msg2
        true
        >>> msg1 == msg3
        false
        */
        return this.sender == that.sender && this.receiver == that.receiver && this.message == that.message && this.timestamp == that.timestamp
    }
}

class Chat {

    /*
    This is a chat class with the functions of adding users, removing users, sending messages, and obtaining messages.
    */

    let users: HashMap<String, ArrayList<Message>>

    public init() {
        /*
        Initialize the Chat with an attribute users, which is an empty dictionary.
        */
        this.users = HashMap<String, ArrayList<Message>>()
    }

    public func add_user(username: String): Bool {
        /*
        Add a new user to the Chat.
        :param username: The user's name, String.
        :return: If the user is already in the Chat, returns false, otherwise, returns true.
        >>> chat = Chat()
        >>> chat.add_user('John')
        true
        this.users = {'John': []}
        >>> chat.add_user('John')
        false

        */
        if this.users.containsKey(username) {
            return false
        }
        this.users.put(username, ArrayList<Message>())
        return true
    }

    public func remove_user(username: String): Bool {
        /*
        Remove a user from the Chat.
        :param username: The user's name, String.
        :return: If the user is already in the Chat, returns true, otherwise, returns false.
        >>> chat = Chat()
        >>> chat.users = {'John': []}
        >>> chat.remove_user('John')
        true
        >>> chat.remove_user('John')
        false

        */
        if !this.users.containsKey(username) {
            return false
        }
        this.users.remove(username)
        return true
    }

    public func send_message(sender: String, receiver: String, message: String): Bool {
        /*
        Send a message from a user to another user.
        :param sender: The sender's name, String.
        :param receiver: The receiver's name, String.
        :param message: The message, String.
        :return: If the sender or the receiver is not in the Chat, returns false, otherwise, returns true.
        >>> chat = Chat()
        >>> chat.users = {'John': [], 'Mary': []}
        >>> chat.send_message('John', 'Mary', 'Hello')
        true
        >>> chat.send_message('John', 'Tom', 'Hello')
        false

        */
        if !this.users.containsKey(sender) || !this.users.containsKey(receiver) {
            return false
        }
        let ts = DateTime.now().format("yyyy-MM-dd HH:mm:ss")
        let msg = Message(sender, receiver, message, ts)
        // Store sent messages with the sender as demonstrated in the examples
        let sentMessages = this.users.get(sender)
        if sentMessages == null {
            // Should not happen because sender existence is checked, but ensure robustness
            let newList = ArrayList<Message>()
            newList.add(msg)
            this.users.put(sender, newList)
        } else {
            sentMessages.add(msg)
        }
        return true
    }

    public func get_messages(username: String): ArrayList<Message> {
        /*
        Get all the messages of a user from the Chat.
        :param username: The user's name, String.
        :return: A list of messages, each message is a Message object.
        >>> chat = Chat()
        >>> chat.users = {'John': ArrayList<Message>([Message('John', 'Mary', 'Hello', '2023-01-01 00:00:00')]), 'Mary': []}
        >>> chat.get_messages('John')
        ArrayList<Message>([Message('John', 'Mary', 'Hello', '2023-01-01 00:00:00')])
        >>> chat.get_messages('Mary')
        []

        */
        if !this.users.containsKey(username) {
            return ArrayList<Message>()
        }
        let messages = this.users.get(username)
        if messages == null {
            return ArrayList<Message>()
        }
        return messages
    }
}

import std.collection.ArrayList
import std.time.DateTime

class Course <: Equatable<Course> {

    /*
    This is a class representing a course, containing the name of the course and its start and end times.
    It supports equality comparison to check if two courses are identical in terms of name and time.
    */

    let name: String
    let start_time: String
    let end_time: String

    public init(name: String, start_time: String, end_time: String) {
        /*
        Initialize a course with its name and time range.
        :param name: String, the name of the course
        :param start_time: String, the start time of the course in format 'yyyy/MM/dd HH:mm'
        :param end_time: String, the end time of the course in format 'yyyy/MM/dd HH:mm'
        */
        this.name = name
        this.start_time = start_time
        this.end_time = end_time
    }

    public override operator func != (that: Course): Bool {
        /*
        Check if this course is not equal to another course.
        Two courses are considered different if any of their name, start time or end time differs.
        :param that: Course, the course to compare with
        :return: true if the courses differ in name, start time or end time; false otherwise
        */
        return this.name != that.name || this.start_time != that.start_time || this.end_time != that.end_time
    }

    public override operator func == (that: Course): Bool {
        /*
        Check if this course is equal to another course.
        Two courses are considered equal if they have the same name, start time and end time.
        :param that: Course, the course to compare with
        :return: true if the courses have the same name, start time and end time; false otherwise
        */
        return this.name == that.name && this.start_time == that.start_time && this.end_time == that.end_time
    }
}

class Classroom {

    /*
    This is a class representing a classroom, capable of adding and removing courses, checking availability at a given time, and detecting conflicts when scheduling new courses.
    */

    let id: Int64
    let courses: ArrayList<Course>

    public init(id: Int64) {
        /*
        Initialize the classroom management system.
        :param id: Int64, the id of classroom
        */
        this.id = id
        this.courses = ArrayList<Course>()
    }

    public func add_course(course: Course): Unit {
        /*
        Add course to this.courses list if the course wasn't in it.
        :param course: Course, information of the course, including 'start_time', 'end_time' and 'name'
        >>> classroom = Classroom(1)
        >>> classroom.add_course({'name': 'math', 'start_time': '2023/09/01 08:00', 'end_time': '2023/09/01 09:40'})
        */
        let n = this.courses.size()
        var i = 0
        while i < n {
            let c = this.courses.get(i)
            if c == course {
                return
            }
            i = i + 1
        }
        this.courses.add(course)
    }

    public func remove_course(course: Course): Unit {
        /*
        Remove course from this.courses list if the course was in it.
        :param course: Course, information of the course, including 'start_time', 'end_time' and 'name'
        >>> classroom = Classroom(1)
        >>> classroom.add_course({'name': 'math', 'start_time': '2023/09/01 08:00', 'end_time': '2023/09/01 09:40'})
        >>> classroom.remove_course({'name': 'math', 'start_time': '2023/09/01 08:00', 'end_time': '2023/09/01 09:40'})
        */
        let n = this.courses.size()
        var i = 0
        while i < n {
            let c = this.courses.get(i)
            if c == course {
                this.courses.remove_at(i)
                return
            }
            i = i + 1
        }
    }

    public func is_free_at(check_time: String): Bool {
        /*
        change the time format as 'yyyy/MM/dd HH:mm' and check the time is free or not in the classroom.
        :param check_time: String, the time need to be checked
        :return: true if the check_time does not conflict with every course time, or false otherwise.
        >>> classroom = Classroom(1)
        >>> classroom.add_course({'name': 'math', 'start_time': '2023/09/01 08:00', 'end_time': '2023/09/01 09:40'})
        >>> classroom.is_free_at('2023/09/01 10:00')
        true
        >>> classroom.is_free_at('2023/09/01 09:00')
        false
        */
        // Since the time format is 'yyyy/MM/dd HH:mm' with zero-padded components,
        // lexicographical string comparison matches chronological order.
        let n = this.courses.size()
        var i = 0
        while i < n {
            let c = this.courses.get(i)
            // Occupied if start_time <= check_time <= end_time (inclusive)
            if check_time >= c.start_time && check_time <= c.end_time {
                return false
            }
            i = i + 1
        }
        return true
    }

    public func check_course_conflict(new_course: Course): Bool {
        /*
        Before adding a new course, check if the new course time conflicts with any other course.
        :param new_course: Course, information of the course, including 'start_time', 'end_time' and 'name'
        :return: false if the new course time conflicts(including two courses have the same boundary time) with other courses, or true otherwise.
        >>> classroom = Classroom(1)
        >>> classroom.add_course({'name': 'math', 'start_time': '2023/09/01 08:00', 'end_time': '2023/09/01 09:40'})
        >>> classroom.check_course_conflict({'name': 'SE', 'start_time': '2023/09/01 09:40', 'end_time': '2023/09/01 10:40'})
        false
        */
        let s2 = new_course.start_time
        let e2 = new_course.end_time

        let n = this.courses.size()
        var i = 0
        while i < n {
            let c = this.courses.get(i)
            let s1 = c.start_time
            let e1 = c.end_time
            // Conflict if time ranges overlap with inclusive boundaries:
            // not (e2 < s1 or s2 > e1)
            if !(e2 < s1 || s2 > e1) {
                return false
            }
            i = i + 1
        }
        return true
    }
}

import std.collection.ArrayList
import std.collection.HashMap

class ClassRegistrationSystem {

    /*
    This is a class as a class registration system, allowing to register students, register them for classes, retrieve students by major, get a list of all majors, and determine the most popular class within a specific major.
    */

    var students: ArrayList<HashMap<String, String>>
    var students_registration_classes: HashMap<String, ArrayList<String>>

    public init() {
        /*
        Initialize the registration system with the attribute students and students_registration_class.
        students is a list of student dictionaries, each student dictionary has the key of name and major.
        students_registration_class is a dictionaries, key is the student name, value is a list of class names
        */
        this.students = ArrayList<HashMap<String, String>>()
        this.students_registration_classes = HashMap<String, ArrayList<String>>()
    }

    public func register_student(student: HashMap<String, String>): Int64 {
        /*
        register a student to the system, add the student to the students list, if the student is already registered, return 0, else return 1
        */
        var name: String = student.get("name")
        var i: Int64 = 0
        while i < this.students.size() {
            var existing: HashMap<String, String> = this.students.get(i)
            var existing_name: String = existing.get("name")
            if existing_name == name {
                return 0
            }
            i = i + 1
        }
        this.students.add(student)
        return 1
    }

    public func register_class(student_name: String, class_name: String): ArrayList<String> {
        /*
        register a class to the student.
        :param student_name: String
        :param class_name: String
        :return a list of class names that the student has registered
        >>> registration_system = ClassRegistrationSystem()
        >>> registration_system.register_class("John", "CS101")
        >>> registration_system.register_class("John", "CS102")
        ["CS101", "CS102"]
        */
        var classes: ArrayList<String>
        if this.students_registration_classes.contains_key(student_name) {
            classes = this.students_registration_classes.get(student_name)
        } else {
            classes = ArrayList<String>()
            this.students_registration_classes.put(student_name, classes)
        }

        var exists: Int64 = 0
        var i: Int64 = 0
        while i < classes.size() {
            if classes.get(i) == class_name {
                exists = 1
                break
            }
            i = i + 1
        }
        if exists == 0 {
            classes.add(class_name)
        }
        return classes
    }

    public func get_students_by_major(major: String): ArrayList<String> {
        /*
        get all students in the major
        :param major: String
        :return a list of student name
        >>> registration_system = ClassRegistrationSystem()
        >>> student1 = HashMap<String, String>([("name", "John"), ("major", "Computer Science")])
        >>> registration_system.register_student(student1)
        >>> registration_system.get_students_by_major("Computer Science")
        ["John"]
        */
        var result: ArrayList<String> = ArrayList<String>()
        var i: Int64 = 0
        while i < this.students.size() {
            var s: HashMap<String, String> = this.students.get(i)
            var m: String = s.get("major")
            if m == major {
                result.add(s.get("name"))
            }
            i = i + 1
        }
        return result
    }

    public func get_all_major(): ArrayList<String> {
        /*
        get all majors in the system
        :return a list of majors
        >>> registration_system = ClassRegistrationSystem()
        >>> student1 = HashMap<String, String>([("name", "John"), ("major", "Computer Science")])
        >>> registration_system.students = ArrayList<HashMap<String, String>>()
        >>> registration_system.students.add(student1)
        >>> registration_system.get_all_major()
        ["Computer Science"]
        */
        var majors: ArrayList<String> = ArrayList<String>()
        var i: Int64 = 0
        while i < this.students.size() {
            var s: HashMap<String, String> = this.students.get(i)
            var m: String = s.get("major")

            var exists: Int64 = 0
            var j: Int64 = 0
            while j < majors.size() {
                if majors.get(j) == m {
                    exists = 1
                    break
                }
                j = j + 1
            }
            if exists == 0 {
                majors.add(m)
            }

            i = i + 1
        }
        return majors
    }

    public func get_most_popular_class_in_major(major: String): String {
        /*
        get the class with the highest enrollment in the major.
        :return a string of the most popular class in this major
        >>> registration_system = ClassRegistrationSystem()
        >>> registration_system.students = ArrayList<HashMap<String, String>>([HashMap<String, String>([("name", "John"), ("major", "Computer Science")]), HashMap<String, String>([("name", "Bob"), ("major", "Computer Science")]), HashMap<String, String>([("name", "Alice"), ("major", "Computer Science")])])
        >>> registration_system.students_registration_classes = HashMap<String, ArrayList<String>>([("John", ArrayList<String>(["Algorithms", "Data Structures"])), ("Bob", ArrayList<String>(["Operating Systems", "Data Structures", "Algorithms"]))])
        >>> registration_system.get_most_popular_class_in_major("Computer Science")
        "Data Structures"
        */
        var counts: HashMap<String, Int64> = HashMap<String, Int64>()
        var best_class: String = ""
        var max_count: Int64 = 0

        var i: Int64 = 0
        while i < this.students.size() {
            var s: HashMap<String, String> = this.students.get(i)
            if s.get("major") == major {
                var name: String = s.get("name")
                if this.students_registration_classes.contains_key(name) {
                    var classes: ArrayList<String> = this.students_registration_classes.get(name)
                    var j: Int64 = 0
                    while j < classes.size() {
                        var c: String = classes.get(j)
                        var current: Int64
                        if counts.contains_key(c) {
                            current = counts.get(c) + 1
                            counts.put(c, current)
                        } else {
                            current = 1
                            counts.put(c, current)
                        }

                        if current > max_count {
                            max_count = current
                            best_class = c
                        } else if current == max_count {
                            // In case of tie, prefer the last class reaching the max (matches provided example)
                            best_class = c
                        }

                        j = j + 1
                    }
                }
            }
            i = i + 1
        }

        return best_class
    }
}

import std.collection.ArrayList

class CombinationCalculator {

    /*
    This is a class that provides methods to calculate the number of combinations for a specific count, calculate all possible combinations, and generate combinations with a specified number of elements.
    */

    let datas: ArrayList<String>

    public init(datas: ArrayList<String>) {
        /*
        Initialize the calculator with a list of data.
        */
        this.datas = datas
    }

    public static func factorial(n: Int64): Int64 {
        /*
        Calculate the factorial of a number.
        :param n: The number to calculate the factorial of,Int64.
        :return: The factorial of the number,Int64.
        */
        var result: Int64 = 1
        for (i in 1..n + 1) {
            result *= i
        }
        return result
    }

    public static func count(n: Int64, m: Int64): Int64 {
        /*
        Calculate the number of combinations for a specific count.
        :param n: The total number of elements,Int64.
        :param m: The number of elements in each combination,Int64.
        :return: The number of combinations,Int64.
        >>> CombinationCalculator.count(4, 2)
        6
        */
        if (m < 0 || n < 0) {
            return 0
        }
        if (m == 0 || m == n) {
            return 1
        }
        if (m > n) {
            return 0
        }
        var k = m
        if (k > n - k) {
            k = n - k
        }
        var res: Int64 = 1
        var i: Int64 = 1
        while (i <= k) {
            // res = res * (n - k + i) / i
            // This sequence keeps res integral at each step.
            res = (res * (n - k + i)) / i
            i += 1
        }
        return res
    }

    public static func count_all(n: Int64): Int64 {
        /*
        Calculate the number of all possible combinations.
        :param n: The total number of elements,Int64.
        :return: The number of all possible combinations,Int64,if the number of combinations is greater than 2^63-1,return Int64.Max.
        >>> CombinationCalculator.count_all(4)
        15
        */
        if (n <= 0) {
            return 0
        }
        var value: Int64 = 1
        for (_ in 0..n) {
            if (value > Int64.Max / 2) {
                return Int64.Max
            }
            value = value * 2
        }
        // 2^n - 1
        return value - 1
    }

    public func select(m: Int64): ArrayList<ArrayList<String>> {
        /*
        Generate combinations with a specified number of elements.
        :param m: The number of elements in each combination,Int64.
        :return: A list of combinations,ArrayList<ArrayList<String>>.
        >>> calc = CombinationCalculator(ArrayList<String>(["A", "B", "C", "D"]))
        >>> calc.select(2)
        [['A', 'B'], ['A', 'C'], ['A', 'D'], ['B', 'C'], ['B', 'D'], ['C', 'D']]

        */
        var result = ArrayList<ArrayList<String>>()
        if (m <= 0) {
            return result
        }
        let n = this.datas.size()
        if (m > n) {
            return result
        }
        let tempArray = Array<String>(m, repeat: "")
        var tempList = ArrayList<String>(tempArray)
        this._select(0, tempList, 0, result)
        return result
    }

    public func select_all(): ArrayList<ArrayList<String>> {
        /*
        Generate all possible combinations of  selecting elements from the given data list,and it uses the select method.
        :return: A list of combinations,ArrayList<ArrayList<String>>.
        >>> calc = CombinationCalculator(ArrayList<String>(["A", "B", "C", "D"]))
        >>> calc.select_all()
        [['A'], ['B'], ['C'], ['D'], ['A', 'B'], ['A', 'C'], ['A', 'D'], ['B', 'C'], ['B', 'D'], ['C', 'D'], ['A', 'B', 'C'], ['A', 'B', 'D'], ['A', 'C', 'D'], ['B', 'C', 'D'], ['A', 'B', 'C', 'D']]

        */
        var all = ArrayList<ArrayList<String>>()
        let n = this.datas.size()
        for (k in 1..n + 1) {
            let part = this.select(k)
            // append all from part into all
            for (i in 0..part.size()) {
                all.add(part[i])
            }
        }
        return all
    }

    public func _select(dataIndex: Int64, resultList: ArrayList<String>, resultIndex: Int64, result: ArrayList<ArrayList<String>>): Unit {
        /*
        Generate combinations with a specified number of elements by recursion.
        :param dataIndex: The index of the data to be selected,Int64.
        :param resultList: The list of elements in the combination,ArrayList<String>.
        :param resultIndex: The index of the element in the combination,Int64.
        :param result: The list of combinations,ArrayList<ArrayList<String>>.
        :return: Unit.
        >>> calc = CombinationCalculator(ArrayList<String>(["A", "B", "C", "D"]))
        >>> result = ArrayList<ArrayList<String>>()
        >>> calc._select(0, ArrayList<String>(Array<String>(2, repeat: "")), 0, result)
        >>> result
        [['A', 'B'], ['A', 'C'], ['A', 'D'], ['B', 'C'], ['B', 'D'], ['C', 'D']]

        */
        let n = this.datas.size()
        let m = resultList.size()

        if (resultIndex == m) {
            var combination = ArrayList<String>()
            for (j in 0..m) {
                combination.add(resultList[j])
            }
            result.add(combination)
            return
        }

        let remaining = m - resultIndex
        let endExclusive = n - remaining + 1

        for (i in dataIndex..endExclusive) {
            resultList[resultIndex] = this.datas[i]
            this._select(i + 1, resultList, resultIndex + 1, result)
        }
    }
}

import std.math.abs

class ComplexNumber <: Equatable<ComplexNumber> {

    /*
    This is a class that represents a complex number with real and imaginary parts.
    */

    public var real: Float64
    public var imaginary: Float64

    public init(real: Float64, imaginary: Float64) {
        /*
        Initializes a complex number with the given real and imaginary parts.
        :param real: The real part of the complex number,Float64.
        :param imaginary: The imaginary part of the complex number,Float64.
        */
        this.real = real
        this.imaginary = imaginary
    }

    public override operator func != (that: ComplexNumber): Bool {
        /*
        Checks if this complex number is not equal to another complex number.
        :param that: The other complex number to compare with,ComplexNumber.
        :return: true if the complex numbers are not equal, false otherwise,Bool.
        */
        return this.real != that.real || this.imaginary != that.imaginary
    }

    public override operator func == (that: ComplexNumber): Bool {
        /*
        Checks if this complex number is equal to another complex number.
        :param that: The other complex number to compare with,ComplexNumber.
        :return: true if the complex numbers are equal, false otherwise,Bool.
        */
        return this.real == that.real && this.imaginary == that.imaginary
    }
}


class ComplexCalculator {

    /*
    This is a class that implements addition, subtraction, multiplication, and division operations for complex numbers.
    */

    public init() { }

    public static func add(c1: ComplexNumber, c2: ComplexNumber): ComplexNumber {
        /*
        Adds two complex numbers.
        :param c1: The first complex number,ComplexNumber.
        :param c2: The second complex number,ComplexNumber.
        :return: The sum of the two complex numbers,ComplexNumber.
        >>> ComplexCalculator.add(ComplexNumber(1.0, 2.0), ComplexNumber(3.0, 4.0))
        ComplexNumber(4.0, 6.0)

        */
        let r = c1.real + c2.real
        let i = c1.imaginary + c2.imaginary
        return ComplexNumber(real: r, imaginary: i)
    }

    public static func subtract(c1: ComplexNumber, c2: ComplexNumber): ComplexNumber {
        /*
        Subtracts two complex numbers.
        :param c1: The first complex number,ComplexNumber.
        :param c2: The second complex number,ComplexNumber.
        :return: The difference of the two complex numbers,ComplexNumber.
        >>> ComplexCalculator.subtract(ComplexNumber(1.0, 2.0), ComplexNumber(3.0, 4.0))
        ComplexNumber(-2.0, -2.0)

        */
        let r = c1.real - c2.real
        let i = c1.imaginary - c2.imaginary
        return ComplexNumber(real: r, imaginary: i)
    }

    public static func multiply(c1: ComplexNumber, c2: ComplexNumber): ComplexNumber {
        /*
        Multiplies two complex numbers.
        :param c1: The first complex number,ComplexNumber.
        :param c2: The second complex number,ComplexNumber.
        :return: The product of the two complex numbers,ComplexNumber.
        >>> ComplexCalculator.multiply(ComplexNumber(1.0, 2.0), ComplexNumber(3.0, 4.0))
        ComplexNumber(-5.0, 10.0)

        */
        let a = c1.real
        let b = c1.imaginary
        let c = c2.real
        let d = c2.imaginary
        let r = a * c - b * d
        let i = a * d + b * c
        return ComplexNumber(real: r, imaginary: i)
    }

    public static func divide(c1: ComplexNumber, c2: ComplexNumber): ComplexNumber {
        /*
        Divides two complex numbers.
        :param c1: The first complex number,ComplexNumber.
        :param c2: The second complex number,ComplexNumber.
        :return: The quotient of the two complex numbers,ComplexNumber.
        >>> ComplexCalculator.divide(ComplexNumber(1.0, 2.0), ComplexNumber(3.0, 4.0))
        ComplexNumber(0.44, 0.08)

        */
        let a = c1.real
        let b = c1.imaginary
        let c = c2.real
        let d = c2.imaginary
        let denom = c * c + d * d
        let r = (a * c + b * d) / denom
        let i = (b * c - a * d) / denom
        return ComplexNumber(real: r, imaginary: i)
    }
}

import std.collection.ArrayList
import std.fs.*
import std.io.*
import std.unicode.UnicodeStringExtension

class CSVProcessor {

    /*
    This is a class for processing CSV files, including readring and writing CSV data, as well as processing specific operations and saving as a new CSV file.
    */

    public init() {}

    private func safe_to_upper(s: String): String {
        // Use Unicode extension if available; fallback to s if conversion fails.
        try {
            return UnicodeStringExtension.toUpperCase(s)
        } catch (_: Exception) {
            return s
        }
    }

    private func parse_csv_line(line: String): ArrayList<String> {
        // Naive CSV split by comma (no advanced quoting handling)
        let items = ArrayList<String>()
        var current = ""
        var inQuotes = false
        var i: Int64 = 0
        let n = line.length()
        while i < n {
            let ch = line.charAt(i)
            if ch == '"' {
                // Toggle quote state or escape double quotes
                if inQuotes && (i + 1) < n && line.charAt(i + 1) == '"' {
                    current = current + "\""
                    i = i + 1
                } else {
                    inQuotes = !inQuotes
                }
            } else if ch == ',' && !inQuotes {
                items.push(current)
                current = ""
            } else {
                current = current + ch
            }
            i = i + 1
        }
        items.push(current)
        return items
    }

    private func join_csv_row(row: ArrayList<String>): String {
        var out = ""
        let size = row.size()
        var i: Int64 = 0
        while i < size {
            var cell = row.get(i)
            // If cell contains comma or quotes, we simply quote it and escape quotes
            if cell.contains(",") || cell.contains("\"") {
                cell = "\"" + cell.replace("\"", "\"\"") + "\""
            }
            out = out + cell
            if i < size - 1 {
                out = out + ","
            }
            i = i + 1
        }
        return out
    }

    private func read_text_file(file_name: String): (String, Bool) {
        // Read entire file as text, return (content, success)
        try {
            let content = IO.readTextFile(file_name)
            return (content, true)
        } catch (_: Exception) {
            return ("", false)
        }
    }

    private func write_text_file(file_name: String, content: String): Bool {
        try {
            IO.writeTextFile(file_name, content)
            return true
        } catch (_: Exception) {
            return false
        }
    }

    public func read_csv(file_name: String): (ArrayList<String>, ArrayList<ArrayList<String>>) {
        /*
        Read the csv file by file_name, get the title and data from it
        :param file_name: String, name of the csv file
        :return title, data: (ArrayList<String>, ArrayList<ArrayList<String>>), first row is title, the rest is data
        >>> csvProcessor = CSVProcessor()
        >>> csvProcessor.read_csv('read_test.csv')
        (['a', 'b', 'c', 'd'], [['hElLo', 'YoU', 'ME', 'LoW']])
        */
        var title = ArrayList<String>()
        var data = ArrayList<ArrayList<String>>()

        let (content, ok) = read_text_file(file_name)
        if !ok {
            return (title, data)
        }

        // Normalize line endings, split into lines
        var normalized = content.replace("\r\n", "\n").replace("\r", "\n")
        let rawLines = normalized.split("\n")
        var lines = ArrayList<String>()
        for line in rawLines {
            // Skip empty trailing lines
            if line.trim().length() > 0 {
                lines.push(line)
            }
        }

        if lines.size() == 0 {
            return (title, data)
        }

        // First line is header
        title = parse_csv_line(lines.get(0))

        // Remaining lines are data
        var idx: Int64 = 1
        while idx < lines.size() {
            data.push(parse_csv_line(lines.get(idx)))
            idx = idx + 1
        }

        return (title, data)
    }

    public func write_csv(data: ArrayList<ArrayList<String>>, file_name: String): Int64 {
        /*
        Write data into a csv file.
        :param file_name: String, name of the csv file
        :return: Int64, if success return 1, or 0 otherwise
        >>> csvProcessor = CSVProcessor()
        >>> data = ArrayList<ArrayList<String>>([ArrayList<String>(['a', 'b', 'c', 'd']), ArrayList<String>(['hElLo', 'YoU', 'ME', 'LoW'])])
        >>> csvProcessor.write_csv(data, 'write_test.csv')
        1
        */
        var content = ""
        var i: Int64 = 0
        while i < data.size() {
            content = content + join_csv_row(data.get(i))
            if i < data.size() - 1 {
                content = content + "\n"
            }
            i = i + 1
        }

        let ok = write_text_file(file_name, content)
        if ok {
            return 1
        }
        return 0
    }

    private func add_process_suffix(file_name: String): String {
        // Insert "_process" before file extension if present, else append
        let dotIndex = file_name.lastIndexOf(".")
        if dotIndex >= 0 {
            let base = file_name.substring(0, dotIndex)
            let ext = file_name.substring(dotIndex, file_name.length())
            return base + "_process" + ext
        }
        return file_name + "_process"
    }

    public func process_csv_data(N: Int64, save_file_name: String): Int64 {
        /*
        Read a csv file into variable title and data.
        Only remain the N th (from 0) column data and Capitalize them, store the title and new data into a new csv file.
        Add '_process' suffix after old file name, as a new file name.
        :param N: Int64, the N th column(from 0)
        :param save_file_name, the name of file that needs to be processed.
        :return:Int64, if success return 1, or 0 otherwise
        >>> csvProcessor = CSVProcessor()
        >>> csvProcessor.read_csv('read_test.csv')
        (['a', 'b', 'c', 'd'], [['hElLo', 'YoU', 'ME', 'LoW']])
        >>> csvProcessor.process_csv_data(0, 'read_test.csv')
        1
        >>> csvProcessor.read_csv('read_test_process.csv')
        (['a', 'b', 'c', 'd'], [['HELLO']])
        */
        let (title, data) = read_csv(save_file_name)
        if title.size() == 0 {
            return 0
        }
        if N < 0 || N >= title.size() {
            return 0
        }

        // Build new dataset: header unchanged, each row becomes a single uppercase column from N
        let newData = ArrayList<ArrayList<String>>()
        newData.push(title)

        var i: Int64 = 0
        while i < data.size() {
            let row = data.get(i)
            var cell = ""
            if N < row.size() {
                cell = row.get(N)
            }
            let upperCell = safe_to_upper(cell)
            let newRow = ArrayList<String>()
            newRow.push(upperCell)
            newData.push(newRow)
            i = i + 1
        }

        let newFileName = add_process_suffix(save_file_name)
        return write_csv(newData, newFileName)
    }
}

import std.collection.HashMap
import std.collection.ArrayList
import std.math.abs

class CurrencyConverter {

    /*
    This is a class for currency conversion, which supports to convert amounts between different currencies, retrieve supported currencies, add new currency rates, and update existing currency rates.
    */

    let rates: HashMap<String, Float64>

    public init() {
        /*
        Initialize the exchange rate of the US dollar against various currencies
        */
        this.rates = HashMap<String, Float64>()
        this.rates.add('USD', 1.0)
        this.rates.add('EUR', 0.85)
        this.rates.add('GBP', 0.72)
        this.rates.add('JPY', 110.15)
        this.rates.add('CAD', 1.23)
        this.rates.add('AUD', 1.34)
        this.rates.add('CNY', 6.40)
    }

    public func convert(amount: Float64, from_currency: String, to_currency: String): Float64 {
        /*
        Convert the value of a given currency to another currency type
        :param amount: Float64, The value of a given currency
        :param from_currency: String, source currency type
        :param to_currency: String, target currency type
        :return: Float64, value converted to another currency type
        >>> cc = CurrencyConverter()
        >>> cc.convert(64.0, 'CNY','USD')
        10.0
        */
        if from_currency == to_currency {
            return amount
        }
        if !this.rates.containsKey(from_currency) {
            return 0.0
        }
        if !this.rates.containsKey(to_currency) {
            return 0.0
        }
        let from_rate: Float64 = this.rates.get(from_currency)
        let to_rate: Float64 = this.rates.get(to_currency)
        let amount_in_usd: Float64 = amount / from_rate
        return amount_in_usd * to_rate
    }

    public func get_supported_currencies(): ArrayList<String> {
        /*
        Returns a list of supported currency types
        :return: ArrayList<String>, All supported currency types
        >>> cc = CurrencyConverter()
        >>> cc.get_supported_currencies()
        ['USD','EUR','GBP','JPY','CAD','AUD','CNY']
        */
        let list = ArrayList<String>()
        for k in this.rates.keys() {
            list.add(k)
        }
        return list
    }

    public func add_currency_rate(currency: String, rate: Float64): Bool {
        /*
        Add a new supported currency type, return false if the currency type is already in the support list
        :param currency:String, currency type to be added
        :param rate:Float64, exchange rate for this type of currency
        :return:If successful, returns true; if unsuccessful, returns false
        >>> cc = CurrencyConverter()
        >>> cc.add_currency_rate('KRW', 1308.84)
        true
        this.rates['KRW'] = 1308.84
        */
        if this.rates.containsKey(currency) {
            return false
        }
        this.rates.add(currency, rate)
        return true
    }

    public func update_currency_rate(currency: String, new_rate: Float64): Bool {
        /*
        Update the exchange rate for a certain currency
        :param currency:String
        :param new_rate:Float64
        :return:If successful, returns true; if unsuccessful, returns false
        >>> cc = CurrencyConverter()
        >>> cc.update_currency_rate('CNY', 7.18)
        true
        this.rates['CNY'] = 7.18
        */
        if !this.rates.containsKey(currency) {
            return false
        }
        this.rates.add(currency, new_rate)
        return true
    }
}

import std.collection.HashMap
import std.collection.ArrayList
import std.math.round
import std.math.abs
import std.sort.sort

class DataStatistics {

    /*
    This is a class for performing data statistics, supporting to calculate the mean, median, and mode of a given data set.
    */

    private func round2(x: Float64): Float64 {
        // Round to two decimal places
        return round(x * 100.0) / 100.0
    }

    public func mean(data: ArrayList<Int64>): Float64 {
        /*
        Calculate the average value of a group of data, accurate to two digits after the Decimal separator
        :param data:ArrayList<Int64>, data list
        :return:Float64, the mean value
        >>> ds = DataStatistics()
        >>> ds.mean(ArrayList<Int64>([1, 2, 3, 4, 5]))
        3.00
        */
        if data.size() == 0 {
            return 0.0
        }

        var total: Float64 = 0.0
        for v in data {
            total += Float64(v)
        }
        let n = data.size()
        let avg = total / Float64(n)
        return this.round2(avg)
    }

    public func median(data: ArrayList<Int64>): Float64 {
        /*
        Calculate the median of a group of data, accurate to two digits after the Decimal separator
        :param data:ArrayList<Int64>, data list
        :return:Float64, the median value
        >>> ds = DataStatistics()
        >>> ds.median(ArrayList<Int64>([2, 5, 1, 3, 4]))
        3.00
        */
        let n = data.size()
        if n == 0 {
            return 0.0
        }

        // Copy and sort data
        var sorted = ArrayList<Int64>()
        for v in data {
            sorted.add(v)
        }
        sort(sorted)

        if n % 2 == 1 {
            let mid = sorted.get(n / 2)
            return this.round2(Float64(mid))
        } else {
            let mid1 = sorted.get((n / 2) - 1)
            let mid2 = sorted.get(n / 2)
            let med = (Float64(mid1) + Float64(mid2)) / 2.0
            return this.round2(med)
        }
    }

    public func mode(data: ArrayList<Int64>): ArrayList<Int64> {
        /*
        Calculate the mode of a set of data
        :param data:ArrayList<Int64>, data list
        :return:ArrayList<Int64>, the mode
        >>> ds = DataStatistics()
        >>> ds.mode(ArrayList<Int64>([2, 2, 3, 3, 4]))
        [2, 3]
        */
        var result = ArrayList<Int64>()
        let n = data.size()
        if n == 0 {
            return result
        }

        // Sort to count runs
        var sorted = ArrayList<Int64>()
        for v in data {
            sorted.add(v)
        }
        sort(sorted)

        var maxCount = 0
        var runCount = 0
        var first = true
        var prev: Int64 = 0

        for v in sorted {
            if first {
                prev = v
                runCount = 1
                first = false
            } else if v == prev {
                runCount += 1
            } else {
                // run for prev ended
                if runCount > maxCount {
                    maxCount = runCount
                    result.clear()
                    result.add(prev)
                } else if runCount == maxCount {
                    result.add(prev)
                }
                prev = v
                runCount = 1
            }
        }

        // finalize last run
        if runCount > maxCount {
            maxCount = runCount
            result.clear()
            result.add(prev)
        } else if runCount == maxCount {
            result.add(prev)
        }

        return result
    }
}

import std.collection.ArrayList
import std.math.round
import std.math.sqrt
import std.math.abs

class DataStatistics2 {

    /*
    This is a class for performing data statistics, supporting to get the sum, minimum, maximum, variance, standard deviation, and correlation of a given dataset.
    */

    let data: ArrayList<Float64>

    public init(data: ArrayList<Float64>) {
        /*
        Initialize Data List
        :param data:ArrayList<Float64>
        */
        this.data = data
    }

    private func round2(value: Float64): Float64 {
        return round(value * 100.0) / 100.0
    }

    public func get_sum(): Float64 {
        /*
        Calculate the sum of data
        :return:Float64
        >>> ds2 = DataStatistics2(ArrayList<Float64>([1.0, 2.0, 3.0, 4.0]))
        >>> ds2.get_sum()
        10.0
        */
        let n: Int = this.data.size()
        var total: Float64 = 0.0
        var i: Int = 0
        while i < n {
            total = total + this.data.get(i)
            i = i + 1
        }
        return total
    }

    public func get_min(): Float64 {
        /*
        Calculate the minimum value in the data
        :return:Float64
        >>> ds2 = DataStatistics2(ArrayList<Float64>([1.0, 2.0, 3.0, 4.0]))
        >>> ds2.get_min()
        1.0
        */
        let n: Int = this.data.size()
        if n == 0 {
            return 0.0
        }
        var m: Float64 = this.data.get(0)
        var i: Int = 1
        while i < n {
            let v: Float64 = this.data.get(i)
            if v < m {
                m = v
            }
            i = i + 1
        }
        return m
    }

    public func get_max(): Float64 {
        /*
        Calculate the maximum value in the data
        :return:Float64
        >>> ds2 = DataStatistics2(ArrayList<Float64>([1.0, 2.0, 3.0, 4.0]))
        >>> ds2.get_max()
        4.0
        */
        let n: Int = this.data.size()
        if n == 0 {
            return 0.0
        }
        var m: Float64 = this.data.get(0)
        var i: Int = 1
        while i < n {
            let v: Float64 = this.data.get(i)
            if v > m {
                m = v
            }
            i = i + 1
        }
        return m
    }

    public func get_variance(): Float64 {
        /*
        Calculate variance, accurate to two digits after the Decimal separator
        :return:Float64
        >>> ds2 = DataStatistics2(ArrayList<Float64>([1.0, 2.0, 3.0, 4.0]))
        >>> ds2.get_variance()
        1.25
        */
        let n: Int = this.data.size()
        if n == 0 {
            return 0.0
        }
        let nf: Float64 = Float64(n)
        let sum: Float64 = this.get_sum()
        let mean: Float64 = sum / nf

        var sqSum: Float64 = 0.0
        var i: Int = 0
        while i < n {
            let d: Float64 = this.data.get(i) - mean
            sqSum = sqSum + d * d
            i = i + 1
        }
        let variance: Float64 = sqSum / nf
        return this.round2(variance)
    }

    public func get_std_deviation(): Float64 {
        /*
        Calculate standard deviation, accurate to two digits after the Decimal separator
        :return:Float64
        >>> ds2 = DataStatistics2(ArrayList<Float64>([1.0, 2.0, 3.0, 4.0]))
        >>> ds2.get_std_deviation()
        1.12
        */
        let variance: Float64 = this.get_variance()
        let stddev: Float64 = sqrt(variance)
        return this.round2(stddev)
    }

    public func get_correlation(): Float64 {
        /*
        Calculate correlation
        :return:Float64
        >>> ds2 = DataStatistics2(ArrayList<Float64>([1.0, 2.0, 3.0, 4.0]))
        >>> ds2.get_correlation()
        1.0
        */
        let n: Int = this.data.size()
        if n <= 1 {
            return 0.0
        }

        // x is 1..n
        let nf: Float64 = Float64(n)
        let meanX: Float64 = (nf + 1.0) / 2.0

        // Mean of Y
        let sumY: Float64 = this.get_sum()
        let meanY: Float64 = sumY / nf

        // Compute Syy and numerator sum((x - meanX)*(y - meanY))
        var sYY: Float64 = 0.0
        var numerator: Float64 = 0.0
        var i: Int = 0
        while i < n {
            let xi: Float64 = Float64(i + 1)
            let yi: Float64 = this.data.get(i)
            let dx: Float64 = xi - meanX
            let dy: Float64 = yi - meanY
            numerator = numerator + dx * dy
            sYY = sYY + dy * dy
            i = i + 1
        }

        // Closed-form Sxx for 1..n
        // Sxx = sum_{i=1}^n (i - meanX)^2 = n(n^2 - 1)/12
        let sXX: Float64 = nf * (nf * nf - 1.0) / 12.0

        if sXX == 0.0 || sYY == 0.0 {
            return 0.0
        }

        let corr: Float64 = numerator / sqrt(sXX * sYY)
        return corr
    }
}

import std.collection.ArrayList
import std.math.sqrt
import std.math.exp
import std.math.abs

class DataStatistics4 {

    /*
    This is a class that performs advanced mathematical calculations and statistics, including correlation coefficient, skewness, kurtosis, and probability density function (PDF) for a normal distribution.
    */

    public static func correlation_coefficient(data1: ArrayList<Float64>, data2: ArrayList<Float64>): Float64 {
        /*
        Calculate the correlation coefficient of two sets of data.
        :param data1: The first set of data,ArrayList<Float64>.
        :param data2: The second set of data,ArrayList<Float64>.
        :return: The correlation coefficient, Float64.
        >>> DataStatistics4.correlation_coefficient(ArrayList<Float64>([1.0, 2.0, 3.0]), ArrayList<Float64>([4.0, 5.0, 6.0]))
        0.9999999999999998

        */
        let n: Int = data1.size()
        if n == 0 || n != data2.size() {
            return 0.0
        }

        var sum1: Float64 = 0.0
        var sum2: Float64 = 0.0
        var i: Int = 0
        while i < n {
            sum1 += data1.get(i)
            sum2 += data2.get(i)
            i += 1
        }

        let mean1: Float64 = sum1 / Float64(n)
        let mean2: Float64 = sum2 / Float64(n)

        var sxx: Float64 = 0.0
        var syy: Float64 = 0.0
        var sxy: Float64 = 0.0

        i = 0
        while i < n {
            let dx: Float64 = data1.get(i) - mean1
            let dy: Float64 = data2.get(i) - mean2
            sxx += dx * dx
            syy += dy * dy
            sxy += dx * dy
            i += 1
        }

        let denom: Float64 = sqrt(sxx * syy)
        if denom == 0.0 {
            return 0.0
        }
        return sxy / denom
    }

    public static func skewness(data: ArrayList<Float64>): Float64 {
        /*
        Calculate the skewness of a set of data.
        :param data: The input data list, ArrayList<Float64>.
        :return: The skewness, Float64.
        >>> DataStatistics4.skewness(ArrayList<Float64>([1.0, 2.0, 5.0]))
        2.3760224064818463

        */
        let n: Int = data.size()
        if n < 3 {
            return 0.0
        }

        var sum: Float64 = 0.0
        var i: Int = 0
        while i < n {
            sum += data.get(i)
            i += 1
        }
        let mu: Float64 = sum / Float64(n)

        var sum2: Float64 = 0.0
        var sum3: Float64 = 0.0
        i = 0
        while i < n {
            let d: Float64 = data.get(i) - mu
            let d2: Float64 = d * d
            sum2 += d2
            sum3 += d2 * d
            i += 1
        }

        let m2: Float64 = sum2 / Float64(n)  // population second central moment
        if m2 == 0.0 {
            return 0.0
        }
        let sp: Float64 = sqrt(m2)           // population standard deviation
        let sp3: Float64 = sp * sp * sp

        let numer: Float64 = Float64(n) * sum3
        let denom: Float64 = Float64(n - 1) * Float64(n - 2) * sp3
        if denom == 0.0 {
            return 0.0
        }
        return numer / denom
    }

    public static func kurtosis(data: ArrayList<Float64>): Float64 {
        /*
        Calculate the kurtosis of a set of data.
        :param data: The input data list, ArrayList<Float64>.
        :return: The kurtosis, Float64.
        >>> DataStatistics4.kurtosis(ArrayList<Float64>([1.0, 2.0, 5.0]))
        -1.5000000000000007

        */
        let n: Int = data.size()
        if n == 0 {
            return 0.0
        }

        var sum: Float64 = 0.0
        var i: Int = 0
        while i < n {
            sum += data.get(i)
            i += 1
        }
        let mu: Float64 = sum / Float64(n)

        var sum2: Float64 = 0.0
        var sum4: Float64 = 0.0
        i = 0
        while i < n {
            let d: Float64 = data.get(i) - mu
            let d2: Float64 = d * d
            sum2 += d2
            sum4 += d2 * d2
            i += 1
        }

        let m2: Float64 = sum2 / Float64(n)  // population second central moment
        if m2 == 0.0 {
            return 0.0
        }
        let m4: Float64 = sum4 / Float64(n)  // population fourth central moment

        return (m4 / (m2 * m2)) - 3.0
    }

    public static func pdf(data: ArrayList<Float64>, mu: Float64, sigma: Float64): ArrayList<Float64> {
        /*
        Calculate the probability density function (PDF) of a set of data under a normal distribution.
        :param data: The input data list, ArrayList<Float64>.
        :param mu: The mean of the normal distribution, Float64.
        :param sigma: The standard deviation of the normal distribution, Float64.
        :return: The probability density function (PDF), ArrayList<Float64>.
        >>> DataStatistics4.pdf(ArrayList<Float64>([1.0, 2.0, 3.0]), 1.0, 1.0)
        [0.3989422804014327, 0.24197072451914337, 0.05399096651318806]

        */
        let PI: Float64 = 3.141592653589793
        let result: ArrayList<Float64> = ArrayList<Float64>()

        if sigma <= 0.0 {
            var i: Int = 0
            while i < data.size() {
                result.add(0.0)
                i += 1
            }
            return result
        }

        let coeff: Float64 = 1.0 / (sigma * sqrt(2.0 * PI))
        let twoSigma2: Float64 = 2.0 * sigma * sigma

        var i: Int = 0
        while i < data.size() {
            let x: Float64 = data.get(i)
            let z: Float64 = x - mu
            let density: Float64 = coeff * exp(-(z * z) / twoSigma2)
            result.add(density)
            i += 1
        }
        return result
    }
}

import std.collection.ArrayList

class DecryptionUtils {

    /*
    This is a class that provides methods for decryption, including the Caesar cipher, Vigenere cipher, and Rail Fence cipher.
    */

    let key: String

    public init(key: String) {
        /*
        Initializes the decryption utility with a key.
        :param key: The key to use for decryption,String.
        */
        this.key = key
    }

    public func caesar_decipher(ciphertext: String, shift: Int64): String {
        /*
        Deciphers the given ciphertext using the Caesar cipher
        :param ciphertext: The ciphertext to decipher,String.
        :param shift: The shift to use for decryption,Int64.
        :return: The deciphered plaintext,String.
        >>> d = DecryptionUtils('key')
        >>> d.caesar_decipher('ifmmp', 1)
        'hello'

        */
        let lowercase: String = "abcdefghijklmnopqrstuvwxyz"
        let uppercase: String = "ABCDEFGHIJKLMNOPQRSTUVWXYZ"

        let n: Int64 = ciphertext.length()
        var result: String = ""

        let normShift: Int64 = this._normalize_shift(shift)

        var i: Int64 = 0
        while (i < n) {
            let ch: String = ciphertext.charAt(i)

            let li: Int64 = this._index_in_alphabet(lowercase, ch)
            if (li != -1) {
                let newIdx: Int64 = this._mod(li - normShift, 26)
                result = result + lowercase.charAt(newIdx)
                i = i + 1
                continue
            }

            let ui: Int64 = this._index_in_alphabet(uppercase, ch)
            if (ui != -1) {
                let newIdx: Int64 = this._mod(ui - normShift, 26)
                result = result + uppercase.charAt(newIdx)
                i = i + 1
                continue
            }

            result = result + ch
            i = i + 1
        }

        return result
    }

    public func vigenere_decipher(ciphertext: String): String {
        /*
        Deciphers the given ciphertext using the Vigenere cipher
        :param ciphertext: The ciphertext to decipher,String.
        :return: The deciphered plaintext,String.
        >>> d = DecryptionUtils('key')
        >>> d.vigenere_decipher('ifmmp')
        'ybocl'

        */
        let lowercase: String = "abcdefghijklmnopqrstuvwxyz"
        let uppercase: String = "ABCDEFGHIJKLMNOPQRSTUVWXYZ"

        let n: Int64 = ciphertext.length()
        let klen: Int64 = this.key.length()
        if (klen == 0) {
            return ciphertext
        }

        var result: String = ""
        var keyPos: Int64 = 0

        var i: Int64 = 0
        while (i < n) {
            let ch: String = ciphertext.charAt(i)

            let li: Int64 = this._index_in_alphabet(lowercase, ch)
            let ui: Int64 = this._index_in_alphabet(uppercase, ch)

            if (li == -1 && ui == -1) {
                // Non-letter: pass through without advancing key
                result = result + ch
                i = i + 1
                continue
            }

            // Determine shift from key character (letters only)
            var kch: String = this.key.charAt(this._mod(keyPos, klen))
            var kShift: Int64 = this._index_in_alphabet(lowercase, kch)
            if (kShift == -1) {
                kShift = this._index_in_alphabet(uppercase, kch)
            }
            // If still -1 (non-letter in key), treat as zero shift and don't advance keyPos for this round
            if (kShift == -1) {
                kShift = 0
            } else {
                keyPos = keyPos + 1
            }

            if (li != -1) {
                let newIdx: Int64 = this._mod(li - kShift, 26)
                result = result + lowercase.charAt(newIdx)
            } else {
                let newIdx: Int64 = this._mod(ui - kShift, 26)
                result = result + uppercase.charAt(newIdx)
            }

            i = i + 1
        }

        return result
    }

    public func rail_fence_decipher(encrypted_text: String, rails: Int64): String {
        /*
        Deciphers the given ciphertext using the Rail Fence cipher
        :param encrypted_text: The ciphertext to decipher,String.
        :param rails: The number of rails to use for decryption,Int64.
        :return: The deciphered plaintext,String.
        >>> d = DecryptionUtils('key')
        >>> d.rail_fence_decipher('Hoo!el,Wrdl l', 3)
        'Hello, World!'

        */
        let n: Int64 = encrypted_text.length()
        if (rails <= 1 || rails >= n) {
            return encrypted_text
        }

        // Step 1: Build the zig-zag pattern rows for each index
        var pattern: ArrayList<Int64> = ArrayList<Int64>()
        var row: Int64 = 0
        var dir: Int64 = 1  // 1 down, -1 up

        var i: Int64 = 0
        while (i < n) {
            pattern.add(row)

            if (row == 0) {
                dir = 1
            } else if (row == rails - 1) {
                dir = -1
            }
            row = row + dir

            i = i + 1
        }

        // Step 2: Count how many positions belong to each rail
        var counts: ArrayList<Int64> = ArrayList<Int64>()
        var r: Int64 = 0
        while (r < rails) {
            counts.add(0)
            r = r + 1
        }

        i = 0
        while (i < n) {
            let pr: Int64 = pattern.get(i)
            let curr: Int64 = counts.get(pr)
            counts.set(pr, curr + 1)
            i = i + 1
        }

        // Step 3: Compute starting indices for each rail in the encrypted text
        var starts: ArrayList<Int64> = ArrayList<Int64>()
        var acc: Int64 = 0
        r = 0
        while (r < rails) {
            starts.add(acc)
            acc = acc + counts.get(r)
            r = r + 1
        }

        // Step 4: Current read position per rail
        var currPos: ArrayList<Int64> = ArrayList<Int64>()
        r = 0
        while (r < rails) {
            currPos.add(starts.get(r))
            r = r + 1
        }

        // Step 5: Reconstruct plaintext by reading in the zig-zag order
        var plaintextChars: ArrayList<String> = ArrayList<String>()
        // initialize with placeholders
        i = 0
        while (i < n) {
            plaintextChars.add("")
            i = i + 1
        }

        i = 0
        while (i < n) {
            let pr: Int64 = pattern.get(i)
            let readIdx: Int64 = currPos.get(pr)
            let ch: String = encrypted_text.charAt(readIdx)
            plaintextChars.set(i, ch)
            currPos.set(pr, readIdx + 1)
            i = i + 1
        }

        // Step 6: Join
        var result: String = ""
        i = 0
        while (i < n) {
            result = result + plaintextChars.get(i)
            i = i + 1
        }

        return result
    }

    // Helper: normalize shift to 0..25
    func _normalize_shift(shift: Int64): Int64 {
        return this._mod(shift, 26)
    }

    // Helper: modulo handling negative numbers
    func _mod(a: Int64, m: Int64): Int64 {
        var r: Int64 = a % m
        if (r < 0) {
            r = r + m
        }
        return r
    }

    // Helper: find index of single-character string ch in alphabet, or -1
    func _index_in_alphabet(alphabet: String, ch: String): Int64 {
        let len: Int64 = alphabet.length()
        var i: Int64 = 0
        while (i < len) {
            if (alphabet.charAt(i) == ch) {
                return i
            }
            i = i + 1
        }
        return -1
    }
}

import std.collection.ArrayList

class EightPuzzle {

    /*
    This class is an implementation of the classic 8-puzzle game, including methods for finding the blank tile, making moves, getting possible moves, and solving the puzzle using a breadth-first search algorithm.
    */

    let initial_state: ArrayList<ArrayList<Int64>>
    let goal_state: ArrayList<ArrayList<Int64>>

    public init(initial_state: ArrayList<ArrayList<Int64>>) {
        /*
        Initializing the initial state of Eight Puzzle Game, stores in attribute this.initial_state.
        And set the goal state of this game, stores in this.goal_state. In this case, set the size as 3*3
        :param initial_state: a 3*3 size list of Integer, stores the initial state
        */
        this.initial_state = initial_state
        this.goal_state = ArrayList<ArrayList<Int64>>([ArrayList<Int64>([1, 2, 3]), ArrayList<Int64>([4, 5, 6]), ArrayList<Int64>([7, 8, 0])])
    }

    public func find_blank(state: ArrayList<ArrayList<Int64>>): (Int64, Int64) {
        /*
        Find the blank position of current state, which is the 0 element.
        :param state: a 3*3 size list of Integer, stores the current state.
        :return i, j: two Integers, represent the coordinate of the blank block.
        >>> eightPuzzle = EightPuzzle(ArrayList<ArrayList<Int64>>([ArrayList<Int64>([2, 3, 4]), ArrayList<Int64>([5, 8, 1]), ArrayList<Int64>([6, 0, 7])]))
        >>> eightPuzzle.find_blank(ArrayList<ArrayList<Int64>>([ArrayList<Int64>([2, 3, 4]), ArrayList<Int64>([5, 8, 1]), ArrayList<Int64>([6, 0, 7])]))
        (2, 1)
        */
        var i: Int64 = 0
        while i < 3 {
            let row = state.get(i)
            var j: Int64 = 0
            while j < 3 {
                if row.get(j) == 0 {
                    return (i, j)
                }
                j = j + 1
            }
            i = i + 1
        }
        return (-1, -1)
    }

    public func move(state: ArrayList<ArrayList<Int64>>, direction: String): ArrayList<ArrayList<Int64>> {
        /*
        Find the blank block, then makes the board moves forward the given direction.
        :param state: a 3*3 size list of Integer, stores the state before moving.
        :param direction: String, only has 4 direction 'up', 'down', 'left', 'right'
        :return new_state: a 3*3 size list of Integer, stores the state after moving.
        >>> eightPuzzle.move(ArrayList<ArrayList<Int64>>([ArrayList<Int64>([2, 3, 4]), ArrayList<Int64>([5, 8, 1]), ArrayList<Int64>([6, 0, 7])]), 'left')
        [[2, 3, 4], [5, 8, 1], [0, 6, 7]]
        */
        let new_state = this.copy_state(state)
        let (bi, bj) = this.find_blank(state)

        var ti: Int64 = bi
        var tj: Int64 = bj

        if direction == "up" {
            ti = bi - 1
            tj = bj
        } else if direction == "down" {
            ti = bi + 1
            tj = bj
        } else if direction == "left" {
            ti = bi
            tj = bj - 1
        } else if direction == "right" {
            ti = bi
            tj = bj + 1
        } else {
            // Invalid direction, return original state copy
            return new_state
        }

        if ti < 0 || ti >= 3 || tj < 0 || tj >= 3 {
            // Move out of bounds, return original state copy
            return new_state
        }

        let blankRow = new_state.get(bi)
        let targetRow = new_state.get(ti)
        let temp: Int64 = targetRow.get(tj)
        targetRow.set(tj, blankRow.get(bj))
        blankRow.set(bj, temp)

        return new_state
    }

    public func get_possible_moves(state: ArrayList<ArrayList<Int64>>): ArrayList<String> {
        /*
        According the current state, find all the possible moving directions. Only has 4 direction 'up', 'down', 'left', 'right'.
        :param state: a 3*3 size list of Integer, stores the current state.
        :return moves: a list of String, store all the possible moving directions according to the current state.
        >>> eightPuzzle.get_possible_moves(ArrayList<ArrayList<Int64>>([ArrayList<Int64>([2, 3, 4]), ArrayList<Int64>([5, 8, 1]), ArrayList<Int64>([6, 0, 7])]))
        ['up', 'left', 'right']
        */
        let moves = ArrayList<String>()
        let (bi, bj) = this.find_blank(state)

        if bi > 0 {
            moves.add("up")
        }
        if bi < 2 {
            moves.add("down")
        }
        if bj > 0 {
            moves.add("left")
        }
        if bj < 2 {
            moves.add("right")
        }

        return moves
    }

    public func solve(): ArrayList<String> {
        /*
        Use BFS algorithm to find the path solution which makes the initial state to the goal method.
        Maintain a list as a queue, named as open_list, append the initial state.
        Always visit and pop the 0 index element, invoke get_possible_moves method find all the possible directions.
        Traversal the possible_moves list and invoke move method to get several new states.Then append them.
        redo the above steps until the open_list is empty or the state has changed to the goal state.
        :return path: list of String, the solution to the goal state.
        >>> eightPuzzle = EightPuzzle(ArrayList<ArrayList<Int64>>([ArrayList<Int64>([1, 2, 3]), ArrayList<Int64>([4, 5, 6]), ArrayList<Int64>([7, 0, 8])]))
        >>> eightPuzzle.solve()
        ['right']
        */
        // Queues implemented via ArrayList with advancing index
        let open_states = ArrayList<ArrayList<ArrayList<Int64>>>()
        let open_paths = ArrayList<ArrayList<String>>()
        let visited = ArrayList<String>()

        open_states.add(this.copy_state(this.initial_state))
        open_paths.add(ArrayList<String>())

        var idx: Int64 = 0
        while idx < open_states.size() {
            let current_state = open_states.get(idx)
            let current_path = open_paths.get(idx)

            if this.states_equal(current_state, this.goal_state) {
                return current_path
            }

            let key = this.serialize_state(current_state)
            if !visited.contains(key) {
                visited.add(key)
                let moves = this.get_possible_moves(current_state)
                var m: Int64 = 0
                while m < moves.size() {
                    let mv = moves.get(m)
                    let next_state = this.move(current_state, mv)
                    let next_key = this.serialize_state(next_state)
                    if !visited.contains(next_key) {
                        let next_path = this.clone_string_list(current_path)
                        next_path.add(mv)
                        open_states.add(next_state)
                        open_paths.add(next_path)
                    }
                    m = m + 1
                }
            }

            idx = idx + 1
        }

        return ArrayList<String>()
    }

    private func copy_state(state: ArrayList<ArrayList<Int64>>): ArrayList<ArrayList<Int64>> {
        let new_state = ArrayList<ArrayList<Int64>>()
        var i: Int64 = 0
        while i < 3 {
            let row = state.get(i)
            let new_row = ArrayList<Int64>()
            var j: Int64 = 0
            while j < 3 {
                new_row.add(row.get(j))
                j = j + 1
            }
            new_state.add(new_row)
            i = i + 1
        }
        return new_state
    }

    private func states_equal(a: ArrayList<ArrayList<Int64>>, b: ArrayList<ArrayList<Int64>>): Bool {
        var i: Int64 = 0
        while i < 3 {
            let ra = a.get(i)
            let rb = b.get(i)
            var j: Int64 = 0
            while j < 3 {
                if ra.get(j) != rb.get(j) {
                    return false
                }
                j = j + 1
            }
            i = i + 1
        }
        return true
    }

    private func serialize_state(state: ArrayList<ArrayList<Int64>>): String {
        var s: String = ""
        var i: Int64 = 0
        while i < 3 {
            let row = state.get(i)
            var j: Int64 = 0
            while j < 3 {
                s = s + row.get(j).toString() + ","
                j = j + 1
            }
            i = i + 1
        }
        return s
    }

    private func clone_string_list(lst: ArrayList<String>): ArrayList<String> {
        let res = ArrayList<String>()
        var i: Int64 = 0
        while i < lst.size() {
            res.add(lst.get(i))
            i = i + 1
        }
        return res
    }
}

import std.time.DateTime
import std.collection.ArrayList
import std.collection.HashMap

class EmailClient {

    /*
    This is a class that serves as an email client, implementing functions such as checking emails, determining whether there is sufficient space, and cleaning up space
    */

    let addr: String
    let capacity: Int64
    var inbox: ArrayList<HashMap<String, Any>>

    public init(addr: String, capacity: Int64) {
        /*
        Initializes the EmailClient class with the email address and the capacity of the email box.
        :param addr: The email address, String.
        :param capacity: The capacity of the email box, Int64.
        */
        this.addr = addr
        this.capacity = capacity
        this.inbox = ArrayList<HashMap<String, Any>>()
    }

    public func send_to(recv: EmailClient, content: String, size: Int64): Bool {
        /*
        Sends an email to the given email address.
        :param recv: The email address of the receiver, String.
        :param content: The content of the email, String.
        :param size: The size of the email, Int64.
        :return: true if the email is sent successfully, false if the receiver's email box is full.
        >>> sender = EmailClient('sender@example.com', 100)
        >>> receiver = EmailClient('receiver@example.com', 50)
        >>> sender.send_to(receiver, 'Hello', 10)
        true
        >>> receiver.inbox
        {'sender': 'sender@example.com', 'receiver': 'receiver@example.com', 'content': 'Hello', 'size': 10, 'time': '2023-07-13 11:36:40', 'state': 'unread'}

        */
        if recv.is_full_with_one_more_email(size) {
            return false
        }

        let email = HashMap<String, Any>()
        email.put("sender", this.addr)
        email.put("receiver", recv.addr)
        email.put("content", content)
        email.put("size", size)
        email.put("time", DateTime.now())
        email.put("state", "unread")

        recv.inbox.add(email)
        return true
    }

    public func fetch(): HashMap<String, Any> {
        /*
        Retrieves the first unread email in the email box and marks it as read.
        :return: The first unread email in the email box, HashMap<String, Any>
        >>> sender = EmailClient('sender@example.com', 100)
        >>> receiver = EmailClient('receiver@example.com', 50)
        >>> receiver.inbox = ArrayList<HashMap<String, Any>>([HashMap<String, Any>([('sender', 'sender@example.com'), ('receiver', 'receiver@example.com'), ('content', 'Hello'), ('size', 10), ('time', '2023-07-13 11:36:40'), ('state', 'unread')])])
        >>> receiver.fetch()
        {'sender': 'sender@example.com', 'receiver': 'receiver@example.com', 'content': 'Hello', 'size': 10, 'time': '2023-07-13 11:36:40', 'state': 'read'}

        */
        var i: Int64 = 0
        while i < this.inbox.size() {
            let mail = this.inbox.get(i)
            let st = mail.get("state")
            if st == "unread" {
                mail.put("state", "read")
                return mail
            }
            i = i + 1
        }
        return HashMap<String, Any>()
    }

    public func is_full_with_one_more_email(size: Int64): Bool {
        /*
        Determines whether the email box is full after adding an email of the given size.
        :param size: The size of the email, Int64.
        :return: true if the email box is full, false otherwise.
        >>> sender = EmailClient('sender@example.com', 100)
        >>> receiver = EmailClient('receiver@example.com', 50)
        >>> receiver.is_full_with_one_more_email(10)
        false

        */
        return this.get_occupied_size() + size > this.capacity
    }

    public func get_occupied_size(): Int64 {
        /*
        Gets the total size of the emails in the email box.
        :return: The total size of the emails in the email box, Int64.
        >>> sender = EmailClient('sender@example.com', 100)
        >>> receiver = EmailClient('receiver@example.com', 50)
        >>> sender.inbox = ArrayList<HashMap<String, Any>>([HashMap<String, Any>([('sender', 'sender@example.com'), ('receiver', 'receiver@example.com'), ('content', 'Hello'), ('size', 10), ('time', DateTime.now()), ('state', 'unread')])])
        >>> sender.get_occupied_size()
        10

        */
        var total: Int64 = 0
        var i: Int64 = 0
        while i < this.inbox.size() {
            let mail = this.inbox.get(i)
            let s = mail.get("size") as Int64
            total = total + s
            i = i + 1
        }
        return total
    }

    public func clear_inbox(size: Int64): Unit {
        /*
        Clears the email box by deleting the oldest emails until the email box has enough space to accommodate the given size.
        :param size: The size of the email, Int64.
        >>> sender = EmailClient('sender@example.com', 100)
        >>> receiver = EmailClient('receiver@example.com', 50)
        >>> receiver.inbox = ArrayList<HashMap<String, Any>>([HashMap<String, Any>([('size', 10)]), HashMap<String, Any>([('size', 20)]), HashMap<String, Any>([('size', 15)])])
        >>> receiver.clear_inbox(30)
        >>> receiver.inbox
        [{'size': 15}]

        */
        while this.get_occupied_size() + size > this.capacity && this.inbox.size() > 0 {
            this.inbox.removeAt(0)
        }
    }
}

import std.collection.ArrayList

class EncryptionUtils {

    /*
    This is a class that provides methods for encryption, including the Caesar cipher, Vigenere cipher, and Rail Fence cipher.
    */

    let key: String

    public init(key: String) {
        /*
        Initializes the class with a key.
        :param key: The key to use for encryption, String.
        */
        this.key = key
    }

    private func charAt(s: String, index: Int64): String {
        return s.substring(index, index + 1)
    }

    private func indexOf(s: String, ch: String): Int64 {
        let n = s.length
        var i: Int64 = 0
        while i < n {
            if s.substring(i, i + 1) == ch {
                return i
            }
            i = i + 1
        }
        return -1
    }

    private func normalizeShift(shift: Int64, base: Int64): Int64 {
        var r = shift % base
        if r < 0 {
            r = r + base
        }
        return r
    }

    public func caesar_cipher(plaintext: String, shift: Int64): String {
        /*
        Encrypts the plaintext using the Caesar cipher.
        :param plaintext: The plaintext to encrypt, String.
        :param shift: The number of characters to shift each character in the plaintext, Int64.
        :return: The ciphertext, String.
        >>> e = EncryptionUtils("key")
        >>> e.caesar_cipher("abc", 1)
        'bcd'

        */
        let lower = "abcdefghijklmnopqrstuvwxyz"
        let upper = "ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        let n = plaintext.length
        let s = this.normalizeShift(shift, 26)
        var out = ""
        var i: Int64 = 0
        while i < n {
            let ch = this.charAt(plaintext, i)
            let li = this.indexOf(lower, ch)
            if li != -1 {
                let ni = (li + s) % 26
                out = out + this.charAt(lower, ni)
            } else {
                let ui = this.indexOf(upper, ch)
                if ui != -1 {
                    let ni = (ui + s) % 26
                    out = out + this.charAt(upper, ni)
                } else {
                    out = out + ch
                }
            }
            i = i + 1
        }
        return out
    }

    public func vigenere_cipher(plain_text: String): String {
        /*
        Encrypts the plaintext using the Vigenere cipher.
        :param plaintext: The plaintext to encrypt, String.
        :return: The ciphertext, String.
        >>> e = EncryptionUtils("key")
        >>> e.vigenere_cipher("abc")
        'kfa'

        */
        let lower = "abcdefghijklmnopqrstuvwxyz"
        let upper = "ABCDEFGHIJKLMNOPQRSTUVWXYZ"

        let keyLen = this.key.length
        if keyLen == 0 {
            return plain_text
        }

        var out = ""
        var ki: Int64 = 0
        let n = plain_text.length
        var i: Int64 = 0
        while i < n {
            let ch = this.charAt(plain_text, i)
            let li = this.indexOf(lower, ch)
            let ui = this.indexOf(upper, ch)

            if li != -1 || ui != -1 {
                // Determine key shift from current key character
                let kch = this.charAt(this.key, ki % keyLen)
                var kShift = this.indexOf(lower, kch)
                if kShift == -1 {
                    kShift = this.indexOf(upper, kch)
                }
                if kShift == -1 {
                    kShift = 0
                }

                if li != -1 {
                    let ni = (li + kShift) % 26
                    out = out + this.charAt(lower, ni)
                } else {
                    let ni = (ui + kShift) % 26
                    out = out + this.charAt(upper, ni)
                }
                ki = ki + 1
            } else {
                out = out + ch
            }
            i = i + 1
        }
        return out
    }

    public func rail_fence_cipher(plain_text: String, rails: Int64): String {
        /*
        Encrypts the plaintext using the Rail Fence cipher.
        :param plaintext: The plaintext to encrypt, String.
        :return: The ciphertext, String.
        >>> e = EncryptionUtils("key")
        >>> e.rail_fence_cipher("abc", 2)
        'acb'

        */
        let n = plain_text.length
        if rails <= 1 || rails >= n {
            return plain_text
        }

        let rows = ArrayList<String>()
        var r: Int64 = 0
        while r < rails {
            rows.add("")
            r = r + 1
        }

        var row: Int64 = 0
        var dir: Int64 = 1  // 1 for down, -1 for up

        var i: Int64 = 0
        while i < n {
            let ch = this.charAt(plain_text, i)
            let cur = rows.get(row)
            rows.set(row, cur + ch)

            row = row + dir
            if row == 0 || row == (rails - 1) {
                dir = 0 - dir
            }
            i = i + 1
        }

        var out = ""
        var j: Int64 = 0
        while j < rails {
            out = out + rows.get(j)
            j = j + 1
        }
        return out
    }
}

import std.math.numeric.Decimal
import std.regex.Regex
import std.collection.ArrayList

class ExpressionCalculator {

    /*
    This is a class in Cangjie that can perform calculations with basic arithmetic operations, including addition, subtraction, multiplication, division, and modulo.
    */

    let postfix_stack: ArrayList<String>
    let operat_priority: ArrayList<Int64>

    public init() {
        /*
        Initialize the expression calculator
        */
        postfix_stack = ArrayList<String>()
        operat_priority = ArrayList<Int64>([0, 3, 2, 1, -1, 1, 0, 2])
    }

    public func calculate(expression: String): Float64 {
        /*
        Calculate the result of the given postfix expression
        :param expression: String, the postfix expression to be calculated
        :return: Float64, the calculated result
        >>> expression_calculator = ExpressionCalculator()
        >>> expression_calculator.calculate("2 + 3 * 4")
        14.0

        */
        let prepared = ExpressionCalculator.transform(expression)
        prepare(prepared)

        let values = ArrayList<Decimal>()
        var i: Int64 = 0
        let n: Int64 = postfix_stack.size()
        while i < n {
            let token = postfix_stack.get(i)
            if ExpressionCalculator.is_operator(token) {
                // Parentheses should not appear in postfix, but ignore safely
                if token == "(" || token == ")" {
                    i = i + 1
                    continue
                }
                // Pop operands: second first, then first
                let bIdx = values.size() - 1
                let b = values.get(bIdx)
                values.removeAt(bIdx)
                let aIdx = values.size() - 1
                let a = values.get(aIdx)
                values.removeAt(aIdx)
                let res = ExpressionCalculator._calculate(a, b, token)
                values.add(res)
            } else {
                // number
                let val = Decimal.parse(token)
                values.add(val)
            }
            i = i + 1
        }

        // Final result
        let resultIdx = values.size() - 1
        let resultDec = values.get(resultIdx)
        return resultDec.toFloat64()
    }

    public func prepare(expression: String): Unit {
        /*
        Prepare the infix expression for conversion to postfix notation
        :param expression: String, the infix expression to be prepared
        >>> expression_calculator = ExpressionCalculator()
        >>> expression_calculator.prepare("2+3*4")

        expression_calculator.postfix_stack = ['2', '3', '4', '*', '+']
        */
        // Clear any previous state
        postfix_stack.clear()

        let output = ArrayList<String>()
        let ops = ArrayList<String>()

        var i: Int64 = 0
        let n: Int64 = expression.length()

        while i < n {
            let c = expression.charAt(i)

            // Number (possibly with unary minus)
            if c == "." || (c >= "0" && c <= "9") || (c == "-" && (i == 0 || ExpressionCalculator.is_operator(expression.charAt(i - 1))) ) {
                // Handle unary minus before a number: "-123.45"
                var num = ""
                if c == "-" && (i == 0 || ExpressionCalculator.is_operator(expression.charAt(i - 1))) {
                    // If "-(" occurs, treat as (0 - ( ... ))
                    if (i + 1) < n && expression.charAt(i + 1) == "(" {
                        // push implicit 0 and a '-' operator
                        output.add("0")
                        // process the '-' as an operator
                        let curOp = "-"
                        while ops.size() > 0 {
                            let topIdx = ops.size() - 1
                            let top = ops.get(topIdx)
                            if top == "(" {
                                break
                            }
                            if compare(top, curOp) {
                                ops.removeAt(topIdx)
                                output.add(top)
                            } else {
                                break
                            }
                        }
                        ops.add(curOp)
                        i = i + 1
                        continue
                    } else {
                        num = num + "-"
                        i = i + 1
                        // fallthrough to parse number after the sign
                    }
                }

                // Parse digits and decimal point
                while i < n {
                    let ch = expression.charAt(i)
                    if (ch >= "0" && ch <= "9") || ch == "." {
                        num = num + ch
                        i = i + 1
                    } else {
                        break
                    }
                }
                output.add(num)
                continue
            }

            // Parentheses
            if c == "(" {
                ops.add(c)
                i = i + 1
                continue
            }
            if c == ")" {
                while ops.size() > 0 {
                    let topIdx = ops.size() - 1
                    let top = ops.get(topIdx)
                    if top == "(" {
                        ops.removeAt(topIdx)
                        break
                    } else {
                        ops.removeAt(topIdx)
                        output.add(top)
                    }
                }
                i = i + 1
                continue
            }

            // Operators
            if ExpressionCalculator.is_operator(c) {
                let curOp = c
                while ops.size() > 0 {
                    let topIdx = ops.size() - 1
                    let top = ops.get(topIdx)
                    if top == "(" {
                        break
                    }
                    if compare(top, curOp) {
                        ops.removeAt(topIdx)
                        output.add(top)
                    } else {
                        break
                    }
                }
                ops.add(curOp)
                i = i + 1
                continue
            }

            // Unknown/whitespace (should not occur after transform), skip
            i = i + 1
        }

        // Drain remaining operators
        while ops.size() > 0 {
            let topIdx = ops.size() - 1
            let top = ops.get(topIdx)
            ops.removeAt(topIdx)
            if top != "(" && top != ")" {
                output.add(top)
            }
        }

        // Move output to postfix_stack
        var k: Int64 = 0
        while k < output.size() {
            postfix_stack.add(output.get(k))
            k = k + 1
        }
    }

    public static func is_operator(c: String): Bool {
        /*
        Check if a character is an operator in ['+', '-', '*', '/', '(', ')', '%']
        :param c: String, the character to be checked
        :return: Bool, true if the character is an operator, false otherwise
        >>> ExpressionCalculator.is_operator("+")
        true

        */
        return c == "+" || c == "-" || c == "*" || c == "/" || c == "(" || c == ")" || c == "%"
    }

    public func compare(cur: String, peek: String): Bool {
        /*
        Compare the precedence of two operators
        :param cur: String, the current operator
        :param peek: String, the operator at the top of the operator stack
        :return: Bool, true if the current operator has higher or equal precedence, false otherwise
        >>> expression_calculator = ExpressionCalculator()
        >>> expression_calculator.compare("+", "-")
        true

        */
        func prec(op: String): Int64 {
            if op == "+" || op == "-" {
                return 1
            } else if op == "*" || op == "/" || op == "%" {
                return 2
            } else {
                return 0
            }
        }
        return prec(cur) >= prec(peek)
    }

    public static func _calculate(first_value: Decimal, second_value: Decimal, current_op: String): Decimal {
        /*
        Perform the mathematical calculation based on the given operands and operator
        :param first_value: Decimal, the first operand
        :param second_value: Decimal, the second operand
        :param current_op: String, the operator
        :return: Decimal, the calculated result
        >>> ExpressionCalculator._calculate("2", "3", "+")
        5.0

        */
        if current_op == "+" {
            return first_value + second_value
        } else if current_op == "-" {
            return first_value - second_value
        } else if current_op == "*" {
            return first_value * second_value
        } else if current_op == "/" {
            return first_value / second_value
        } else if current_op == "%" {
            return first_value % second_value
        } else {
            // Unknown operator, return 0
            return Decimal.parse("0")
        }
    }

    public static func transform(expression: String): String {
        /*
        Transform the infix expression to a format suitable for conversion
        :param expression: String, the infix expression to be transformed
        :return: String, the transformed expression
        >>> ExpressionCalculator.transform("2 + 3 * 4")
        "2+3*4"

        */
        let pattern = Regex("\\s+")
        return pattern.replaceAll(expression, "")
    }
}

import std.collection.ArrayList
import std.collection.HashMap
import std.math.abs

class FitnessTracker {

    /*
    This is a class as fitness tracker that implements to calculate BMI (Body Mass Index) and calorie intake based on the user's height, weight, age, and sex.
    */

    let height: Float64
    let weight: Float64
    let age: Int64
    let sex: String
    let BMI_std: ArrayList<HashMap<String, ArrayList<Int64>>>

    public init(height: Float64, weight: Float64, age: Int64, sex: String) {
        /*
        Initialize the class with height, weight, age, and sex, and calculate the BMI standard based on sex, and male is 20-25, female is 19-24.
        */
        this.height = height
        this.weight = weight
        this.age = age
        this.sex = sex
        this.BMI_std = ArrayList<HashMap<String, ArrayList<Int64>>>()
        this.BMI_std.add(HashMap<String, ArrayList<Int64>>([("male", ArrayList<Int64>([20, 25]))]))
        this.BMI_std.add(HashMap<String, ArrayList<Int64>>([("female", ArrayList<Int64>([19, 24]))]))
    }

    public func get_BMI(): Float64 {
        /*
        Calculate the BMI based on the height and weight.
        :return: BMI,which is the weight divide by the square of height, Float64.
        >>> fitnessTracker = FitnessTracker(1.8, 70.0, 20, "male")
        >>> fitnessTracker.get_BMI()
        21.604938271604937

        */
        return this.weight / (this.height * this.height)
    }

    public func condition_judge(): Int64 {
        /*
        Judge the condition of the user based on the BMI standard.
        :return: 1 if the user is too fat, -1 if the user is too thin, 0 if the user is normal, Int64.
        >>> fitnessTracker = FitnessTracker(1.8, 70.0, 20, "male")
        >>> fitnessTracker.condition_judge()
        -1

        */
        let bmi: Float64 = this.get_BMI()
        var low: Float64
        var high: Float64

        if this.sex == "male" {
            low = Float64(22)
            high = Float64(25)
        } else if this.sex == "female" {
            low = Float64(19)
            high = Float64(24)
        } else {
            low = Float64(19)
            high = Float64(25)
        }

        if bmi > high {
            return Int64(1)
        } else if bmi < low {
            return Int64(-1)
        } else {
            return Int64(0)
        }
    }

    public func calculate_calorie_intake(): Float64 {
        /*
        Calculate the calorie intake based on the user's condition and BMR (Basal Metabolic Rate),BMR is calculated based on the user's height, weight, age, and sex,male is Float64(10) * this.weight + 6.25 * this.height - Float64(5) * Float64(this.age) + Float64(5),female is Float64(10) * this.weight + 6.25 * this.height - Float64(5) * Float64(this.age) - Float64(161), and the calorie intake is calculated based on the BMR and the user's condition,if the user is too fat, the calorie intake is BMR * 1.2, if the user is too thin, the calorie intake is BMR * 1.6, if the user is normal, the calorie intake is BMR * 1.4.
        :return: calorie intake, Float64.
        >>> fitnessTracker = FitnessTracker(1.8, 70.0, 20, "male")
        >>> fitnessTracker.calculate_calorie_intake()
        986.0

        */
        var bmr: Float64
        if this.sex == "male" {
            bmr = Float64(10) * this.weight + Float64(6.25) * this.height - Float64(5) * Float64(this.age) + Float64(5)
        } else if this.sex == "female" {
            bmr = Float64(10) * this.weight + Float64(6.25) * this.height - Float64(5) * Float64(this.age) - Float64(161)
        } else {
            bmr = Float64(10) * this.weight + Float64(6.25) * this.height - Float64(5) * Float64(this.age)
        }

        let condition: Int64 = this.condition_judge()
        if condition == Int64(1) {
            return bmr * Float64(1.2)
        } else if condition == Int64(-1) {
            return bmr * Float64(1.6)
        } else {
            return bmr * Float64(1.4)
        }
    }
}

import std.collection.ArrayList

class GomokuGame {

    /*
    This class is an implementation of a Gomoku game, supporting for making moves, checking for a winner, and checking if there are five consecutive symbols on the game board.
    */

    let board_size: Int64
    let board: ArrayList<ArrayList<String>>
    var current_player: String

    public init(board_size: Int64) {
        /*
        Initializes the game with a given board size.
        It initializes the board with empty spaces and sets the current player symbol as 'X'.
        */
        this.board_size = board_size
        this.board = ArrayList<ArrayList<String>>()
        this.current_player = "X"
        for (_ in 0..board_size) {
            let row: ArrayList<String> = ArrayList<String>()
            for (_ in 0..board_size) {
                row.add(" ")
            }
            board.add(row)
        }
    }

    public func make_move(row: Int64, col: Int64): Bool {
        /*
        Makes a move at the given row and column.
        If the move is valid, it places the current player's symbol on the board
        and changes the current player to the other player (if the current player is 'X', then it becomes 'O' and vice versa).
        :param row: Int64, the row index of this move
        :param col: Int64, the column index
        return: true if the move is valid, or false otherwise.
        >>> gomokuGame = GomokuGame(10)
        >>> gomokuGame.make_move(5, 5)
        true
        >>> gomokuGame.make_move(5, 5)
        false
        */
        if (row < 0 || row >= this.board_size || col < 0 || col >= this.board_size) {
            return false
        }
        let row_list = this.board.get(row)
        let current = row_list.get(col)
        if (current != " ") {
            return false
        }
        row_list.set(col, this.current_player)
        if (this.current_player == "X") {
            this.current_player = "O"
        } else {
            this.current_player = "X"
        }
        return true
    }

    public func check_winner(): Option<String> {
        /*
        Checks if there is a winner by looking for five in a row in all directions (horizontal, vertical, diagonal).
        return: the symbol of the winning player (either 'X' or 'O') if there is a winner, or None otherwise.
        >>> gomokuGame = GomokuGame(10)
        >>> moves = [(5, 5), (0, 0), (5, 4), (0, 1), (5, 3), (0, 2), (5, 2), (0, 3), (5, 1)]
        >>> for (move in moves) {
        ...     gomokuGame.make_move(move[0], move[1])
        ... }
        >>> gomokuGame.check_winner()
        'X'
        */
        for (r in 0..this.board_size) {
            for (c in 0..this.board_size) {
                let s = this.board.get(r).get(c)
                if (s == " ") {
                    continue
                }

                // Right
                if (this._is_start_of_line(r, c, (0, 1)) && this._check_five_in_a_row(r, c, (0, 1))) {
                    return Some(s)
                }
                // Down
                if (this._is_start_of_line(r, c, (1, 0)) && this._check_five_in_a_row(r, c, (1, 0))) {
                    return Some(s)
                }
                // Down-right
                if (this._is_start_of_line(r, c, (1, 1)) && this._check_five_in_a_row(r, c, (1, 1))) {
                    return Some(s)
                }
                // Down-left
                if (this._is_start_of_line(r, c, (1, -1)) && this._check_five_in_a_row(r, c, (1, -1))) {
                    return Some(s)
                }
            }
        }
        return None
    }

    private func _is_start_of_line(row: Int64, col: Int64, direction: (Int64, Int64)): Bool {
        let (dx, dy) = direction
        let pr = row - dx
        let pc = col - dy
        if (pr >= 0 && pr < this.board_size && pc >= 0 && pc < this.board_size) {
            let s = this.board.get(row).get(col)
            if (s != " ") {
                if (this.board.get(pr).get(pc) == s) {
                    return false
                }
            }
        }
        return true
    }

    public func _check_five_in_a_row(row: Int64, col: Int64, direction: (Int64, Int64)): Bool {
        /*
        checks if there are five consecutive symbols of the same player in a row starting from a given cell in a given direction (horizontal, vertical, diagonal).
        Counts the number of consecutive symbols in that direction starting from the given cell,
        :param row: Int64, row of the given cell
        :param col: Int64, column of the given cell
        :param direction: tuple, (Int64, Int64), named as (dx, dy). Row and col will plus several dx and dy repectively.
        :return: true if there are five consecutive symbols of the same player, and false otherwise.
        >>> gomokuGame = GomokuGame(10)
        >>> moves = [(5, 5), (0, 0), (5, 4), (0, 1), (5, 3), (0, 2), (5, 2), (0, 3), (5, 1)]
        >>> for (move in moves) {
        ...     gomokuGame.make_move(move[0], move[1])
        ... }
        >>> gomokuGame._check_five_in_a_row(5, 1, (0, 1))
        true
        >>> gomokuGame._check_five_in_a_row(5, 1, (1, 1))
        false
        */
        let s = this.board.get(row).get(col)
        if (s == " ") {
            return false
        }
        let (dx, dy) = direction
        var r = row
        var c = col
        var count: Int64 = 0
        while (r >= 0 && r < this.board_size && c >= 0 && c < this.board_size) {
            let v = this.board.get(r).get(c)
            if (v != s) {
                break
            }
            count = count + 1
            if (count >= 5) {
                return true
            }
            r = r + dx
            c = c + dy
        }
        return false
    }
}

import std.collection.HashMap

class Hotel {

    /*
    This is a class as hotel management system, managing the booking, check-in, check-out, and availability of rooms in a hotel with different room types.
    */

    let name: String
    let available_rooms: HashMap<String, Int64>
    var booked_rooms: HashMap<String, HashMap<String, Int64>>

    public init(name: String, rooms: HashMap<String, Int64>) {
        /*
        Initialize the three fields in Hotel System.
        name is the hotel name.
        available_rooms stores the remaining rooms in the hotel
        booked_rooms stores the rooms that have been booked and the person's name who booked rooms.
        >>> hotel.name
        'peace hotel'
        >>> hotel.available_rooms
        available_rooms = {'single': 5, 'double': 3}
        >>> hotel.booked_rooms
        {'single': {'guest 1': 2, 'guest 2':1}, 'double': {'guest1': 1}}
        */
        this.name = name
        this.available_rooms = HashMap<String, Int64>(rooms)
        this.booked_rooms = HashMap<String, HashMap<String, Int64>>()
    }

    public func book_room(room_type: String, room_number: Int64, name: String): String {
        /*
        Check if there are any rooms of the specified type available.
        if rooms are adequate, modify available_rooms and booked_rooms and finish booking, or fail to book otherwise.
        :param room_type: String
        :param room_number: Int64, the expected number of specified type rooms to be booked
        :param name: String, guest name
        :return: if number of rooms about to be booked doesn't exceed the remaining rooms, return str 'Success!'
                if exceeds but quantity of available rooms is not equal to zero, return Int64.toString() (the remaining quantity of this room type).
                if exceeds and quantity is zero or the room_type isn't in available_room, return 'false'.
        >>> hotel = Hotel('peace hotel', HashMap<String, Int64>([('single', 5), ('double', 3)]))
        >>> hotel.book_room('single', 1, 'guest 1')
        'Success!'
        >>> hotel.book_room('single', 5, 'guest 1')
        '4'
        >>> hotel.book_room('single', 4, 'guest 1')
        'Success!'
        >>> hotel.book_room('single', 1, 'guest 1')
        'false'
        >>> hotel.book_room('triple', 1, 'guest 1')
        'false'
        */
        if !this.available_rooms.containsKey(room_type) {
            return "false"
        }
        let qty = this.available_rooms.get(room_type)
        if qty == 0 {
            return "false"
        }
        if room_number <= qty {
            // update available rooms
            this.available_rooms.put(room_type, qty - room_number)

            // update booked rooms
            var room_bookings: HashMap<String, Int64>
            if this.booked_rooms.containsKey(room_type) {
                room_bookings = this.booked_rooms.get(room_type)
            } else {
                room_bookings = HashMap<String, Int64>()
                this.booked_rooms.put(room_type, room_bookings)
            }

            let current = room_bookings.containsKey(name) ? room_bookings.get(name) : 0
            room_bookings.put(name, current + room_number)

            return "Success!"
        } else {
            return qty.toString()
        }
    }

    public func check_in(room_type: String, room_number: Int64, name: String): Bool {
        /*
        Check if the room of the specified type and number is booked by the person named name.
        Remove this name when check in successfuly(room_number is equal to specific person's booked_rooms. When the actual check in quantity (room_number) is less than the booked quantity, number in booked_rooms will be booked quantity minus actual quantity
        :param room_type: String, check in room type
        :param room_number: Int64, check in room number
        :param name: String, person name
        :return false: only if the room_type is not in the booked_rooms or room_number is higher than quantity in booked rooms.
        >>> hotel = Hotel('peace hotel', HashMap<String, Int64>([('single', 5), ('double', 3)]))
        >>> hotel.book_room('single', 1, 'guest 1')
        true
        >>> hotel.check_in('single', 2, 'guest 1')
        false
        >>> hotel.check_in('single', 1, 'guest 1')
        true
        >>> hotel.booked_rooms
        {'single': {}}
        */
        if !this.booked_rooms.containsKey(room_type) {
            return false
        }
        let room_bookings = this.booked_rooms.get(room_type)
        if !room_bookings.containsKey(name) {
            return false
        }
        let booked_qty = room_bookings.get(name)
        if room_number > booked_qty {
            return false
        }

        let remaining = booked_qty - room_number
        if remaining == 0 {
            room_bookings.remove(name)
        } else {
            room_bookings.put(name, remaining)
        }

        // Keep the room_type key even if the inner map becomes empty, per example.
        return true
    }

    public func check_out(room_type: String, room_number: Int64): Unit {
        /*
        Check out rooms, add number for specific type in available_rooms.
        If room_type is new, add new type in available_rooms.
        :param room_type: String, check out room type
        :param room_number: Int64, check out room number
        >>> hotel = Hotel('peace hotel', HashMap<String, Int64>([('single', 5), ('double', 3)]))
        >>> hotel.check_out('single', 2)
        >>> hotel.available_rooms
        {'single': 7, 'double': 3}
        >>> hotel.check_out('triple', 2)
        >>> hotel.available_rooms
        {'single': 7, 'double': 3, 'triple': 2}
        */
        let current = this.available_rooms.containsKey(room_type) ? this.available_rooms.get(room_type) : 0
        this.available_rooms.put(room_type, current + room_number)
    }

    public func get_available_rooms(room_type: String): Int64 {
        /*
        Get the number of specific type of available rooms.
        :param room_type: String, the room type that want to know
        :return: Int64, the remaining number of this type rooms.
        >>> hotel = Hotel('peace hotel', HashMap<String, Int64>([('single', 5), ('double', 3)]))
        >>> hotel.get_available_rooms('single')
        5
        */
        return this.available_rooms.containsKey(room_type) ? this.available_rooms.get(room_type) : 0
    }
}

import std.collection.HashMap
