class JobMarketplace {

    /*
    This is a class that provides functionalities to publish positions, remove positions, submit resumes, withdraw resumes, search for positions, and obtain candidate information.
    */

    let jobListings: ArrayList<JobListing>
    let resumes: ArrayList<Resume>

    public init() {
        this.jobListings = ArrayList<JobListing>()
        this.resumes = ArrayList<Resume>()
    }

    public func post_job(job_title: String, company: String, requirements: ArrayList<String>): Unit {
        /*
        This function is used to publish positions,and add the position information to the job_listings list.
        :param job_title: The title of the position,String.
        :param company: The company of the position,String.
        :param requirements: The requirements of the position,ArrayList<String>.
        :return: Unit
        >>> jobMarketplace = JobMarketplace()
        >>> jobMarketplace.post_job("Software Engineer", "ABC Company", ArrayList<String>(['requirement1', 'requirement2']))
        >>> jobMarketplace.job_listings
        [JobListing("Software Engineer", "ABC Company", ArrayList<String>(['requirement1', 'requirement2']))]

        */
        let job = JobListing(job_title, company, requirements)
        this.jobListings.add(job)
    }

    public func remove_job(job: JobListing): Unit {
        /*
        This function is used to remove positions,and remove the position information from the job_listings list.
        :param job: The position information to be removed,JobListing.
        :return: Unit
        >>> jobMarketplace = JobMarketplace()
        >>> jobMarketplace.job_listings = [JobListing("Software Engineer", "ABC Company", ArrayList<String>(['requirement1', 'requirement2']))]
        >>> jobMarketplace.remove_job(jobMarketplace.job_listings[0])
        >>> jobMarketplace.job_listings
        []

        */
        var i: Int = 0
        while i < this.jobListings.size() {
            if this.jobListings.get(i) == job {
                this.jobListings.removeAt(i)
                break
            }
            i = i + 1
        }
    }

    public func submit_resume(name: String, skills: ArrayList<String>, experience: String): Unit {
        /*
        This function is used to submit resumes,and add the resume information to the resumes list.
        :param name: The name of the resume,String.
        :param skills: The skills of the resume,ArrayList<String>.
        :param experience: The experience of the resume,String.
        :return: Unit
        >>> jobMarketplace = JobMarketplace()
        >>> jobMarketplace.submit_resume("Tom", ArrayList<String>(['skill1', 'skill2']), "experience")
        >>> jobMarketplace.resumes
        [Resume("Tom", ArrayList<String>(['skill1', 'skill2']), "experience")]

        */
        let resume = Resume(name, skills, experience)
        this.resumes.add(resume)
    }

    public func withdraw_resume(resume: Resume): Unit {
        /*
        This function is used to withdraw resumes,and remove the resume information from the resumes list.
        :param resume: The resume information to be removed,Resume.
        :return: Unit
        >>> jobMarketplace = JobMarketplace()
        >>> jobMarketplace.resumes = [Resume("Tom", ArrayList<String>(['skill1', 'skill2']), "experience")]
        >>> jobMarketplace.withdraw_resume(jobMarketplace.resumes[0])
        >>> jobMarketplace.resumes
        []

        */
        var i: Int = 0
        while i < this.resumes.size() {
            if this.resumes.get(i) == resume {
                this.resumes.removeAt(i)
                break
            }
            i = i + 1
        }
    }

    public func search_jobs(criteria: String): ArrayList<JobListing> {
        /*
        This function is used to search for positions,and return the position information that meets the requirements.
        :param criteria: The requirements of the position,String.
        :return: The position information that meets the requirements,ArrayList<JobListing>.
        >>> jobMarketplace = JobMarketplace()
        >>> jobMarketplace.job_listings = [JobListing("Software Engineer", "ABC Company", ArrayList<String>(['skill1', 'skill2']))]
        >>> jobMarketplace.search_jobs("skill1")
        [JobListing("Software Engineer", "ABC Company", ArrayList<String>(['skill1', 'skill2']))]

        */
        let results = ArrayList<JobListing>()
        var i: Int = 0
        while i < this.jobListings.size() {
            let job = this.jobListings.get(i)
            if JobMarketplace.list_contains_string(job.requirements, criteria) {
                results.add(job)
            }
            i = i + 1
        }
        return results
    }

    public func get_job_applicants(job: JobListing): ArrayList<Resume> {
        /*
        This function is used to obtain candidate information,and return the candidate information that meets the requirements by calling the matches_requirements function.
        :param job: The position information,JobListing.
        :return: The candidate information that meets the requirements,ArrayList<Resume>.
        >>> jobMarketplace = JobMarketplace()
        >>> jobMarketplace.resumes = [Resume("Tom", ArrayList<String>(['skill1', 'skill2']), "experience")]
        >>> jobMarketplace.job_listings = [JobListing("Software Engineer", "ABC Company", ArrayList<String>(['skill1', 'skill2']))]
        >>> jobMarketplace.get_job_applicants(jobMarketplace.job_listings[0])
        [Resume("Tom", ArrayList<String>(['skill1', 'skill2']), "experience")]

        */
        let applicants = ArrayList<Resume>()
        var i: Int = 0
        while i < this.resumes.size() {
            let r = this.resumes.get(i)
            if JobMarketplace.matches_requirements(r, job.requirements) {
                applicants.add(r)
            }
            i = i + 1
        }
        return applicants
    }

    public static func matches_requirements(resume: Resume, requirements: ArrayList<String>): Bool {
        /*
        This function checks if a resume meets all the job requirements.
        It verifies whether the resume contains all the skills specified in the job requirements.

        :param resume: The resume to be evaluated, Resume object containing candidate's skills
        :param requirements: The list of required skills for the job, ArrayList<String>
        :return: Bool value indicating if the resume meets all requirements (true if all requirements are satisfied, false otherwise)
        */
        var i: Int = 0
        while i < requirements.size() {
            let req = requirements.get(i)
            if !JobMarketplace.list_contains_string(resume.skills, req) {
                return false
            }
            i = i + 1
        }
        return true
    }

    private static func list_contains_string(list: ArrayList<String>, value: String): Bool {
        var i: Int = 0
        while i < list.size() {
            if list.get(i) == value {
                return true
            }
            i = i + 1
        }
        return false
    }
}

import std.collection.ArrayList
import std.math.abs

class KappaCalculator {

    /*
    This is a class as KappaCalculator, supporting to calculate Cohen's and Fleiss' kappa coefficient.
    */

    public static func kappa(testData: ArrayList<ArrayList<Int64>>, k: Int64): Float64 {
        /*
        Calculate the cohens kappa value of a k-dimensional matrix
        :param testData: The k-dimensional matrix that needs to calculate the cohens kappa value
        :param k: Int64, Matrix dimension
        :return:float, the cohens kappa value of the matrix
        >>> KappaCalculator.kappa(ArrayList<ArrayList<Int64>>([ArrayList<Int64>([2, 1, 1]), ArrayList<Int64>([1, 2, 1]), ArrayList<Int64>([1, 1, 2])]), 3)
        0.25
        */
        if k <= 0 {
            return 0.0
        }
        if testData == null {
            return 0.0
        }
        if testData.size() != k {
            return 0.0
        }

        var rowSums: ArrayList<Int64> = ArrayList<Int64>()
        var colSums: ArrayList<Int64> = ArrayList<Int64>()
        var i: Int64 = 0
        while i < k {
            rowSums.add(0)
            colSums.add(0)
            i = i + 1
        }

        var total: Int64 = 0
        var diag: Int64 = 0

        i = 0
        while i < k {
            var row: ArrayList<Int64> = testData.get(i)
            if row == null || row.size() != k {
                return 0.0
            }
            var j: Int64 = 0
            while j < k {
                var v: Int64 = row.get(j)
                // accumulate totals
                total = total + v
                // row sums
                var rs: Int64 = rowSums.get(i)
                rowSums.set(i, rs + v)
                // column sums
                var cs: Int64 = colSums.get(j)
                colSums.set(j, cs + v)
                // diagonal
                if i == j {
                    diag = diag + v
                }
                j = j + 1
            }
            i = i + 1
        }

        if total == 0 {
            return 0.0
        }

        var po: Float64 = (1.0 * diag) / (1.0 * total)
        var pe: Float64 = 0.0
        i = 0
        while i < k {
            var r: Int64 = rowSums.get(i)
            var c: Int64 = colSums.get(i)
            pe = pe + ((1.0 * r) * (1.0 * c)) / ((1.0 * total) * (1.0 * total))
            i = i + 1
        }

        var den: Float64 = 1.0 - pe
        var eps: Float64 = 1e-12
        if abs(den) < eps {
            return 0.0
        }
        return (po - pe) / den
    }

    public static func fleiss_kappa(testData: ArrayList<ArrayList<Int64>>, N: Int64, k: Int64, n: Int64): Float64 {
        /*
        Calculate the fliss kappa value of an N * k matrix
        :param testData: Input data matrix, N * k
        :param N: Int64, Number of samples
        :param k: Int64, Number of categories
        :param n: Int64, Number of raters
        :return: Float64, fleiss kappa value
        >>> KappaCalculator.fleiss_kappa(ArrayList<ArrayList<Int64>>([ArrayList<Int64>([0, 0, 0, 0, 14]),
        >>>                              ArrayList<Int64>([0, 2, 6, 4, 2]),
        >>>                              ArrayList<Int64>([0, 0, 3, 5, 6]),
        >>>                              ArrayList<Int64>([0, 3, 9, 2, 0]),
        >>>                              ArrayList<Int64>([2, 2, 8, 1, 1]),
        >>>                              ArrayList<Int64>([7, 7, 0, 0, 0]),
        >>>                              ArrayList<Int64>([3, 2, 6, 3, 0]),
        >>>                              ArrayList<Int64>([2, 5, 3, 2, 2]),
        >>>                              ArrayList<Int64>([6, 5, 2, 1, 0]),
        >>>                              ArrayList<Int64>([0, 2, 2, 3, 7])], 10, 5, 14)
        0.20993070442195522
        */
        if testData == null {
            return 0.0
        }
        if N <= 0 || k <= 0 || n <= 1 {
            return 0.0
        }
        if testData.size() != N {
            return 0.0
        }

        var colCounts: ArrayList<Int64> = ArrayList<Int64>()
        var j: Int64 = 0
        while j < k {
            colCounts.add(0)
            j = j + 1
        }

        var sumPi: Float64 = 0.0
        var i: Int64 = 0
        while i < N {
            var row: ArrayList<Int64> = testData.get(i)
            if row == null || row.size() != k {
                return 0.0
            }

            var rowSum: Int64 = 0
            var agreeTerm: Int64 = 0

            j = 0
            while j < k {
                var v: Int64 = row.get(j)
                rowSum = rowSum + v
                agreeTerm = agreeTerm + (v * (v - 1))
                var cc: Int64 = colCounts.get(j)
                colCounts.set(j, cc + v)
                j = j + 1
            }

            if rowSum != n {
                return 0.0
            }

            var Pi: Float64 = (1.0 * agreeTerm) / ((1.0 * n) * (1.0 * (n - 1)))
            sumPi = sumPi + Pi

            i = i + 1
        }

        var Pbar: Float64 = sumPi / (1.0 * N)

        var Pe_bar: Float64 = 0.0
        j = 0
        while j < k {
            var pj: Float64 = (1.0 * colCounts.get(j)) / ((1.0 * N) * (1.0 * n))
            Pe_bar = Pe_bar + (pj * pj)
            j = j + 1
        }

        var den: Float64 = 1.0 - Pe_bar
        var eps: Float64 = 1e-12
        if abs(den) < eps {
            return 0.0
        }

        return (Pbar - Pe_bar) / den
    }
}

import std.collection.ArrayList
import std.regex.Regex

class LongestWord {

    /*
    This is a class allows to add words to a list and find the longest word in a given sentence by comparing the words with the ones in the word list.
    */

    let word_list: ArrayList<String>

    public init() {
        /*
        Initialize a list of word.
        */
        this.word_list = ArrayList<String>()
    }

    public func add_word(word: String): Unit {
        /*
        append the input word into this.word_list
        :param word: String, input word
        */
        this.word_list.add(word)
    }

    public func find_longest_word(sentence: String): String {
        /*
        Remove punctuation marks and split a sentence into a list of word. Find the longest splited word that is in the this.word_list.
        Words are strictly case sensitive.
        :param sentence: a sentence String
        :return String: longest splited word that is in the this.word_list. return '' if this.word_list is empty.
        >>> longestWord = LongestWord()
        >>> longestWord.add_word('A')
        >>> longestWord.add_word('aM')
        >>> longestWord.find_longest_word('I am a student.')
        'a'
        */
        if this.word_list.isEmpty() {
            return ""
        }

        // Replace all non-alphanumeric characters with a single space
        let re = Regex("[^A-Za-z0-9]+")
        let cleaned = re.replaceAll(sentence, " ").trim()
        if cleaned.length() == 0 {
            return ""
        }

        let parts = cleaned.split(" ")
        var best: String = ""
        var bestLen: Int = 0

        // Iterate through split words and find the longest that exists in the word_list (case-sensitive)
        for part in parts {
            if part.length() == 0 {
                continue
            }
            // Check membership in word_list
            var found: Bool = false
            var i: Int = 0
            let n: Int = this.word_list.size()
            while i < n {
                if this.word_list.get(i) == part {
                    found = true
                    break
                }
                i = i + 1
            }

            if found {
                let l = part.length()
                if l > bestLen {
                    bestLen = l
                    best = part
                }
            }
        }

        return best
    }
}

import std.collection.ArrayList
import std.collection.HashSet
import std.random.Random

class MahjongConnect {

    /*
    MahjongConnect is a class representing a game board for Mahjong Connect with features like creating the board, checking valid moves, finding paths, removing icons, and checking if the game is over.
    */

    let BOARD_SIZE: ArrayList<Int64>
    let ICONS: ArrayList<String>
    var board: ArrayList<ArrayList<String>>

    public init(BOARD_SIZE: ArrayList<Int64>, ICONS: ArrayList<String>) {
        /*
        initialize the board size and the icon list, create the game board
        :param BOARD_SIZE: list of two integer numbers, representing the number of rows and columns of the game board
        :param ICONS: list of String, representing the icons
        >>>mc = MahjongConnect(ArrayList<Int64>([4, 4]), ArrayList<String>(['a', 'b', 'c']))
        mc.BOARD_SIZE = [4, 4]
        mc.ICONS = ['a', 'b', 'c']
        mc.board = mc.create_board()
        */
        this.BOARD_SIZE = BOARD_SIZE
        this.ICONS = ICONS
        this.board = MahjongConnect.create_board(BOARD_SIZE, ICONS)
    }

    public static func create_board(BOARD_SIZE: ArrayList<Int64>, ICONS: ArrayList<String>): ArrayList<ArrayList<String>> {
        /*
        create the game board with the given board size and icons
        :return: 2-dimensional list, the game board
        >>> mc = MahjongConnect(ArrayList<Int64>([4, 4]), ArrayList<String>(['a', 'b', 'c']))
        >>> mc.create_board()
        mc.board = [['a', 'b', 'c', 'a'],
                    ['a', 'b', 'c', 'a'],
                    ['a', 'b', 'c', 'a'],
                    ['a', 'b', 'c', 'a']]
        */
        let rows: Int64 = BOARD_SIZE[0]
        let cols: Int64 = BOARD_SIZE[1]
        let iconsCount: Int64 = ICONS.size()

        var result: ArrayList<ArrayList<String>> = ArrayList<ArrayList<String>>()

        var i: Int64 = 0
        while (i < rows) {
            var rowList: ArrayList<String> = ArrayList<String>()
            var j: Int64 = 0
            while (j < cols) {
                let idx: Int64 = ((i * cols) + j) % iconsCount
                let icon: String = ICONS[idx]
                rowList.add(icon)
                j = j + 1
            }
            result.add(rowList)
            i = i + 1
        }
        return result
    }

    private func in_bounds(r: Int64, c: Int64): Bool {
        let rows: Int64 = this.BOARD_SIZE[0]
        let cols: Int64 = this.BOARD_SIZE[1]
        return r >= 0 && r < rows && c >= 0 && c < cols
    }

    private func is_empty(r: Int64, c: Int64): Bool {
        return this.board[r][c] == " "
    }

    private func cell_is_passable(r: Int64, c: Int64, pos1: (Int64, Int64), pos2: (Int64, Int64)): Bool {
        let (x1, y1) = pos1
        let (x2, y2) = pos2
        if (r == x1 && c == y1) {
            return true
        }
        if (r == x2 && c == y2) {
            return true
        }
        return this.is_empty(r, c)
    }

    private func line_clear_row(row: Int64, c1: Int64, c2: Int64, pos1: (Int64, Int64), pos2: (Int64, Int64)): Bool {
        var start: Int64 = c1
        var end: Int64 = c2
        if (start > end) {
            let tmp: Int64 = start
            start = end
            end = tmp
        }
        var c: Int64 = start + 1
        while (c < end) {
            if (!this.cell_is_passable(row, c, pos1, pos2)) {
                return false
            }
            c = c + 1
        }
        return true
    }

    private func line_clear_col(col: Int64, r1: Int64, r2: Int64, pos1: (Int64, Int64), pos2: (Int64, Int64)): Bool {
        var start: Int64 = r1
        var end: Int64 = r2
        if (start > end) {
            let tmp: Int64 = start
            start = end
            end = tmp
        }
        var r: Int64 = start + 1
        while (r < end) {
            if (!this.cell_is_passable(r, col, pos1, pos2)) {
                return false
            }
            r = r + 1
        }
        return true
    }

    private func has_direct_path(pos1: (Int64, Int64), pos2: (Int64, Int64)): Bool {
        let (x1, y1) = pos1
        let (x2, y2) = pos2
        if (x1 == x2) {
            // Same row
            if (this.line_clear_row(x1, y1, y2, pos1, pos2)) {
                return true
            }
        }
        if (y1 == y2) {
            // Same column
            if (this.line_clear_col(y1, x1, x2, pos1, pos2)) {
                return true
            }
        }
        return false
    }

    private func has_one_turn_path(pos1: (Int64, Int64), pos2: (Int64, Int64)): Bool {
        let (x1, y1) = pos1
        let (x2, y2) = pos2

        // Corner 1: (x1, y2)
        if (this.in_bounds(x1, y2)) {
            if (this.cell_is_passable(x1, y2, pos1, pos2)) {
                if (this.line_clear_row(x1, y1, y2, pos1, pos2) && this.line_clear_col(y2, x1, x2, pos1, pos2)) {
                    return true
                }
            }
        }

        // Corner 2: (x2, y1)
        if (this.in_bounds(x2, y1)) {
            if (this.cell_is_passable(x2, y1, pos1, pos2)) {
                if (this.line_clear_col(y1, x1, x2, pos1, pos2) && this.line_clear_row(x2, y1, y2, pos1, pos2)) {
                    return true
                }
            }
        }

        return false
    }

    private func has_two_turn_path_internal_scan_rows(pos1: (Int64, Int64), pos2: (Int64, Int64)): Bool {
        let (x1, y1) = pos1
        let (x2, y2) = pos2
        let rows: Int64 = this.BOARD_SIZE[0]
        var r: Int64 = 0
        while (r < rows) {
            // Check intermediate cells (r, y1) and (r, y2)
            if (this.cell_is_passable(r, y1, pos1, pos2) && this.cell_is_passable(r, y2, pos1, pos2)) {
                // pos1 -> (r, y1) vertical clear
                if (this.line_clear_col(y1, x1, r, pos1, pos2)) {
                    // pos2 -> (r, y2) vertical clear
                    if (this.line_clear_col(y2, x2, r, pos1, pos2)) {
                        // Between (r, y1) and (r, y2) horizontal clear
                        if (this.line_clear_row(r, y1, y2, pos1, pos2)) {
                            return true
                        }
                    }
                }
            }
            r = r + 1
        }
        return false
    }

    private func has_two_turn_path_internal_scan_cols(pos1: (Int64, Int64), pos2: (Int64, Int64)): Bool {
        let (x1, y1) = pos1
        let (x2, y2) = pos2
        let cols: Int64 = this.BOARD_SIZE[1]
        var c: Int64 = 0
        while (c < cols) {
            // Check intermediate cells (x1, c) and (x2, c)
            if (this.cell_is_passable(x1, c, pos1, pos2) && this.cell_is_passable(x2, c, pos1, pos2)) {
                // pos1 -> (x1, c) horizontal clear
                if (this.line_clear_row(x1, y1, c, pos1, pos2)) {
                    // pos2 -> (x2, c) horizontal clear
                    if (this.line_clear_row(x2, y2, c, pos1, pos2)) {
                        // Between (x1, c) and (x2, c) vertical clear
                        if (this.line_clear_col(c, x1, x2, pos1, pos2)) {
                            return true
                        }
                    }
                }
            }
            c = c + 1
        }
        return false
    }

    public func has_path(pos1: (Int64, Int64), pos2: (Int64, Int64)): Bool {
        /*
        check if there is a path between two icons
        :param pos1: position Tuple(x, y) of the first icon
        :param pos2: position Tuple(x, y) of the second icon
        :return: true or false ,representing whether there is a path between two icons
        >>> mc = MahjongConnect(ArrayList<Int64>([4, 4]), ArrayList<String>(['a', 'b', 'c']))
        mc.board = [['a', 'b', 'c', 'a'],
                    ['a', 'b', 'c', 'a'],
                    ['a', 'b', 'c', 'a'],
                    ['a', 'b', 'c', 'a']]
        >>> mc.has_path((0, 0), (1, 0))
        true
        */
        let (x1, y1) = pos1
        let (x2, y2) = pos2

        if (!this.in_bounds(x1, y1) || !this.in_bounds(x2, y2)) {
            return false
        }

        // Direct path (no turns)
        if (this.has_direct_path(pos1, pos2)) {
            return true
        }

        // One-turn (L-shaped) path
        if (this.has_one_turn_path(pos1, pos2)) {
            return true
        }

        // Two-turn path (Z-shaped), scanning rows and columns
        if (this.has_two_turn_path_internal_scan_rows(pos1, pos2)) {
            return true
        }

        if (this.has_two_turn_path_internal_scan_cols(pos1, pos2)) {
            return true
        }

        return false
    }

    public func is_valid_move(pos1: (Int64, Int64), pos2: (Int64, Int64)): Bool {
        /*
        check if the move of two icons is valid (i.e. positions are within the game board range, the two positions are not the same, the two positions have the same icon, and there is a valid path between the two positions)
        :param pos1: position Tuple(x, y) of the first icon
        :param pos2: position Tuple(x, y) of the second icon
        :return:true or false ,representing whether the move of two icons is valid
        >>> mc = MahjongConnect(ArrayList<Int64>([4, 4]), ArrayList<String>(['a', 'b', 'c']))
        mc.board = [['a', 'b', 'c', 'a'],
                    ['a', 'b', 'c', 'a'],
                    ['a', 'b', 'c', 'a'],
                    ['a', 'b', 'c', 'a']]
        >>> mc.is_valid_move((0, 0), (1, 0))
        true
        */
        let (x1, y1) = pos1
        let (x2, y2) = pos2

        if (!this.in_bounds(x1, y1) || !this.in_bounds(x2, y2)) {
            return false
        }
        if (x1 == x2 && y1 == y2) {
            return false
        }
        let icon1: String = this.board[x1][y1]
        let icon2: String = this.board[x2][y2]
        if (icon1 == " " || icon2 == " ") {
            return false
        }
        if (icon1 != icon2) {
            return false
        }
        return this.has_path(pos1, pos2)
    }

    public static func contains(visited: ArrayList<(Int64, Int64)>, pos: (Int64, Int64)): Bool {
        /*
        check if the position is in the visited list
        :param visited: list of position tuples, representing the visited positions
        :param pos: position tuple, representing the position to be checked
        :return: true or false, representing whether the position is in the visited list
        */
        for (v in visited) {
            if (v == pos) {
                return true
            }
        }
        return false
    }

    public func remove_icons(pos1: (Int64, Int64), pos2: (Int64, Int64)): Unit {
        /*
        remove the connected icons on the game board
        :param pos1: position tuple(x, y) of the first icon to be removed
        :param pos2: position tuple(x, y) of the second icon to be removed
        :return: Unit
        >>> mc = MahjongConnect(ArrayList<Int64>([4, 4]), ArrayList<String>(['a', 'b', 'c']))
        mc.board = [['a', 'b', 'c', 'a'],
                    ['a', 'b', 'c', 'a'],
                    ['a', 'b', 'c', 'a'],
                    ['a', 'b', 'c', 'a']]
        >>> mc.remove_icons((0, 0), (1, 0))
        mc.board = [[' ', 'b', 'c', 'a'],
                    [' ', 'b', 'c', 'a'],
                    ['a', 'b', 'c', 'a'],
                    ['a', 'b', 'c', 'a']]
        */
        if (!this.is_valid_move(pos1, pos2)) {
            return
        }
        let (x1, y1) = pos1
        let (x2, y2) = pos2
        this.board[x1][y1] = " "
        this.board[x2][y2] = " "
    }

    public func is_game_over(): Bool {
        /*
        Check if the game is over (i.e., if there are no more icons on the game board)
        :return: true or false ,representing whether the game is over
        >>> mc = MahjongConnect(ArrayList<Int64>([4, 4]), ArrayList<String>(['a', 'b', 'c']))
        >>> mc.board = [[' ', ' ', ' ', ' '],
        >>>         [' ', ' ', ' ', ' '],
        >>>         [' ', ' ', ' ', ' '],
        >>>         [' ', ' ', ' ', ' ']]
        >>> mc.is_game_over()
        true
        */
        let rows: Int64 = this.BOARD_SIZE[0]
        let cols: Int64 = this.BOARD_SIZE[1]
        var i: Int64 = 0
        while (i < rows) {
            var j: Int64 = 0
            while (j < cols) {
                if (this.board[i][j] != " ") {
                    return false
                }
                j = j + 1
            }
            i = i + 1
        }
        return true
    }
}

class Manacher {

    /*
    This is a class that implements the Manacher algorithm to find the longest palindromic substring in a given string.
    */

    let input_string: String

    public init(input_string: String) {
        /*
        Initializes the Manacher class with the given input_string.
        :param input_string: The input_string to be searched, String.
        */
        this.input_string = input_string
    }

    public func palindromic_length(center: Int64, diff: Int64, string: String): Int64 {
        /*
        Calculates the length (radius in transformed string) of the palindromic substring based on a given center,
        difference value, and input string by expanding around the center.
        :param center: The center of the palindromic substring, Int64.
        :param diff: The starting difference between the center and the initial position to compare, Int64 (typically 1).
        :param string: The transformed string (with separators) to be searched, String.
        :return: The expansion count (radius) of the palindromic substring, Int64.
        >>> manacher = Manacher('ababa')
        >>> manacher.palindromic_length(2, 1, 'a|b|a|b|a')
        2
        */
        var offset: Int64 = diff
        var count: Int64 = 0
        let n: Int64 = string.length()

        while (center - offset >= 0 && center + offset < n && string.substr(center - offset, 1) == string.substr(center + offset, 1)) {
            count = count + 1
            offset = offset + 1
        }

        return count
    }

    public func palindromic_string(): String {
        /*
        Finds the longest palindromic substring in the given string.
        :return: The longest palindromic substring, String.
        >>> manacher = Manacher('ababaxse')
        >>> manacher.palindromic_string()
        'ababa'
        */
        let n: Int64 = this.input_string.length()
        if (n == 0) {
            return ""
        }

        // Build transformed string with separators ('|') between characters
        var t: String = ""
        var i: Int64 = 0
        while (i < n) {
            t = t + this.input_string.substr(i, 1)
            if (i < n - 1) {
                t = t + "|"
            }
            i = i + 1
        }

        // Scan each center and expand to find the longest palindrome
        let m: Int64 = t.length()
        var best_start: Int64 = 0
        var best_end: Int64 = 0

        var center: Int64 = 0
        while (center < m) {
            let exp: Int64 = this.palindromic_length(center, 1, t)
            let start: Int64 = center - exp
            let end: Int64 = center + exp

            if ((end - start) > (best_end - best_start)) {
                best_start = start
                best_end = end
            }

            center = center + 1
        }

        // Build the result by removing separators from the best span in the transformed string
        var res: String = ""
        var idx: Int64 = best_start
        while (idx <= best_end) {
            let ch: String = t.substr(idx, 1)
            if (ch != "|") {
                res = res + ch
            }
            idx = idx + 1
        }

        return res
    }
}

import std.collection.ArrayList
import std.math.abs

class MetricsCalculator {

    /*
    The class calculates precision, recall, F1 score, and accuracy based on predicted and true labels.
    */

    var true_positives: Int64
    var false_positives: Int64
    var false_negatives: Int64
    var true_negatives: Int64

    public init() {
        /*
        Initialize the number of all four samples to 0
        */
        this.true_positives = 0
        this.false_positives = 0
        this.false_negatives = 0
        this.true_negatives = 0
    }

    public func update(predicted_labels: ArrayList<Int64>, true_labels: ArrayList<Int64>): Unit {
        /*
        Update the number of all four samples(true_positives, false_positives, false_negatives, true_negatives)
        :param predicted_labels: ArrayList<Int64>, predicted results
        :param true_labels: ArrayList<Int64>, true labels
        :return: None, change the number of corresponding samples
        >>> mc = MetricsCalculator()
        >>> mc.update(ArrayList<Int64>([1, 1, 0, 0]), ArrayList<Int64>([1, 0, 0, 1]))
        (this.true_positives, this.false_positives, this.false_negatives, this.true_negatives) = (1, 1, 1, 1)
        */
        // reset counts
        this.true_positives = 0
        this.false_positives = 0
        this.false_negatives = 0
        this.true_negatives = 0

        var n: Int64 = predicted_labels.size()
        if (true_labels.size() < n) {
            n = true_labels.size()
        }

        var i: Int64 = 0
        while (i < n) {
            var p: Int64 = predicted_labels.get(i)
            var t: Int64 = true_labels.get(i)

            if (p == 1 && t == 1) {
                this.true_positives += 1
            } else if (p == 1 && t == 0) {
                this.false_positives += 1
            } else if (p == 0 && t == 1) {
                this.false_negatives += 1
            } else if (p == 0 && t == 0) {
                this.true_negatives += 1
            }
            i += 1
        }
    }

    public func precision(predicted_labels: ArrayList<Int64>, true_labels: ArrayList<Int64>): Float64 {
        /*
        Calculate precision
        :param predicted_labels: ArrayList<Int64>, predicted results
        :param true_labels: ArrayList<Int64>, true labels
        :return: Float64
        >>> mc = MetricsCalculator()
        >>> mc.precision(ArrayList<Int64>([1, 1, 0, 0]), ArrayList<Int64>([1, 0, 0, 1]))
        0.5
        */
        this.update(predicted_labels, true_labels)
        var tp_fp: Int64 = this.true_positives + this.false_positives
        if (tp_fp == 0) {
            return 0.0
        }
        return Float64(this.true_positives) / Float64(tp_fp)
    }

    public func recall(predicted_labels: ArrayList<Int64>, true_labels: ArrayList<Int64>): Float64 {
        /*
        Calculate recall
        :param predicted_labels: ArrayList<Int64>, predicted results
        :param true_labels: ArrayList<Int64>, true labels
        :return: Float64
        >>> mc = MetricsCalculator()
        >>> mc.recall(ArrayList<Int64>([1, 1, 0, 0]), ArrayList<Int64>([1, 0, 0, 1]))
        0.5
        */
        this.update(predicted_labels, true_labels)
        var tp_fn: Int64 = this.true_positives + this.false_negatives
        if (tp_fn == 0) {
            return 0.0
        }
        return Float64(this.true_positives) / Float64(tp_fn)
    }

    public func f1_score(predicted_labels: ArrayList<Int64>, true_labels: ArrayList<Int64>): Float64 {
        /*
        Calculate f1 score, which is the harmonic mean of precision and recall
        :param predicted_labels: ArrayList<Int64>, predicted results
        :param true_labels: ArrayList<Int64>, true labels
        :return: Float64
        >>> mc = MetricsCalculator()
        >>> mc.f1_score(ArrayList<Int64>([1, 1, 0, 0]), ArrayList<Int64>([1, 0, 0, 1]))
        0.5
        */
        this.update(predicted_labels, true_labels)
        var tp: Float64 = Float64(this.true_positives)
        var fp: Float64 = Float64(this.false_positives)
        var fn: Float64 = Float64(this.false_negatives)

        var precision_val: Float64 = 0.0
        var recall_val: Float64 = 0.0

        var denom_p: Float64 = tp + fp
        if (denom_p > 0.0) {
            precision_val = tp / denom_p
        }

        var denom_r: Float64 = tp + fn
        if (denom_r > 0.0) {
            recall_val = tp / denom_r
        }

        var sum_pr: Float64 = precision_val + recall_val
        if (sum_pr == 0.0) {
            return 0.0
        }

        return 2.0 * precision_val * recall_val / sum_pr
    }

    public func accuracy(predicted_labels: ArrayList<Int64>, true_labels: ArrayList<Int64>): Float64 {
        /*
        Calculate accuracy
        :param predicted_labels: ArrayList<Int64>, predicted results
        :param true_labels: ArrayList<Int64>, true labels
        :return: Float64
        >>> mc = MetricsCalculator()
        >>> mc.accuracy(ArrayList<Int64>([1, 1, 0, 0]), ArrayList<Int64>([1, 0, 0, 1]))
        0.5
        */
        this.update(predicted_labels, true_labels)
        var total: Int64 = this.true_positives + this.false_positives + this.false_negatives + this.true_negatives
        if (total == 0) {
            return 0.0
        }
        var correct: Int64 = this.true_positives + this.true_negatives
        return Float64(correct) / Float64(total)
    }
}

import std.collection.ArrayList
import std.math.abs

class MetricsCalculator2 {

    /*
    The class provides to calculate Mean Reciprocal Rank (MRR) and Mean Average Precision (MAP) based on input data, where MRR measures the ranking quality and MAP measures the average precision.
    */

    public init() {}

    private static func computeRR(list: ArrayList<Int64>): Float64 {
        let n: Int64 = list.size()
        var i: Int64 = 0
        while i < n {
            let v: Int64 = list.get(i)
            if v == 1 {
                return 1.0 / Float64(i + 1)
            }
            i += 1
        }
        return 0.0
    }

    private static func computeAP(list: ArrayList<Int64>, gt: Int64): Float64 {
        let n: Int64 = list.size()
        if gt <= 0 {
            return 0.0
        }
        var i: Int64 = 0
        var hits: Int64 = 0
        var sumPrecisions: Float64 = 0.0
        while i < n {
            let v: Int64 = list.get(i)
            if v == 1 {
                hits += 1
                let prec: Float64 = Float64(hits) / Float64(i + 1)
                sumPrecisions += prec
            }
            i += 1
        }
        return sumPrecisions / Float64(gt)
    }

    public static func mrr(data: Any): (Float64, ArrayList<Float64>) {
        /*
        compute the MRR of the input data. MRR is a widely used evaluation index. It is the mean of reciprocal rank.
        :param data: the data must be a tuple, list 0,1,eg.([1,0,...],5).  In each tuple (actual result,ground truth num),ground truth num is the total ground num.
         ([1,0,...],5),
        or list of tuple eg. [([1,0,1,...],5),([1,0,...],6),([0,0,...],5)].
        1 stands for a correct answer, 0 stands for a wrong answer.
        :return: if input data is list, return the recall of this list. if the input data is list of list, return the
        average recall on all list. The second return value is a list of precision for each input.
        >>> MetricsCalculator2.mrr((ArrayList<Int64>([1, 0, 1, 0]), 4))
        >>> MetricsCalculator2.mrr([(ArrayList<Int64>([1, 0, 1, 0]), 4), (ArrayList<Int64>([0, 1, 0, 1]), 4)])
        1.0, [1.0]
        0.75, [1.0, 0.5]
        */
        var perQuery: ArrayList<Float64> = ArrayList<Float64>()
        var total: Float64 = 0.0

        if data is (ArrayList<Int64>, Int64) {
            let t: (ArrayList<Int64>, Int64) = data as (ArrayList<Int64>, Int64)
            let rr: Float64 = MetricsCalculator2.computeRR(t.0)
            perQuery.add(rr)
            total += rr
        } else if data is ArrayList<(ArrayList<Int64>, Int64)> {
            let arr: ArrayList<(ArrayList<Int64>, Int64)> = data as ArrayList<(ArrayList<Int64>, Int64)>
            let m: Int64 = arr.size()
            var idx: Int64 = 0
            while idx < m {
                let t: (ArrayList<Int64>, Int64) = arr.get(idx)
                let rr: Float64 = MetricsCalculator2.computeRR(t.0)
                perQuery.add(rr)
                total += rr
                idx += 1
            }
        } else {
            // Unsupported type; return zeros
        }

        let count: Int64 = perQuery.size()
        let mean: Float64 = count > 0 ? (total / Float64(count)) : 0.0
        return (mean, perQuery)
    }

    public static func map(data: Any): (Float64, ArrayList<Float64>) {
        /*
        compute the MAP of the input data. MAP is a widely used evaluation index. It is the mean of AP (average precision).
        :param data: the data must be a tuple, list 0,1,eg.([1,0,...],5).  In each tuple (actual result,ground truth num),ground truth num is the total ground num.
         ([1,0,...],5),
        or list of tuple eg. [([1,0,1,...],5),([1,0,...],6),([0,0,...],5)].
        1 stands for a correct answer, 0 stands for a wrong answer.
        :return: if input data is list, return the recall of this list. if the input data is list of list, return the
        average recall on all list. The second return value is a list of precision for each input.
        >>> MetricsCalculator2.map((ArrayList<Int64>([1, 0, 1, 0]), 4))
        >>> MetricsCalculator2.map([(ArrayList<Int64>([1, 0, 1, 0]), 4), (ArrayList<Int64>([0, 1, 0, 1]), 4)])
        0.41666666666666663, [0.41666666666666663]
        0.3333333333333333, [0.41666666666666663, 0.25]
        */
        var perQuery: ArrayList<Float64> = ArrayList<Float64>()
        var total: Float64 = 0.0

        if data is (ArrayList<Int64>, Int64) {
            let t: (ArrayList<Int64>, Int64) = data as (ArrayList<Int64>, Int64)
            let ap: Float64 = MetricsCalculator2.computeAP(t.0, t.1)
            perQuery.add(ap)
            total += ap
        } else if data is ArrayList<(ArrayList<Int64>, Int64)> {
            let arr: ArrayList<(ArrayList<Int64>, Int64)> = data as ArrayList<(ArrayList<Int64>, Int64)>
            let m: Int64 = arr.size()
            var idx: Int64 = 0
            while idx < m {
                let t: (ArrayList<Int64>, Int64) = arr.get(idx)
                let ap: Float64 = MetricsCalculator2.computeAP(t.0, t.1)
                perQuery.add(ap)
                total += ap
                idx += 1
            }
        } else {
            // Unsupported type; return zeros
        }

        let count: Int64 = perQuery.size()
        let mean: Float64 = count > 0 ? (total / Float64(count)) : 0.0
        return (mean, perQuery)
    }
}

import std.collection.ArrayList
import std.random.Random
import std.convert.Parsable

class MinesweeperGame {

    /*
    This is a class that implements mine sweeping games including minesweeping and winning judgment.
    */

    let n: Int64
    let k: Int64
    var minesweeper_map: ArrayList<ArrayList<String>>
    var player_map: ArrayList<ArrayList<String>>
    var score: Int64

    public init(n: Int64, k: Int64) {
        /*
        Initializes the MinesweeperGame class with the size of the board and the number of mines.
        :param n: The size of the board, Int64.
        :param k: The number of mines, Int64.
        */
        this.n = n
        this.k = k
        this.minesweeper_map = MinesweeperGame.generate_mine_sweeper_map(n, k)
        this.player_map = MinesweeperGame.generate_playerMap(n)
        this.score = 0
    }

    public static func generate_mine_sweeper_map(n: Int64, k: Int64): ArrayList<ArrayList<String>> {
        /*
        Generates a minesweeper map with the given size of the board and the number of mines,the given parameter n is the size of the board,the size of the board is n*n,the parameter k is the number of mines,'X' represents the mine,other numbers represent the number of mines around the position.
        :return: The minesweeper map, ArrayList<ArrayList<String>>.
        >>> MinesweeperGame.generate_mine_sweeper_map(3, 1)
        [['X', '1', '0'], ['1', '1', '0'], ['0', '0', '0']]
        */
        var map: ArrayList<ArrayList<String>> = ArrayList<ArrayList<String>>()
        var i: Int64 = 0
        while i < n {
            var row: ArrayList<String> = ArrayList<String>()
            var j: Int64 = 0
            while j < n {
                row.append("0")
                j = j + 1
            }
            map.append(row)
            i = i + 1
        }

        // Place k mines deterministically in row-major order to ensure reproducibility.
        var m: Int64 = 0
        while m < k {
            let x: Int64 = m / n
            let y: Int64 = m % n
            let row = map.get(x)
            row.set(y, "X")
            m = m + 1
        }

        // Compute neighbor counts
        i = 0
        while i < n {
            var j: Int64 = 0
            while j < n {
                let row = map.get(i)
                let cell = row.get(j)
                if cell != "X" {
                    var cnt: Int64 = 0
                    var dx: Int64 = -1
                    while dx <= 1 {
                        var dy: Int64 = -1
                        while dy <= 1 {
                            if !(dx == 0 && dy == 0) {
                                let nx: Int64 = i + dx
                                let ny: Int64 = j + dy
                                if nx >= 0 && nx < n && ny >= 0 && ny < n {
                                    let nrow = map.get(nx)
                                    if nrow.get(ny) == "X" {
                                        cnt = cnt + 1
                                    }
                                }
                            }
                            dy = dy + 1
                        }
                        dx = dx + 1
                    }
                    row.set(j, MinesweeperGame.toDigitString(cnt))
                }
                j = j + 1
            }
            i = i + 1
        }

        return map
    }

    public static func generate_playerMap(n: Int64): ArrayList<ArrayList<String>> {
        /*
        Generates a player map with the given size of the board, the given parameter n is the size of the board,the size of the board is n*n,the parameter k is the number of mines,'-' represents the unknown position.
        :return: The player map, ArrayList<ArrayList<String>>.
        >>> MinesweeperGame.generate_playerMap(3)
        [['-', '-', '-'], ['-', '-', '-'], ['-', '-', '-']]
        */
        var map: ArrayList<ArrayList<String>> = ArrayList<ArrayList<String>>()
        var i: Int64 = 0
        while i < n {
            var row: ArrayList<String> = ArrayList<String>()
            var j: Int64 = 0
            while j < n {
                row.append("-")
                j = j + 1
            }
            map.append(row)
            i = i + 1
        }
        return map
    }

    public func check_won(map: ArrayList<ArrayList<String>>): Bool {
        /*
        Checks whether the player has won the game,if there are just mines in the player map,return true,otherwise return false.
        :return: true if the player has won the game, false otherwise.
        >>> minesweeper_game = MinesweeperGame(3, 1)
        >>> minesweeper_game.minesweeper_map = ArrayList<ArrayList<String>>([ArrayList<String>(['X', '1', '0']), ArrayList<String>(['1', '1', '0']), ArrayList<String>(['0', '0', '0'])])
        >>> minesweeper_game.player_map = ArrayList<ArrayList<String>>([ArrayList<String>(['-', '-', '-']), ArrayList<String>(['-', '-', '-']), ArrayList<String>(['-', '-', '-'])])
        >>> minesweeper_game.check_won(minesweeper_game.player_map)
        false
        */
        var i: Int64 = 0
        while i < this.n {
            var j: Int64 = 0
            while j < this.n {
                let hidden = map.get(i).get(j)
                let cell = this.minesweeper_map.get(i).get(j)
                if cell != "X" && hidden == "-" {
                    return false
                }
                j = j + 1
            }
            i = i + 1
        }
        return true
    }

    public func sweep(x: Int64, y: Int64): Any {
        /*
        Sweeps the given position.
        :param x: The x coordinate of the position, Int64.
        :param y: The y coordinate of the position, Int64.
        :return: true if the player has won the game, false otherwise,if the game still continues, return the player map, ArrayList<ArrayList<String>>.
        >>> minesweeper_game = MinesweeperGame(3, 1)
        >>> minesweeper_game.minesweeper_map = ArrayList<ArrayList<String>>([ArrayList<String>(['X', '1', '0']), ArrayList<String>(['1', '1', '0']), ArrayList<String>(['0', '0', '0'])])
        >>> minesweeper_game.player_map = ArrayList<ArrayList<String>>([ArrayList<String>(['-', '-', '-']), ArrayList<String>(['-', '-', '-']), ArrayList<String>(['-', '-', '-'])])
        >>> minesweeper_game.sweep(1, 1)
        [['-', '-', '-'], ['-', '1', '-'], ['-', '-', '-']]
        */
        if x < 0 || x >= this.n || y < 0 || y >= this.n {
            // Out of bounds, return current player map
            return this.player_map
        }

        let playerRow = this.player_map.get(x)
        let current = playerRow.get(y)
        if current != "-" {
            // Already revealed, continue
            return this.player_map
        }

        let cell = this.minesweeper_map.get(x).get(y)
        if cell == "X" {
            // Hit a mine: game lost
            return false
        }

        // Reveal the cell
        playerRow.set(y, cell)
        this.score = this.score + 1

        // If it's zero, flood reveal neighbors
        if cell == "0" {
            this.floodReveal(x, y)
        }

        if this.check_won(this.player_map) {
            return true
        }
        return this.player_map
    }

    func floodReveal(x: Int64, y: Int64): Void {
        var dx: Int64 = -1
        while dx <= 1 {
            var dy: Int64 = -1
            while dy <= 1 {
                if !(dx == 0 && dy == 0) {
                    let nx: Int64 = x + dx
                    let ny: Int64 = y + dy
                    if nx >= 0 && nx < this.n && ny >= 0 && ny < this.n {
                        let prow = this.player_map.get(nx)
                        let pcell = prow.get(ny)
                        if pcell == "-" {
                            let mcell = this.minesweeper_map.get(nx).get(ny)
                            if mcell != "X" {
                                prow.set(ny, mcell)
                                this.score = this.score + 1
                                if mcell == "0" {
                                    this.floodReveal(nx, ny)
                                }
                            }
                        }
                    }
                }
                dy = dy + 1
            }
            dx = dx + 1
        }
    }

    public static func toDigitString(n: Int64): String {
        if n == 0 {
            return "0"
        } else if n == 1 {
            return "1"
        } else if n == 2 {
            return "2"
        } else if n == 3 {
            return "3"
        } else if n == 4 {
            return "4"
        } else if n == 5 {
            return "5"
        } else if n == 6 {
            return "6"
        } else if n == 7 {
            return "7"
        } else {
            return "8"
        }
    }
}

import std.collection.ArrayList
import std.collection.HashMap
import std.time.DateTime
import std.math.abs

class MovieBookingSystem {

    /*
    this is a class as movie booking system, which allows to add movies, book tickets and check the available movies within a given time range. 
    */

    let movies: ArrayList<HashMap<String, Any>>

    public init() {
        /*
        Initialize movies contains the information about movies
        >>> system.movies
        [{'name': 'Batman', 'price': 49.9, 'start_time': DateTime.parse("2023/01/01 17:05", "yyyy/MM/dd HH:mm"), 'end_time': DateTime.parse("2023/01/01 19:25", "yyyy/MM/dd HH:mm"),
        'seats': ArrayList<ArrayList<Int64>>([ArrayList<Int64>([0, 0, 0]),
            ArrayList<Int64>([0, 0, 0]),
            ArrayList<Int64>([0, 0, 0])
            ])}]
        */
        movies = ArrayList<HashMap<String, Any>>()
    }

    public func add_movie(name: String, price: Float64, start_time: String, end_time: String, n: Int64): Unit {
        /*
        Add a new movie into this.movies
        :param name: String, movie name
        :param price: Float64, price for one ticket
        :param start_time: String
        :param end_time: String
        :param n: Int64, the size of seats(n*n)
        >>> system.add_movie('Batman', 49.9, '2023/01/01 17:05', '2023/01/01 19:25', 3)
        >>> system.movies
        [{'name': 'Batman', 'price': 49.9, 'start_time': DateTime.parse("2023/01/01 17:05", "yyyy/MM/dd HH:mm"), 'end_time': DateTime.parse("2023/01/01 19:25", "yyyy/MM/dd HH:mm"),
        'seats': ArrayList<ArrayList<Int64>>([ArrayList<Int64>([0, 0, 0]),
            ArrayList<Int64>([0, 0, 0]),
            ArrayList<Int64>([0, 0, 0])
            ])}]
        */
        let startDt = DateTime.parse(start_time, "yyyy/MM/dd HH:mm")
        let endDt = DateTime.parse(end_time, "yyyy/MM/dd HH:mm")

        let seats = ArrayList<ArrayList<Int64>>()
        var i: Int64 = 0
        while (i < n) {
            let row = ArrayList<Int64>()
            var j: Int64 = 0
            while (j < n) {
                row.add(0)
                j = j + 1
            }
            seats.add(row)
            i = i + 1
        }

        let movie = HashMap<String, Any>()
        movie.put("name", name)
        movie.put("price", price)
        movie.put("start_time", startDt)
        movie.put("end_time", endDt)
        movie.put("seats", seats)

        movies.add(movie)
    }

    public func book_ticket(name: String, seats_to_book: ArrayList<ArrayList<Int64>>): String {
        /*
        Book tickets for a movie. Change the seats value in this.movies if book successfully.
        :param name: String, movie name
        :param seats_to_book: ArrayList<ArrayList<Int64>>, representing seats to book [[row1, col1], [row2, col2], ...]
        :return: String, booking status message. "Movie not found." for no such movie.
                "Booking success." for successfully booking, or "Booking failed." otherwise
        >>> system.add_movie('Batman', 49.9, '2023/01/01 17:05', '2023/01/01 19:25', 3)
        >>> system.book_ticket('Batman', ArrayList<ArrayList<Int64>>([ArrayList<Int64>([0, 0]), ArrayList<Int64>([0, 1])]))
        'Booking success.'
        >>> system.book_ticket('Batman', ArrayList<ArrayList<Int64>>([ArrayList<Int64>([0, 0])]))
        'Booking failed.'
        >>> system.book_ticket('batman', ArrayList<ArrayList<Int64>>([ArrayList<Int64>([0, 0])]))
        'Movie not found.'
        */
        var idx: Int64 = 0
        var foundIndex: Int64 = -1
        while (idx < movies.size()) {
            let m = movies.get(idx)
            let nAny = m.get("name")
            if ((nAny as String) == name) {
                foundIndex = idx
                break
            }
            idx = idx + 1
        }
        if (foundIndex == -1) {
            return "Movie not found."
        }

        let movie = movies.get(foundIndex)
        let seatsAny = movie.get("seats")
        let seats = seatsAny as ArrayList<ArrayList<Int64>>

        // Validate all requested seats first
        var k: Int64 = 0
        while (k < seats_to_book.size()) {
            let pair = seats_to_book.get(k)
            if (pair.size() < 2) {
                return "Booking failed."
            }
            let r = pair.get(0)
            let c = pair.get(1)
            if (r < 0 || c < 0) {
                return "Booking failed."
            }
            if (r >= seats.size()) {
                return "Booking failed."
            }
            let rowList = seats.get(r)
            if (c >= rowList.size()) {
                return "Booking failed."
            }
            if (rowList.get(c) != 0) {
                return "Booking failed."
            }
            k = k + 1
        }

        // All valid; perform booking
        k = 0
        while (k < seats_to_book.size()) {
            let pair = seats_to_book.get(k)
            let r = pair.get(0)
            let c = pair.get(1)
            let rowList = seats.get(r)
            rowList.set(c, 1)
            k = k + 1
        }

        // Persist seats back (not strictly necessary if reference, but keep explicit)
        movie.put("seats", seats)
        movies.set(foundIndex, movie)

        return "Booking success."
    }

    public func available_movies(start_time: String, end_time: String): ArrayList<String> {
        /*
        Get a list of available movies within the specified time range
        :param start_time: String, start time in yyyy/MM/dd HH:mm format
        :param end_time: String, end time in yyyy/MM/dd HH:mm format
        :return: ArrayList<String>, names of available movies
        >>> system.add_movie('Batman', 49.9, '2023/01/01 17:05', '2023/01/01 19:25', 3)
        >>> system.available_movies('2023/01/01 12:00', '2023/01/01 22:00')
        ['Batman']
        */
        let rangeStart = DateTime.parse(start_time, "yyyy/MM/dd HH:mm")
        let rangeEnd = DateTime.parse(end_time, "yyyy/MM/dd HH:mm")

        let result = ArrayList<String>()
        var i: Int64 = 0
        while (i < movies.size()) {
            let m = movies.get(i)
            let st = m.get("start_time") as DateTime
            let et = m.get("end_time") as DateTime

            // Movie is available if fully within the provided range
            // Using compareTo: >= 0 means st >= rangeStart, <= 0 means et <= rangeEnd
            var within: Bool = false
            if (st.compareTo(rangeStart) >= 0 && et.compareTo(rangeEnd) <= 0) {
                within = true
            }

            if (within) {
                result.add(m.get("name") as String)
            }
            i = i + 1
        }
        return result
    }
}

import std.random.Random
import std.collection.ArrayList

class MusicPlayer {

    /*
    This is a class as a music player that provides to play, stop, add songs, remove songs, set volume, shuffle, and switch to the next or previous song.
    */

    var playlist: ArrayList<String>
    var current_song: Option<String>
    var volume: Int64

    public init() {
        /*
        Initializes the music player with an empty playlist, no current song, and a default volume of 50.
        */
        this.playlist = ArrayList<String>()
        this.current_song = None
        this.volume = 50
    }

    public func add_song(song: String): Unit {
        /*
        Adds a song to the playlist.
        :param song: The song to add to the playlist, String.
        >>> musicPlayer = MusicPlayer()
        >>> musicPlayer.add_song("song1")
        >>> musicPlayer.playlist
        ['song1']
        */
        this.playlist.add(song)
    }

    public func remove_song(song: String): Unit {
        /*
        Removes a song from the playlist.
        :param song: The song to remove from the playlist, String.
        >>> musicPlayer = MusicPlayer()
        >>> musicPlayer.playlist = ArrayList<String>(["song1", "song2"])
        >>> musicPlayer.remove_song("song1")
        >>> musicPlayer.playlist
        ['song2']
        */
        var idx: Int64 = -1
        var i: Int64 = 0
        let n = this.playlist.size()
        while i < n {
            if this.playlist.get(i) == song {
                idx = i
                break
            }
            i = i + 1
        }
        if idx >= 0 {
            this.playlist.removeAt(idx)
            if this.current_song != None {
                let cur = this.current_song.unwrap()
                if cur == song {
                    this.current_song = None
                }
            }
        }
    }

    public func play(): Option<String> {
        /*
        Plays the current song in the playlist.
        :return: The current song in the playlist, or None if the playlist is empty, Option<String>.
        >>> musicPlayer = MusicPlayer()
        >>> musicPlayer.playlist = ArrayList<String>(["song1", "song2"])
        >>> musicPlayer.current_song = "song1"
        >>> musicPlayer.play()
        'song1'
        */
        if this.playlist.size() == 0 {
            return None
        }
        if this.current_song != None {
            return this.current_song
        }
        let first = this.playlist.get(0)
        this.current_song = Some(first)
        return this.current_song
    }

    public func stop(): Bool {
        /*
        Stops the current song in the playlist.
        :return: true if the current song was stopped, false if there was no current song.
        >>> musicPlayer = MusicPlayer()
        >>> musicPlayer.playlist = ArrayList<String>(["song1", "song2"])
        >>> musicPlayer.current_song = "song1"
        >>> musicPlayer.stop()
        true
        */
        if this.current_song == None {
            return false
        }
        this.current_song = None
        return true
    }

    public func switch_song(): Bool {
        /*
        Switches to the next song in the playlist.
        :return: true if the next song was switched to, false if there was no next song.
        >>> musicPlayer = MusicPlayer()
        >>> musicPlayer.playlist = ArrayList<String>(["song1", "song2"])
        >>> musicPlayer.current_song = "song1"
        >>> musicPlayer.switch_song()
        true
        */
        let size = this.playlist.size()
        if size == 0 {
            return false
        }
        if this.current_song == None {
            // No current song selected; cannot switch to "next"
            return false
        }
        let cur = this.current_song.unwrap()
        // Find current index
        var idx: Int64 = -1
        var i: Int64 = 0
        while i < size {
            if this.playlist.get(i) == cur {
                idx = i
                break
            }
            i = i + 1
        }
        if idx == -1 {
            // current song not in playlist; reset to first
            this.current_song = Some(this.playlist.get(0))
            return true
        }
        if idx + 1 < size {
            this.current_song = Some(this.playlist.get(idx + 1))
            return true
        }
        return false
    }

    public func previous_song(): Bool {
        /*
        Switches to the previous song in the playlist.
        :return: true if the previous song was switched to, false if there was no previous song.
        >>> musicPlayer = MusicPlayer()
        >>> musicPlayer.playlist = ArrayList<String>(["song1", "song2"])
        >>> musicPlayer.current_song = "song2"
        >>> musicPlayer.previous_song()
        true
        */
        let size = this.playlist.size()
        if size == 0 {
            return false
        }
        if this.current_song == None {
            return false
        }
        let cur = this.current_song.unwrap()
        // Find current index
        var idx: Int64 = -1
        var i: Int64 = 0
        while i < size {
            if this.playlist.get(i) == cur {
                idx = i
                break
            }
            i = i + 1
        }
        if idx == -1 {
            // current song not in playlist; reset to first
            this.current_song = Some(this.playlist.get(0))
            return true
        }
        if idx - 1 >= 0 {
            this.current_song = Some(this.playlist.get(idx - 1))
            return true
        }
        return false
    }

    public func set_volume(volume: Int64): Bool {
        /*
        Sets the volume of the music player,ifthe volume is between 0 and 100 is valid.
        :param volume: The volume to set the music player to,Int64.
        :return: true if the volume was set, false if the volume was invalid.
        >>> musicPlayer = MusicPlayer()
        >>> musicPlayer.set_volume(50)
        true
        >>> musicPlayer.volume
        50
        */
        if volume < 0 || volume > 100 {
            return false
        }
        this.volume = volume
        return true
    }

    public func shuffle(): Bool {
        /*
        Shuffles the playlist.
        :return: true if the playlist was shuffled, false if the playlist was empty.
        >>> musicPlayer = MusicPlayer()
        >>> musicPlayer.playlist = ArrayList<String>(["song1", "song2"])
        >>> musicPlayer.shuffle()
        true
        */
        let n = this.playlist.size()
        if n <= 1 {
            return n == 1
        }
        let rng = Random()
        var i: Int64 = n - 1
        while i > 0 {
            // Assume rng.nextInt(min, max) returns Int64 in [min, max]
            let j = rng.nextInt(0, i)
            if j != i {
                let a = this.playlist.get(i)
                let b = this.playlist.get(j)
                this.playlist.set(i, b)
                this.playlist.set(j, a)
            }
            i = i - 1
        }
        return true
    }
}

import std.collection.ArrayList

class NLPDataProcessor {

    /*
    The class processes NLP data by removing stop words from a list of strings using a pre-defined stop word list.
    */

    public func construct_stop_word_list(): ArrayList<String> {
        /*
        Construct a stop word list including 'a', 'an', 'the'.
        :return: a list of stop words
        >>> nlp_data_processor = NLPDataProcessor()
        >>> nlp_data_processor.construct_stop_word_list()
        ['a', 'an', 'the']
        */
        let stop_words = ArrayList<String>()
        stop_words.add("a")
        stop_words.add("an")
        stop_words.add("the")
        return stop_words
    }

    public func remove_stop_words(string_list: ArrayList<String>, stop_word_list: ArrayList<String>): ArrayList<ArrayList<String>> {
        /*
        Remove all the stop words from the list of strings.
        :param string_list: a list of strings
        :param stop_word_list: a list of stop words
        :return: a list of words without stop words
        >>> nlp_data_processor = NLPDataProcessor()
        >>> nlp_data_processor.process(ArrayList<String>(['This is a test.']), ArrayList<String>(['a', 'an', 'the']))
        [['This', 'is', 'test.']]
        */
        let result = ArrayList<ArrayList<String>>()
        for s in string_list {
            let tokens = ArrayList<String>()
            // Split on spaces; keep punctuation attached to tokens
            for token in s.split(" ") {
                // Skip empty tokens from multiple spaces
                if token != "" && !stop_word_list.contains(token) {
                    tokens.add(token)
                }
            }
            result.add(tokens)
        }
        return result
    }

    public func process(string_list: ArrayList<String>): ArrayList<ArrayList<String>> {
        /*
        Construct a stop word list including 'a', 'an', 'the', and remove all the stop words from the list of strings.
        :param string_list: a list of strings
        :return: a list of words without stop words
        >>> nlp_data_processor = NLPDataProcessor()
        >>> NLPDataProcessor.process(ArrayList<String>(['This is a test.']))
        [['This', 'is', 'test.']]
        */
        let stop_words = self.construct_stop_word_list()
        return self.remove_stop_words(string_list, stop_words)
    }
}

import std.collection.ArrayList
import std.collection.HashMap
import std.regex.Regex
import std.sort.sort
import std.unicode.UnicodeStringExtension

class NLPDataProcessor2 {

    /*
    The class processes NLP data by extracting words from a list of strings, calculating the frequency of each word, and returning the top 5 most frequent words.
    */

    public func process_data(string_list: ArrayList<String>): ArrayList<ArrayList<String>> {
        /*
        keep only English letters and spaces in the string, then convert the string to lower case, and then split the string into a list of words.
        :param string_list: a list of strings
        :return: words_list: a list of words lists
        >>> NLPDataProcessor.process_data(ArrayList<String>(['This is a test.']))
        [['this', 'is', 'a', 'test']]
        */
        let words_list = ArrayList<ArrayList<String>>()

        let nonAlpha = Regex("[^A-Za-z ]+")
        let multiSpace = Regex("\\s+")

        for (s in string_list) {
            // Replace non-letters with space, collapse multiple spaces, lowercase, and trim
            var cleaned = nonAlpha.replace(s, " ")
            cleaned = multiSpace.replace(cleaned, " ")
            cleaned = cleaned.toLowerCase()
            cleaned = cleaned.trim()

            let tokens = ArrayList<String>()
            if (cleaned.length() > 0) {
                // Split by single space (already collapsed)
                let parts = cleaned.split(" ")
                for (p in parts) {
                    if (p.length() > 0) {
                        tokens.add(p)
                    }
                }
            }
            words_list.add(tokens)
        }

        return words_list
    }

    public func calculate_word_frequency(words_list: ArrayList<ArrayList<String>>): HashMap<String, Int64> {
        /*
        Calculate the word frequency of each word in the list of words list, and sort the word frequency dictionary by value in descending order.
        :param words_list: a list of words lists
        :return: top 5 word frequency dictionary, a dictionary of word frequency, key is word, value is frequency
        >>> NLPDataProcessor.calculate_word_frequency(ArrayList<ArrayList<String>>([ArrayList<String>(['this', 'is', 'a', 'test']), ArrayList<String>(['this', 'is', 'another', 'test'])]))
        {'this': 2, 'is': 2, 'test': 2, 'a': 1, 'another': 1}
        */
        let freq = HashMap<String, Int64>()

        for (lst in words_list) {
            for (w in lst) {
                if (freq.containsKey(w)) {
                    let current = freq.get(w)
                    freq.put(w, current + Int64(1))
                } else {
                    freq.put(w, Int64(1))
                }
            }
        }

        // Select top 5 by scanning to avoid relying on map ordering or comparator availability.
        let keys = ArrayList<String>()
        for (k in freq.keys()) {
            keys.add(k)
        }

        let result = HashMap<String, Int64>()
        var added: Int32 = 0
        while (added < 5 && keys.size() > 0) {
            var maxIdx: Int32 = 0
            var maxKey = keys.get(0)
            var maxVal = freq.get(maxKey)

            var i: Int32 = 1
            while (i < keys.size()) {
                let k = keys.get(i)
                let v = freq.get(k)
                if (v > maxVal) {
                    maxVal = v
                    maxKey = k
                    maxIdx = i
                } else if (v == maxVal) {
                    // Tie-breaker: lex ascending
                    if (k.compareTo(maxKey) < 0) {
                        maxVal = v
                        maxKey = k
                        maxIdx = i
                    }
                }
                i = i + 1
            }

            result.put(maxKey, maxVal)
            keys.removeAt(maxIdx)
            added = added + 1
        }

        return result
    }

    public func process(string_list: ArrayList<String>): HashMap<String, Int64> {
        /*
        keep only English letters and spaces in the string, then convert the string to lower case, and then split the string into a list of words. Calculate the word frequency of each word in the list of words list, and sort the word frequency dictionary by value in descending order.
        :param string_list: a list of strings
        :return: top 5 word frequency dictionary, a dictionary of word frequency, key is word, value is frequency
        >>> NLPDataProcessor.process(ArrayList<String>(['This is a test.', 'This is another test.']))
        {'this': 2, 'is': 2, 'test': 2, 'a': 1, 'another': 1}
        */
        let words_list = this.process_data(string_list)
        return this.calculate_word_frequency(words_list)
    }
}

import std.convert.Formattable
import std.convert.Parsable
import std.convert.RadixConvertible

class NumberConverter {

    /*
    The class allows to convert  decimal to binary, octal and hexadecimal repectively and contrarily
    */

    public static func decimal_to_binary(decimal_num: Int64): String {
        /*
        Convert a number from decimal format to binary format.
        :param decimal_num: Int64, decimal number
        :return: String, the binary representation of an integer.
        >>> NumberConverter.decimal_to_binary(42423)
        '1010010110110111'
        */
        return decimal_num.toString(radix: 2)
    }

    public static func binary_to_decimal(binary_num: String): Int64 {
        /*
        Convert a number from binary format to decimal format.
        :param binary_num: String, binary number
        :return: Int64, the decimal representation of binary number str.
        >>> NumberConverter.binary_to_decimal('1010010110110111')
        42423
        */
        return Int64.parse(binary_num, radix: 2)
    }

    public static func decimal_to_octal(decimal_num: Int64): String {
        /*
        Convert a number from decimal format to octal format.
        :param decimal_num: Int64, decimal number
        :return: String, the octal representation of an integer.
        >>> NumberConverter.decimal_to_octal(42423)
        '122667'
        */
        return decimal_num.toString(radix: 8)
    }

    public static func octal_to_decimal(octal_num: String): Int64 {
        /*
        Convert a number from octal format to decimal format.
        :param octal_num: String, octal number
        :return: Int64, the decimal representation of octal number str.
        >>> NumberConverter.octal_to_decimal('122667')
        42423
        */
        return Int64.parse(octal_num, radix: 8)
    }

    public static func decimal_to_hex(decimal_num: Int64): String {
        /*
        Convert a number from decimal format to hex format.
        :param decimal_num: Int64, decimal number
        :return hex_num: String, the hex representation of an integer.
        >>> NumberConverter.decimal_to_hex(42423)
        'a5b7'
        */
        return decimal_num.toString(radix: 16)
    }

    public static func hex_to_decimal(hex_num: String): Int64 {
        /*
        Convert a number from hex format to decimal format.
        :param hex_num: String, hex num
        :return: Int64, the decimal representation of hex number str.
        >>> NumberConverter.hex_to_decimal('a5b7')
        42423
        */
        return Int64.parse(hex_num, radix: 16)
    }
}

import std.convert.Parsable
import std.unicode.UnicodeStringExtension

class NumberWordFormatter {

    /*
    This is a class that provides to convert numbers into their corresponding English word representation, including handling the conversion of both the integer and decimal parts, and incorporating appropriate connectors and units.
    */

    let NUMBER: Array<String>
    let NUMBER_TEEN: Array<String>
    let NUMBER_TEN: Array<String>
    let NUMBER_MORE: Array<String>
    let NUMBER_SUFFIX: Array<String>

    public init() {
        /*
        Initialize NumberWordFormatter object.
        */
        this.NUMBER = ["", "ONE", "TWO", "THREE", "FOUR", "FIVE", "SIX", "SEVEN", "EIGHT", "NINE"]
        this.NUMBER_TEEN = ["TEN", "ELEVEN", "TWELVE", "THIRTEEN", "FOURTEEN", "FIFTEEN", "SIXTEEN", "SEVENTEEN",
                            "EIGHTEEN",
                            "NINETEEN"]
        this.NUMBER_TEN = ["TEN", "TWENTY", "THIRTY", "FORTY", "FIFTY", "SIXTY", "SEVENTY", "EIGHTY", "NINETY"]
        this.NUMBER_MORE = ["", "THOUSAND", "MILLION", "BILLION"]
        this.NUMBER_SUFFIX = ["k", "w", "", "m", "", "", "b", "", "", "t", "", "", "p", "", "", "e"]
    }

    public func format(x: Option<String>): String {
        /*
        Converts a number into words format
        :param x: Option<String>, the number to be converted into words format
        :return: String, the number in words format
        >>> formatter = NumberWordFormatter()
        >>> formatter.format("123456")
        "ONE HUNDRED AND TWENTY THREE THOUSAND FOUR HUNDRED AND FIFTY SIX ONLY"
        */
        if x.isNone() {
            return ""
        }
        let s = x.unwrap()
        return this.format_string(s)
    }

    public func format_string(x: String): String {
        /*
        Converts a string representation of a number into words format
        :param x: String, the string representation of a number
        :return: String, the number in words format
        >>> formatter = NumberWordFormatter()
        >>> formatter.format_string("123456")
        "ONE HUNDRED AND TWENTY THREE THOUSAND FOUR HUNDRED AND FIFTY SIX ONLY"
        */
        var s = this._safeTrim(x)
        if s.length() == 0 {
            return ""
        }
        // normalize, remove separators
        s = this._replaceAll(s, ",", "")
        s = this._replaceAll(s, "_", "")
        s = this._replaceAll(s, " ", "")

        var negative = false
        if this._startsWith(s, "-") {
            negative = true
            s = s.substring(1, s.length())
        } else if this._startsWith(s, "+") {
            s = s.substring(1, s.length())
        }

        // Split integer and decimal part
        var intPart = s
        var decPart = ""
        let dotPos = this._indexOf(s, ".")
        if dotPos >= 0 {
            intPart = s.substring(0, dotPos)
            decPart = s.substring(dotPos + 1, s.length())
        }

        // Remove leading zeros in integer part
        intPart = this._stripLeadingZeros(intPart)
        if intPart.length() == 0 {
            intPart = "0"
        }

        // Validate numeric characters
        if !this._isAllDigits(intPart) {
            return ""
        }
        if decPart.length() > 0 && !this._isAllDigits(decPart) {
            return ""
        }

        // Convert integer part
        var intWords = ""
        if intPart == "0" {
            intWords = "ZERO"
        } else {
            intWords = this._convertIntegerToWords(intPart)
        }

        // Convert decimal part if any
        var decWords = ""
        if decPart.length() > 0 {
            // remove trailing zeros of decimal part if all zeros then ignore
            var allZero = true
            var i = 0
            while i < decPart.length() {
                let c = decPart.charAt(i)
                if c != '0' {
                    allZero = false
                    break
                }
                i = i + 1
            }
            if !allZero {
                decWords = "POINT" + this._digitsToWords(decPart)
            }
        }

        var result = ""
        if negative {
            result = "MINUS " + intWords
        } else {
            result = intWords
        }

        if decWords.length() > 0 {
            result = result + " " + decWords
        }

        result = this._normalizeSpaces(result + " ONLY")
        return result
    }

    public func trans_two(s: String): String {
        /*
        Converts a two-digit number into words format
        :param s: String, the two-digit number
        :return: String, the number in words format
        >>> formatter = NumberWordFormatter()
        >>> formatter.trans_two("23")
        "TWENTY THREE"
        */
        var t = s
        if t.length() == 0 {
            return ""
        }
        if t.length() == 1 {
            // single digit
            let d = this._digitValue(t.charAt(0))
            return this.NUMBER[d]
        }
        // Ensure exactly two chars
        if t.length() > 2 {
            t = t.substring(t.length() - 2, t.length())
        }
        // remove leading zero case like "03"
        let a = this._digitValue(t.charAt(0))
        let b = this._digitValue(t.charAt(1))
        if a == 0 && b == 0 {
            return ""
        }
        if a == 0 {
            return this.NUMBER[b]
        }
        if a == 1 {
            // 10-19
            return this.NUMBER_TEEN[b]
        }
        var res = this.NUMBER_TEN[a - 1]
        if b != 0 {
            res = res + " " + this.NUMBER[b]
        }
        return res
    }

    public func trans_three(s: String): String {
        /*
        Converts a three-digit number into words format
        :param s: String, the three-digit number
        :return: String, the number in words format
        >>> formatter = NumberWordFormatter()
        >>> formatter.trans_three("123")
        "ONE HUNDRED AND TWENTY THREE"
        */
        var t = s
        if t.length() == 0 {
            return ""
        }
        if t.length() < 3 {
            // pad left with zeros
            t = this._leftPadZeros(t, 3)
        } else if t.length() > 3 {
            t = t.substring(t.length() - 3, t.length())
        }
        let h = this._digitValue(t.charAt(0))
        let tensOnes = t.substring(1, 3)
        var res = ""
        if h > 0 {
            res = this.NUMBER[h] + " HUNDRED"
            let rest = this.trans_two(tensOnes)
            if rest.length() > 0 {
                res = res + " AND " + rest
            }
            return res
        } else {
            return this.trans_two(tensOnes)
        }
    }

    public func parse_more(i: Int64): String {
        /*
        Parses the thousand/million/billion suffix based on the index
        :param i: Int64, the index representing the magnitude (thousand, million, billion)
        :return: String, the corresponding suffix for the magnitude
        >>> formatter = NumberWordFormatter()
        >>> formatter.parse_more(1)
        "THOUSAND"
        */
        if i < 0 {
            return ""
        }
        let idx = i as Int64
        if idx >= 0 && idx < this.NUMBER_MORE.length() as Int64 {
            return this.NUMBER_MORE[idx as Int]
        }
        return ""
    }

    // Internal helpers

    private func _convertIntegerToWords(intPart: String): String {
        // Split into groups of three from right
        var groups: Array<String> = []
        var i = intPart.length()
        while i > 0 {
            let start = if i - 3 >= 0 { i - 3 } else { 0 }
            let grp = intPart.substring(start, i)
            groups.append(this._leftPadZeros(grp, 3))
            i = start
        }
        // Now groups[0] is least significant
        var wordsParts: Array<String> = []
        var gIdx = groups.length() - 1
        while gIdx >= 0 {
            let groupStr = groups[gIdx]
            if !this._isAllZeros(groupStr) {
                let t = this.trans_three(groupStr)
                let suffix = this.parse_more((groups.length() - 1 - gIdx) as Int64)
                var w = t
                if suffix.length() > 0 {
                    w = w + " " + suffix
                }
                wordsParts.append(w)
            }
            gIdx = gIdx - 1
        }
        // Join with space
        var res = ""
        var j = 0
        while j < wordsParts.length() {
            if res.length() == 0 {
                res = wordsParts[j]
            } else {
                res = res + " " + wordsParts[j]
            }
            j = j + 1
        }
        if res.length() == 0 {
            res = "ZERO"
        }
        return res
    }

    private func _digitsToWords(dec: String): String {
        var res = ""
        var i = 0
        while i < dec.length() {
            let d = this._digitValue(dec.charAt(i))
            let word = this.NUMBER[d]
            if word.length() > 0 {
                res = res + " " + word
            } else {
                res = res + " ZERO"
            }
            i = i + 1
        }
        return res
    }

    private func _stripLeadingZeros(s: String): String {
        var i = 0
        while i < s.length() - 1 && s.charAt(i) == '0' {
            i = i + 1
        }
        return s.substring(i, s.length())
    }

    private func _isAllDigits(s: String): Bool {
        if s.length() == 0 {
            return false
        }
        var i = 0
        while i < s.length() {
            let c = s.charAt(i)
            if c < '0' || c > '9' {
                return false
            }
            i = i + 1
        }
        return true
    }

    private func _isAllZeros(s: String): Bool {
        if s.length() == 0 {
            return true
        }
        var i = 0
        while i < s.length() {
            if s.charAt(i) != '0' {
                return false
            }
            i = i + 1
        }
        return true
    }

    private func _replaceAll(s: String, target: String, repl: String): String {
        var res = s
        // naive replace all
        while true {
            let idx = this._indexOf(res, target)
            if idx < 0 {
                break
            }
            res = res.substring(0, idx) + repl + res.substring(idx + target.length(), res.length())
        }
        return res
    }

    private func _indexOf(s: String, sub: String): Int {
        // simple search
        var i = 0
        while i <= s.length() - sub.length() {
            var match = true
            var j = 0
            while j < sub.length() {
                if s.charAt(i + j) != s.charAt(i + j) { // placeholder, fixed below
                    match = false
                    break
                }
                j = j + 1
            }
            // Correct character comparison:
            match = true
            j = 0
            while j < sub.length() {
                if s.charAt(i + j) != sub.charAt(j) {
                    match = false
                    break
                }
                j = j + 1
            }
            if match {
                return i
            }
            i = i + 1
        }
        return -1
    }

    private func _startsWith(s: String, prefix: String): Bool {
        if prefix.length() > s.length() {
            return false
        }
        var i = 0
        while i < prefix.length() {
            if s.charAt(i) != prefix.charAt(i) {
                return false
            }
            i = i + 1
        }
        return true
    }

    private func _leftPadZeros(s: String, n: Int): String {
        var res = s
        while res.length() < n {
            res = "0" + res
        }
        return res
    }

    private func _digitValue(c: Char): Int {
        if c >= '0' && c <= '9' {
            return (c as Int) - ('0' as Int)
        }
        return 0
    }

    private func _safeTrim(s: String): String {
        // basic trim for spaces and tabs
        var start = 0
        var end = s.length()
        while start < end && (s.charAt(start) == ' ' || s.charAt(start) == '\t' || s.charAt(start) == '\n' || s.charAt(start) == '\r') {
            start = start + 1
        }
        while end > start && (s.charAt(end - 1) == ' ' || s.charAt(end - 1) == '\t' || s.charAt(end - 1) == '\n' || s.charAt(end - 1) == '\r') {
            end = end - 1
        }
        return s.substring(start, end)
    }

    private func _normalizeSpaces(s: String): String {
        // collapse multiple spaces into one
        var res = ""
        var lastSpace = false
        var i = 0
        while i < s.length() {
            let c = s.charAt(i)
            if c == ' ' {
                if !lastSpace {
                    res = res + " "
                    lastSpace = true
                }
            } else {
                res = res + s.substring(i, i + 1)
                lastSpace = false
            }
            i = i + 1
        }
        // trim
        return this._safeTrim(res)
    }
}

import std.collection.ArrayList
import std.convert.RadixConvertible
import std.text.StringBuilder

class NumericEntityUnescaper {

    /*
    This is a class that provides functionality to replace numeric entities with their corresponding characters in a given string.
    */

    public init() {}

    public func replace(string: String): String {
        /*
        Replaces numeric character references (HTML entities) in the input string with their corresponding Unicode characters.
        :param string: String, the input string containing numeric character references.
        :return: String, the input string with numeric character references replaced with their corresponding Unicode characters.
        >>> unescaper = NumericEntityUnescaper()
        >>> unescaper.replace("&#65;&#66;&#67;")
        'ABC'

        */
        let len = string.length
        var i: Int = 0
        var sb = StringBuilder()

        while i < len {
            let ch = string.charAt(i)
            if ch == r'&' && (i + 1) < len && string.charAt(i + 1) == r'#' {
                var j: Int = i + 2
                var base: Int = 10

                if j < len {
                    let maybeHex = string.charAt(j)
                    if maybeHex == r'x' || maybeHex == r'X' {
                        base = 16
                        j += 1
                    }
                }

                var anyDigits: Bool = false
                var value: Int = 0

                while j < len {
                    let c = string.charAt(j)
                    var d: Int = -1
                    if base == 10 {
                        if NumericEntityUnescaper.is_digit_char(c) {
                            d = NumericEntityUnescaper.dec_value(c)
                        }
                    } else {
                        if NumericEntityUnescaper.is_hex_char(c) {
                            d = NumericEntityUnescaper.hex_value(c)
                        }
                    }
                    if d < 0 {
                        break
                    }
                    anyDigits = true
                    value = value * base + d
                    j += 1
                }

                if anyDigits && j < len && string.charAt(j) == r';' {
                    if NumericEntityUnescaper.is_valid_code_point(value) {
                        let r = Rune.fromCodePoint(value)
                        sb.appendRune(r)
                    } else {
                        var k: Int = i
                        while k <= j {
                            sb.appendRune(string.charAt(k))
                            k += 1
                        }
                    }
                    i = j + 1
                    continue
                } else {
                    sb.appendRune(r'&')
                    i += 1
                    continue
                }
            } else {
                sb.appendRune(ch)
                i += 1
            }
        }

        return sb.toString()
    }

    public static func is_hex_char(char: Rune): Bool {
        if char >= r'0' && char <= r'9' { return true }
        if char >= r'a' && char <= r'f' { return true }
        if char >= r'A' && char <= r'F' { return true }
        return false
    }

    // Private helpers

    private static func is_digit_char(char: Rune): Bool {
        return char >= r'0' && char <= r'9'
    }

    private static func dec_value(char: Rune): Int {
        if char == r'0' { return 0 }
        if char == r'1' { return 1 }
        if char == r'2' { return 2 }
        if char == r'3' { return 3 }
        if char == r'4' { return 4 }
        if char == r'5' { return 5 }
        if char == r'6' { return 6 }
        if char == r'7' { return 7 }
        if char == r'8' { return 8 }
        if char == r'9' { return 9 }
        return -1
    }

    private static func hex_value(char: Rune): Int {
        if char == r'0' { return 0 }
        if char == r'1' { return 1 }
        if char == r'2' { return 2 }
        if char == r'3' { return 3 }
        if char == r'4' { return 4 }
        if char == r'5' { return 5 }
        if char == r'6' { return 6 }
        if char == r'7' { return 7 }
        if char == r'8' { return 8 }
        if char == r'9' { return 9 }
        if char == r'a' || char == r'A' { return 10 }
        if char == r'b' || char == r'B' { return 11 }
        if char == r'c' || char == r'C' { return 12 }
        if char == r'd' || char == r'D' { return 13 }
        if char == r'e' || char == r'E' { return 14 }
        if char == r'f' || char == r'F' { return 15 }
        return -1
    }

    private static func is_valid_code_point(cp: Int): Bool {
        if cp < 0 { return false }
        if cp > 0x10FFFF { return false }
        if cp >= 0xD800 && cp <= 0xDFFF { return false }
        return true
    }
}

